import type { BankQuestion } from "@/lib/bank";

/** Operations, Supply Chain & Business Analytics (Management & Commerce): 643 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"mgmt-operations-analytics-1","question":"A bottling unit has a design capacity of 500 crates per day and an effective capacity of 400 crates per day. Last week it averaged 340 crates per day. What was its efficiency?","options":["85%","117.6%","80%","68%"],"answer":0,"explanation":"Efficiency = actual output ÷ effective capacity = 340 ÷ 400 = 85%. Utilisation uses design capacity instead: 340 ÷ 500 = 68%.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-2","question":"Customers arrive at a pharmacy at an average rate of 40 per hour and spend an average of 15 minutes inside. On average, how many customers are inside the pharmacy at any moment?","options":["25","2.67","600","10"],"answer":3,"explanation":"Little's law: L = λ × W = 40 per hour × (15/60) hour = 10. Multiplying 40 by 15 without converting minutes to hours gives 600.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-3","question":"A plant runs one 7.5-hour shift with 30 minutes of breaks. Daily customer demand is 840 units. What is the takt time?","options":["45 seconds","30 seconds","32.1 seconds","2 minutes"],"answer":1,"explanation":"Available time = 450 − 30 = 420 minutes = 25,200 s. Takt = available time ÷ demand = 25,200 ÷ 840 = 30 s. Forgetting the breaks gives 27,000 ÷ 840 ≈ 32.1 s.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-4","question":"A three-stage process: Stage 1 has one machine taking 6 min per unit; Stage 2 has two identical machines in parallel, each taking 15 min per unit; Stage 3 has one machine taking 5 min per unit. What is the maximum output in an 8-hour shift?","options":["80","32","64","96"],"answer":2,"explanation":"Capacities per hour: Stage 1 = 60/6 = 10, Stage 2 = 2 × 60/15 = 8, Stage 3 = 60/5 = 12. The bottleneck is Stage 2 at 8 units/hour, so output = 8 × 8 = 64. Ignoring the parallel machine gives 4 × 8 = 32.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-5","question":"A distribution centre holds an average of 6,000 units and ships 1,200 units per week. Assuming 52 weeks a year, what is its annual inventory turnover?","options":["10.4","5","20.8","0.2"],"answer":0,"explanation":"Little's law: average time in stock W = I ÷ throughput = 6,000 ÷ 1,200 = 5 weeks. Turns per year = 52 ÷ 5 = 10.4. 5 is the flow time in weeks, not the turnover.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-6","question":"An assembly line must produce 1,600 units in 480 productive minutes per day. The six tasks take 10, 12, 8, 15, 7 and 9 seconds. What is the theoretical minimum number of workstations?","options":["3","5","4","6"],"answer":2,"explanation":"Takt (cycle) time = 480 × 60 ÷ 1,600 = 18 s. Work content = 61 s. Minimum stations = ⌈61 ÷ 18⌉ = ⌈3.39⌉ = 4. Rounding down to 3 is the classic error: stations must be rounded up.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-7","question":"For the same line (work content 61 s, cycle time 18 s), precedence constraints force the planner to use 5 stations. What is the balance delay?","options":["18.7%","32.2%","15.3%","67.8%"],"answer":1,"explanation":"Efficiency = work content ÷ (stations × cycle time) = 61 ÷ (5 × 18) = 67.8%. Balance delay = 1 − efficiency = 32.2%. 15.3% is the delay with 4 stations; 18.7% wrongly uses the longest task (15 s) as cycle time.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-8","question":"A loan-processing centre receives 120 applications per week and has on average 360 applications in process. Management wants the average processing time cut to 1.5 weeks without changing the arrival rate. By how many applications must average work-in-process fall?","options":["120","240","90","180"],"answer":3,"explanation":"Current W = 360 ÷ 120 = 3 weeks. Target WIP = 120 × 1.5 = 180. Reduction = 360 − 180 = 180 applications.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-9","question":"A serial line has three stages. Stage 1: capacity 100 units/hr, yield 95%. Stage 2: capacity 90 units/hr, yield 90%. Stage 3: capacity 85 units/hr, yield 98%. Defective units are scrapped immediately after each stage. What is the maximum rate of good finished output?","options":["85.00 units/hr","75.41 units/hr","79.38 units/hr","83.30 units/hr"],"answer":2,"explanation":"Let x enter Stage 1. Stage 2 sees 0.95x ≤ 90 → x ≤ 94.74. Stage 3 sees 0.855x ≤ 85 → x ≤ 99.42. Stage 1 allows x ≤ 100. So x = 94.74 (Stage 2 binds) and good output = 90 × 0.90 × 0.98 = 79.38/hr. Applying the Stage-1 yield again to the bottleneck capacity gives 75.41.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-10","question":"A single-server help desk (M/M/1) receives 12 requests per hour and can serve 15 per hour. What is the average time a request waits in the queue before service starts?","options":["3.2 minutes","16 minutes","20 minutes","4 minutes"],"answer":1,"explanation":"ρ = 12/15 = 0.8. Lq = ρ²/(1 − ρ) = 0.64/0.2 = 3.2. Wq = Lq/λ = 3.2/12 hr = 16 min. 20 min is W (time in system) = 1/(μ − λ); 4 min is the service time alone.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-11","question":"A single-window ticket counter (M/M/1) has an arrival rate of 18 per hour and a service rate of 24 per hour. What is the probability that the counter is idle?","options":["0.25","0.75","0.33","0.43"],"answer":0,"explanation":"ρ = λ/μ = 18/24 = 0.75, the probability the server is busy. P(idle) = P0 = 1 − ρ = 0.25.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-12","question":"Customers arrive at a single drive-through window at 20 per hour (M/M/1). Management wants the average wait in the queue (before ordering) to be at most 6 minutes. What is the smallest whole-number service rate per hour that achieves this?","options":["30","25","27","28"],"answer":3,"explanation":"Wq = λ / [μ(μ − λ)] ≤ 0.1 hr → 20 ≤ 0.1μ(μ − 20) → μ² − 20μ − 200 ≥ 0 → μ ≥ 10 + √300 ≈ 27.32. So μ = 28. μ = 27 gives Wq = 20/(27×7) hr ≈ 6.35 min, too long. 30 is what you get by limiting time in system W = 1/(μ − λ) instead of the queue wait.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-13","question":"A diagnostic clinic sees 30 patients per hour. Every patient passes registration (on average 4 patients there) and a doctor (on average 6 patients), and 60% also visit the lab, where on average 9 patients are present. What is the average time spent in the lab by a patient who visits it?","options":["38 minutes","30 minutes","18 minutes","15 minutes"],"answer":1,"explanation":"Apply Little's law to the lab alone. Flow into the lab = 0.6 × 30 = 18 patients/hr, so W = 9 ÷ 18 hr = 30 min. Dividing by all 30 patients gives 18 min; 38 min is the average time in the whole clinic, (4 + 9 + 6) ÷ 30 hr.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-14","question":"A machine is available for 480 minutes a day. Product A needs 4 minutes and product B 6 minutes on it. Daily demand is 50 units of A and 40 of B. What is the machine's utilisation?","options":["91.7%","87.5%","108.3%","100.0%"],"answer":0,"explanation":"Load = 50 × 4 + 40 × 6 = 200 + 240 = 440 min. Utilisation = 440 ÷ 480 = 91.7%.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-15","question":"Expected monthly demand for a service is 9,000 jobs. The firm wants a capacity cushion of 20% (measured as a share of capacity). What capacity should it plan?","options":["9,200 jobs","10,800 jobs","7,200 jobs","11,250 jobs"],"answer":3,"explanation":"Capacity cushion = 1 − utilisation, so demand = 80% of capacity. Capacity = 9,000 ÷ 0.8 = 11,250. Adding 20% of demand (10,800) understates it, because the cushion is measured against capacity.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-16","question":"Annual demand is 66,000 good units. Each unit needs 12 minutes of machine time. Plants run 250 days a year, 2 shifts of 8 hours, with 85% machine efficiency, and 4% of units started are scrapped. How many machines are needed?","options":["3","4","5","6"],"answer":2,"explanation":"Units to start = 66,000 ÷ 0.96 = 68,750. Hours needed = 68,750 × 12/60 = 13,750. Effective hours per machine = 250 × 2 × 8 × 0.85 = 3,400. Machines = 13,750 ÷ 3,400 = 4.04 → 5. Ignoring scrap gives 13,200 ÷ 3,400 = 3.88 → 4.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-17","question":"A unit's design capacity is 200 units/day. Its utilisation is 75% and its efficiency is 90%. What is its effective capacity (approximately)?","options":["150 units/day","135 units/day","180 units/day","167 units/day"],"answer":3,"explanation":"Actual output = utilisation × design = 0.75 × 200 = 150. Efficiency = actual ÷ effective → effective = 150 ÷ 0.9 ≈ 166.7 ≈ 167 units/day. 150 is the actual output; 135 multiplies both percentages.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-18","question":"Assertion (A): Adding capacity at a non-bottleneck station does not increase the throughput of a serial process.\nReason (R): The throughput of a serial process is set by its slowest resource.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: output is capped by the bottleneck, so extra capacity anywhere else only adds idle time.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-19","question":"Which statements about Little's law (L = λW) are correct?\nI. It holds in steady state whatever the arrival and service-time distributions.\nII. It holds only for first-come-first-served queues.\nIII. It can be applied to any boundary drawn around part of a system.\nIV. λ is the average throughput rate across the boundary.","options":["I and II only","I, III and IV only","I, II, III and IV","II, III and IV only"],"answer":1,"explanation":"Little's law needs only a stable (steady-state) system; it is independent of distributions and of the queue discipline, so II is false. It applies to any subsystem, with λ the flow rate through that boundary.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-20","question":"A plant works 5 days a week, 2 shifts a day. Each 8-hour shift has two 15-minute tea breaks and a 30-minute lunch. Weekly demand is 1,350 units. What is the takt time?","options":["93.3 seconds","200.0 seconds","186.7 seconds","213.3 seconds"],"answer":2,"explanation":"Available per shift = 480 − 60 = 420 min. Weekly = 420 × 2 × 5 = 4200 min. Takt = 4200 ÷ 1,350 = 3.1111 min = 186.7 s. Deducting only lunch gives 4,500/1,350 min = 200 s; ignoring all breaks gives 213.3 s.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-21","question":"Tasks (time in s; immediate predecessors): A 8 (–), B 5 (A), C 6 (A), D 9 (B), E 4 (C), F 7 (D, E), G 3 (F). The cycle time is 12 s. Tasks are assigned to stations using the 'longest eligible task first' rule. What is the efficiency of the resulting line?","options":["70.0%","30.0%","76.4%","87.5%"],"answer":0,"explanation":"Assignment: S1 {A} = 8; S2 {C, B} = 11; S3 {D} = 9 (E no longer fits); S4 {E, F} = 11; S5 {G} = 3. Five stations, so efficiency = 42 ÷ (5 × 12) = 70%. 87.5% assumes the theoretical minimum of ⌈42/12⌉ = 4 stations; 76.4% uses the largest station load (11 s) instead of the cycle time.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-22","question":"A machine needs a 60-minute setup before each batch and then 2 minutes per unit. Downstream demand is 27 units per hour. What is the smallest batch size that lets this machine keep up with demand?","options":["135","243","270","30"],"answer":2,"explanation":"Capacity with batch B = B ÷ (60 + 2B) units per minute. Set it equal to 27/60 = 0.45: B = 0.45(60 + 2B) = 27 + 0.9B → 0.1B = 27 → B = 270. Note that even an infinite batch cannot exceed 30 units/hr (1 per 2 min).","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-23","question":"A process has a throughput of 50 units per hour and a flow time of 3 hours. If a WIP cap reduces average work-in-process to 100 units while throughput stays the same, what is the new flow time?","options":["3 hours","4.5 hours","1.5 hours","2 hours"],"answer":3,"explanation":"Current WIP = 50 × 3 = 150. With WIP = 100 and λ = 50, W = 100 ÷ 50 = 2 hours.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-24","question":"A distributor has annual sales of ₹64 crore, cost of goods sold of ₹48 crore and an average inventory (at cost) of ₹6 crore. Using a 365-day year, how many days of inventory does it hold?","options":["34.2 days","45.6 days","8.0 days","12.0 days"],"answer":1,"explanation":"Inventory turnover = COGS ÷ average inventory = 48 ÷ 6 = 8. Days of inventory = 365 ÷ 8 = 45.6. Using sales (64 ÷ 6) mixes a selling-price numerator with a cost denominator and gives 34.2 days.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-25","question":"Products P and Q share two machines, each available 480 min/day. P needs 3 min on M1 and 4 min on M2; Q needs 5 min on M1 and 2 min on M2. Current daily demand is 60 P and 40 Q. By what maximum percentage can both demands be increased in the same proportion?","options":["20.8%","50.0%","26.3%","33.3%"],"answer":2,"explanation":"M1 load = 60×3 + 40×5 = 380 min; M2 load = 60×4 + 40×2 = 320 min. M1 binds: scale ≤ 480/380 = 1.2632, i.e. an increase of 26.3%. 50% is M2's headroom; 20.8% is M1's idle share of 480, not the headroom relative to the load.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-26","question":"Station A takes 10 min per unit and Station B takes 12 min per unit. After Station B, 20% of units fail inspection and go back through Station B once (rework takes the full 12 minutes and always succeeds). What is the line's output in an 8-hour shift?","options":["48.0 units","33.3 units","40.0 units","32.0 units"],"answer":1,"explanation":"Each good unit needs 1.2 passes at B: 1.2 × 12 = 14.4 min. B's capacity = 60/14.4 = 4.167 units/hr (A: 6/hr), so B is the bottleneck. Output = 4.167 × 8 = 33.3 units. 40 ignores rework; 32 treats the 20% as scrap.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-27","question":"A retailer sells ₹30 lakh a month at a 25% gross margin (on sales) and carries an average inventory of ₹45 lakh at cost. Holding cost is 24% a year of inventory value. If inventory days (30-day month) are cut to 40 days at the same sales, what is the annual saving in holding cost?","options":["₹4.8 lakh","₹1.2 lakh","₹15 lakh","₹3.6 lakh"],"answer":3,"explanation":"COGS = 0.75 × 30 = ₹22.5 lakh/month = ₹0.75 lakh/day. Current days = 45 ÷ 0.75 = 60. At 40 days inventory = 40 × 0.75 = ₹30 lakh, freeing ₹15 lakh. Saving = 15 × 0.24 = ₹3.6 lakh. Using sales instead of COGS gives 45 days now, ₹40 lakh at 40 days and only ₹1.2 lakh saved.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-28","question":"Jobs arrive at 10 per hour (M/M/1). Option A: a server who handles 12 jobs/hr, costing ₹200/hr. Option B: a server who handles 15 jobs/hr, costing ₹300/hr. Each job in the system (waiting or in service) costs ₹100 per hour. Which option is cheaper, and what is its total hourly cost?","options":["Option B, ₹500/hr","Option A, ₹617/hr","Option B, ₹433/hr","Option A, ₹700/hr"],"answer":0,"explanation":"L = λ/(μ − λ). A: L = 10/2 = 5 → 200 + 500 = ₹700. B: L = 10/5 = 2 → 300 + 200 = ₹500. B is cheaper. Using Lq (queue only) instead of L gives ₹433 for B, but the cost is charged on every job in the system.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-29","question":"In the Theory of Constraints, which scheduling method paces the whole plant to the bottleneck, protects it with a time buffer and releases material in step with it?","options":["Economic Order Quantity","Kanban","Drum–Buffer–Rope","Material Requirements Planning"],"answer":2,"explanation":"In Drum–Buffer–Rope the bottleneck is the drum that sets the pace, the buffer protects it from upstream disruptions, and the rope ties material release to the drum's rate.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-30","question":"Planned production time is 480 minutes, of which 60 minutes are lost to breakdowns. The ideal cycle time is 0.5 min/unit. The machine produced 700 units, of which 665 were good. What is the OEE?","options":["72.9%","79.2%","83.1%","69.3%"],"answer":3,"explanation":"Availability = 420/480 = 0.875. Performance = (700 × 0.5)/420 = 0.8333. Quality = 665/700 = 0.95. OEE = A × P × Q = 69.3% (check: 665 × 0.5 ÷ 480 = 0.6927). 72.9% leaves out quality.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-31","question":"Monthly sales of a product were 120, 135, 150 and 141 units (oldest first). What is the 3-month moving-average forecast for the next month?","options":["135","142","136.5","141"],"answer":1,"explanation":"Use the latest three months: (135 + 150 + 141) ÷ 3 = 426 ÷ 3 = 142. 136.5 averages all four months.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-32","question":"Sales were 200 (Jan), 220 (Feb) and 250 (Mar). Using a weighted moving average with weights 0.5, 0.3 and 0.2, the heaviest weight on the most recent month, what is the April forecast?","options":["231","216","223.33","250"],"answer":0,"explanation":"F = 0.5 × 250 + 0.3 × 220 + 0.2 × 200 = 125 + 66 + 40 = 231. Putting 0.5 on January instead gives 216; the simple average is 223.33.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-33","question":"Last period's forecast was 500 units and actual demand was 540 units. With exponential smoothing and α = 0.3, what is the next forecast?","options":["520","540","512","528"],"answer":2,"explanation":"F(new) = F + α(A − F) = 500 + 0.3 × 40 = 512. Using 0.7 as the weight on the error gives 528.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-34","question":"The forecast for period 1 was 100. Actual demand in periods 1, 2 and 3 was 110, 95 and 120. Using exponential smoothing with α = 0.2, what is the forecast for period 4?","options":["108.33","115.52","120","104.48"],"answer":3,"explanation":"F2 = 100 + 0.2(110 − 100) = 102; F3 = 102 + 0.2(95 − 102) = 100.6; F4 = 100.6 + 0.2(120 − 100.6) = 104.48. Swapping α and 1 − α (α = 0.8) gives 115.52.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-35","question":"Actual demand for four weeks was 100, 120, 80 and 150; the forecasts were 110, 110, 100 and 140. What is the MAPE?","options":["11.3%","12.5%","11.1%","2.5%"],"answer":1,"explanation":"Absolute % errors (divide by actual): 10/100 = 10%, 10/120 = 8.33%, 20/80 = 25%, 10/150 = 6.67%. MAPE = 50% ÷ 4 = 12.5%. Dividing by the forecast gives 11.3%; total error ÷ total demand (50/450) gives 11.1%.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-36","question":"Forecast errors (actual − forecast) for six months were +5, +8, −3, +7, +6 and +9. Control limits for the tracking signal are ±4. What is the tracking signal and what does it say?","options":["5.05; the method consistently under-forecasts","0.84; the method is in control","32; the method is in control","5.05; the method consistently over-forecasts"],"answer":0,"explanation":"Running sum of errors = 32; MAD = 38/6 = 6.333. TS = 32 ÷ 6.333 = 5.05, beyond +4. Positive errors mean actual > forecast, so the method under-forecasts.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-37","question":"Method X has forecast errors +4, −4, +4, −4. Method Y has errors 0, 0, 0, +12. Which statement is correct?","options":["Y has the lower MAD but the higher MSE","Both have the same MAD and MSE","X has both the lower MAD and the lower MSE","Y has both the lower MAD and the lower MSE"],"answer":0,"explanation":"X: MAD = 4, MSE = 16. Y: MAD = 12/4 = 3, MSE = 144/4 = 36. MSE squares errors, so it punishes Y's single large miss.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-38","question":"Quarterly sales (Q1–Q4) were 80, 120, 100, 140 in Year 1 and 100, 140, 110, 170 in Year 2. Seasonal indices are computed as (average for the quarter) ÷ (average of all quarters). If total sales next year are forecast at 1,040, what is the Q4 forecast?","options":["340","201.3","260","335.8"],"answer":3,"explanation":"Quarter averages: 90, 130, 105, 155; overall average = 120. Q4 index = 155/120 = 1.2917. Q4 forecast = (1,040/4) × 1.2917 = 335.8. Dividing by the index (deseasonalising) gives 201.3; 340 uses only Year 2's Q4 share.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-39","question":"A firm's trend line for annual sales (₹ crore) is ŷ = 120 + 8t, with t = 1 for 2019. What is the forecast for 2026?","options":["192","184","128","176"],"answer":1,"explanation":"2026 is t = 8 (2019 = 1). ŷ = 120 + 8 × 8 = 184. Using t = 7 gives 176.","difficulty":"easy","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-40","question":"Annual demand is 2,400 units, ordering cost ₹200 per order and holding cost ₹6 per unit per year. What is the EOQ?","options":["566 units","160 units","400 units","283 units"],"answer":2,"explanation":"EOQ = √(2DS/H) = √(2 × 2,400 × 200 ÷ 6) = √160,000 = 400. Leaving out the 2 gives √80,000 ≈ 283.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-41","question":"Annual demand is 12,000 units and the EOQ is 600 units. The firm works 300 days a year. How often is an order placed?","options":["Every 20 days","Every 15 days","Every 18.25 days","Every 50 days"],"answer":1,"explanation":"Orders per year = 12,000 ÷ 600 = 20. Time between orders = 300 working days ÷ 20 = 15 days. Using 365 days gives 18.25; 20 is the number of orders.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-42","question":"Annual demand is 6,000 units, ordering cost ₹150 per order, unit price ₹20 and holding cost 25% of price per year. What is the total annual ordering-plus-holding cost at the EOQ?","options":["₹1,500","₹123,000","₹4,500","₹3,000"],"answer":3,"explanation":"H = 0.25 × 20 = ₹5. EOQ = √(2 × 6,000 × 150 ÷ 5) = √360,000 = 600. Ordering = (6,000/600) × 150 = ₹1,500; holding = (600/2) × 5 = ₹1,500; total ₹3,000. ₹123,000 adds the purchase cost.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-43","question":"For the item with D = 6,000, S = ₹150 and H = ₹5 (EOQ = 600), the buyer instead orders 900 units each time. How much extra ordering-plus-holding cost does this add per year?","options":["₹250","₹500","₹750","₹1,250"],"answer":0,"explanation":"At Q = 900: ordering = (6,000/900) × 150 = ₹1,000; holding = 450 × 5 = ₹2,250; total ₹3,250. At EOQ the total is ₹3,000, so the penalty is ₹250. ₹750 counts only the extra holding and ignores the ₹500 saved on ordering.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-44","question":"D = 6,000 units/yr, S = ₹150 per order, holding cost = 25% of unit price per year. The supplier charges ₹20 per unit for orders below 1,000 units and ₹19 per unit for orders of 1,000 or more. What order quantity minimises total annual cost (including purchase), and what is that cost?","options":["600 units; ₹123,000","1,000 units; ₹117,400","1,000 units; ₹117,275","616 units; ₹116,924"],"answer":2,"explanation":"EOQ at ₹19 = √(2×6,000×150 ÷ 4.75) ≈ 616, below the 1,000 break, so it is infeasible at that price. Compare: Q = 600 at ₹20 → 120,000 + 1,500 + 1,500 = ₹123,000; Q = 1,000 at ₹19 → 114,000 + 900 + 500 × 4.75 = ₹117,275. Take the discount. ₹117,400 keeps holding cost at ₹5 instead of 25% of ₹19.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-45","question":"Daily demand is 40 units, lead time is 6 days and the firm keeps 60 units of safety stock. What is the reorder point?","options":["300 units","240 units","280 units","360 units"],"answer":0,"explanation":"ROP = demand during lead time + safety stock = 40 × 6 + 60 = 300. 240 leaves out safety stock.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-46","question":"Average daily demand is 50 units with a standard deviation of 8 units per day; the lead time is a constant 9 days. For a 95% cycle-service level (z = 1.65), what is the reorder point?","options":["463.2 units","489.6 units","450.0 units","568.8 units"],"answer":1,"explanation":"σ over lead time = 8 × √9 = 24. Safety stock = 1.65 × 24 = 39.6. ROP = 50 × 9 + 39.6 = 489.6. Multiplying σ by 9 instead of √9 gives 568.8.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-47","question":"Daily demand averages 100 units (σ = 20 units/day). Lead time averages 4 days (σ = 1 day); demand and lead time are independent. For z = 2.33, what safety stock is needed (nearest unit)?","options":["326 units","96 units","93 units","251 units"],"answer":3,"explanation":"σ(LTD) = √(L·σd² + d²·σL²) = √(4 × 400 + 100² × 1) = √11,600 = 107.7. SS = 2.33 × 107.7 ≈ 251. Ignoring lead-time variability gives 2.33 × 40 ≈ 93; adding the σ's linearly gives 326.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-48","question":"Annual usage and unit cost of six items: P 500 units at ₹400; Q 10,000 at ₹2; R 2,000 at ₹50; S 50 at ₹600; T 8,000 at ₹5; U 1,000 at ₹10. If class A covers roughly the top 75% of annual consumption value, which items are class A?","options":["Q and T","P, R and T","P and R","P and S"],"answer":2,"explanation":"Annual values: P ₹2,00,000; R ₹1,00,000; T ₹40,000; S ₹30,000; Q ₹20,000; U ₹10,000; total ₹4,00,000. P (50%) + R (25%) = 75%. Q and T have the most units, and P and S the highest unit prices, but ABC ranks by value.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-49","question":"Match each inventory classification with its basis.\n1. ABC  2. VED  3. FSN  4. HML\na. Rate of movement (issues)  b. Criticality to operations  c. Annual consumption value  d. Unit price","options":["1-c, 2-a, 3-b, 4-d","1-d, 2-b, 3-a, 4-c","1-a, 2-b, 3-c, 4-d","1-c, 2-b, 3-a, 4-d"],"answer":3,"explanation":"ABC = annual consumption value; VED = vital/essential/desirable (criticality); FSN = fast/slow/non-moving; HML = high/medium/low unit price.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-50","question":"Which of the following cause the bullwhip effect in a supply chain?\nI. Each tier updating its forecast from the orders it receives\nII. Ordering in large batches\nIII. Everyday low pricing\nIV. Inflated orders when supply is rationed","options":["II and III only","I, II, III and IV","I, II and IV only","I and IV only"],"answer":2,"explanation":"Demand-signal processing, order batching, price fluctuations and rationing (shortage gaming) cause bullwhip. Everyday low pricing removes promotion-driven forward buying, so it reduces bullwhip.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-51","question":"Assertion (A): Vendor-managed inventory (VMI) tends to dampen the bullwhip effect.\nReason (R): Under VMI the supplier sees the retailer's actual consumption data instead of only its orders.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: the supplier plans from real demand rather than from distorted, batched orders, which removes one layer of signal amplification.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-52","question":"A firm makes a part in-house. Annual demand is 18,000 units (300 working days, so 60 units/day). The production rate is 100 units/day, setup cost ₹900 per run and holding cost ₹6 per unit per year. What is the economic production quantity (nearest unit)?","options":["3,000 units","3,674 units","1,470 units","2,324 units"],"answer":1,"explanation":"EPQ = √[2DS ÷ (H(1 − d/p))] = √[2 × 18,000 × 900 ÷ (6 × 0.4)] = √13,500,000 ≈ 3,674. Plain EOQ gives 2,324; 1,470 is the maximum inventory; using d/p instead of 1 − d/p gives 3,000.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-53","question":"Annual demand for an item rises by 44% while the ordering cost per order falls by 19%. Holding cost is unchanged. By what percentage does the EOQ change?","options":["Rises by 11.8%","Rises by 25%","Rises by 8%","Rises by 16.64%"],"answer":2,"explanation":"EOQ ∝ √(D × S). New/old = √(1.44 × 0.81) = √1.1664 = 1.08, an 8% rise. 16.64% forgets the square root; 25% simply nets 44 − 19.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-54","question":"Under a periodic-review system, stock is reviewed every 14 days and the supplier lead time is 7 days. Daily demand averages 30 units (σ = 6 units/day). For z = 1.65, how much should be ordered at a review when 250 units are on hand and nothing is on order (nearest unit)?","options":["588 units","380 units","207 units","425 units"],"answer":3,"explanation":"The protection period is T + L = 21 days. Order-up-to level = 30 × 21 + 1.65 × 6 × √21 = 630 + 45.4 = 675.4. Order = 675.4 − 250 ≈ 425. 380 leaves out safety stock; covering only the review period gives 207.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-55","question":"A kiosk buys a magazine at ₹30, sells it at ₹60 and returns unsold copies for ₹10 each. Demand is uniformly distributed between 100 and 200 copies. How many copies should it stock?","options":["175","160","150","140"],"answer":1,"explanation":"Underage cost Cu = 60 − 30 = 30; overage cost Co = 30 − 10 = 20. Critical ratio = 30/(30 + 20) = 0.6. Q = 100 + 0.6 × 100 = 160. Using Co/(Cu + Co) = 0.4 gives 140; stocking the mean gives 150.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-56","question":"The standard deviation of lead-time demand is 50 units and holding cost is ₹10 per unit per year. Raising the cycle-service level from 95% (z = 1.645) to 99% (z = 2.33) adds how much annual holding cost ?","options":["₹342.50","₹685.00","₹822.50","₹1,165.00"],"answer":0,"explanation":"Extra safety stock = (2.33 − 1.645) × 50 = 34.25 units. Extra cost = 34.25 × 10 = ₹342.50. ₹1,165 is the whole 99% safety-stock cost, not the increase.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-57","question":"Which statement is true at the economic order quantity in the basic EOQ model?","options":["Annual purchase cost is at its minimum","Annual ordering cost equals annual holding cost","Annual holding cost is twice the annual ordering cost","The number of orders per year equals the EOQ"],"answer":1,"explanation":"In the basic model total cost DS/Q + QH/2 is lowest where its two parts are equal, so at EOQ ordering cost = holding cost. Purchase cost does not depend on Q in this model.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-58","question":"For an item ordered at its EOQ, the annual holding cost is ₹4,500. Annual demand is 9,000 units and each order costs ₹250. What is the holding cost per unit per year?","options":["₹18","₹36","₹9","₹25"],"answer":0,"explanation":"At EOQ ordering cost = holding cost = ₹4,500, so DS/Q = 4,500 → Q = 9,000 × 250 ÷ 4,500 = 500. Holding = (Q/2) × H → 4,500 = 250 × H → H = ₹18. ₹9 divides by Q instead of Q/2.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-59","question":"An item's reorder point is 500 units. Right now there are 320 units on hand, 300 units on an open purchase order and 20 units backordered by customers. What should the planner do?","options":["Place an order; the inventory position is 300","No order; the inventory position is 640","Place an order; on-hand stock of 320 is below 500","No order; the inventory position is 600"],"answer":3,"explanation":"Reorder decisions use the inventory position = on hand + on order − backorders = 320 + 300 − 20 = 600, which is above 500. Adding the backorders instead of subtracting gives 640.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-60","question":"In a four-tier supply chain, the variance of weekly consumer demand is 100. The retailer's orders have variance 160, the distributor's orders 300 and the factory's production plan 540. What is the bullwhip ratio at the distributor?","options":["5.4","1.6","1.875","3.0"],"answer":2,"explanation":"Bullwhip ratio at a tier = variance of orders it places ÷ variance of orders it receives = 300 ÷ 160 = 1.875. 3.0 compares with consumer demand; 5.4 is the factory's ratio to consumer demand.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-61","question":"A batch of 500 circuit boards is inspected; each board has 4 opportunities for a defect. Inspectors find 30 defects. What is the DPMO?","options":["15,000","60,000","1,500","7,500"],"answer":0,"explanation":"DPMO = defects ÷ (units × opportunities) × 10⁶ = 30 ÷ 2,000 × 10⁶ = 15,000. Ignoring opportunities gives 30/500 × 10⁶ = 60,000.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-62","question":"Defect counts last month: scratches 84, dents 56, misalignment 30, paint runs 18, other 12. Using Pareto analysis, what is the smallest number of categories that together account for at least 80% of defects?","options":["4","2","3","1"],"answer":2,"explanation":"Total = 200. Cumulative shares: scratches 42%, + dents 70%, + misalignment 85%. Three categories reach 80%; two stop at 70%.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-63","question":"Which of the following is NOT one of the classic seven wastes of lean production?","options":["Waiting","Standardised work","Overproduction","Over-processing"],"answer":1,"explanation":"The seven wastes (TIMWOOD) are transport, inventory, motion, waiting, overproduction, over-processing and defects. Standardised work is a lean tool for removing waste, not a waste.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-64","question":"Twenty samples of size 5 give a grand mean of 50.0 mm and an average range of 4.0 mm. With A2 = 0.577 for n = 5, what is the upper control limit of the X̄-chart?","options":["55.37 mm","56.92 mm","54.00 mm","52.31 mm"],"answer":3,"explanation":"UCL = X̿ + A2·R̄ = 50 + 0.577 × 4 = 52.31 mm. Treating R̄ as σ (50 + 3 × 4/√5) gives 55.37; A2 already contains the factor 3, so multiplying by 3 again gives 56.92.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-65","question":"Twenty-five samples of 200 items each contain 250 defectives in total. What are the 3-sigma control limits of the p-chart?","options":["LCL = 0.0408, UCL = 0.0592","LCL = 0, UCL = 0.0962","LCL = 0.0038, UCL = 0.0962","LCL = 0.0192, UCL = 0.0808"],"answer":2,"explanation":"p̄ = 250 ÷ 5,000 = 0.05. σp = √(0.05 × 0.95 ÷ 200) = 0.01541. Limits = 0.05 ± 3 × 0.01541 = 0.0038 to 0.0962. The LCL is positive, so it is not set to 0. Using n = 5,000 (all items) shrinks σ wrongly.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-66","question":"A process is monitored with X̄ and R charts (n = 4): X̿ = 25, R̄ = 6.2, A2 = 0.729, D3 = 0, D4 = 2.282. Three new samples are taken: S1 = 27, 30, 24, 33; S2 = 19, 34, 25, 22; S3 = 31, 26, 34, 29. Which samples signal that the process is out of control?","options":["S3 only","S2 and S3 only","S1, S2 and S3","None of them"],"answer":1,"explanation":"X̄ limits = 25 ± 0.729 × 6.2 = 20.48 to 29.52; R limits = 0 to 2.282 × 6.2 = 14.15. S1: mean 28.5, range 9 → in control. S2: mean 25, range 15 → range out. S3: mean 30, range 8 → mean out. Checking only the X̄-chart misses S2.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-67","question":"A shaft's diameter specification is 10.0 ± 0.6 mm. The process mean is 10.2 mm and the standard deviation is 0.15 mm. What is Cpk?","options":["0.44","1.78","1.33","0.89"],"answer":3,"explanation":"Cp = (10.6 − 9.4) ÷ (6 × 0.15) = 1.33. Cpk = min(10.6 − 10.2, 10.2 − 9.4) ÷ (3 × 0.15) = 0.4 ÷ 0.45 = 0.89. Using the far side (0.8) gives 1.78; dividing by 6σ gives 0.44.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-68","question":"A part passes through three steps whose first-pass yields are 98%, 95% and 97%. What is the rolled throughput yield?","options":["90.3%","96.7%","95.0%","90.0%"],"answer":0,"explanation":"RTY = product of first-pass yields = 0.98 × 0.95 × 0.97 = 0.9031 ≈ 90.3%. Averaging gives 96.7%; subtracting the losses (2 + 5 + 3 = 10%) gives 90.0%.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-69","question":"A call centre audits 25,000 calls; each call has 5 defect opportunities, and 780 defects are found. Reference values (with the 1.5σ shift): 3σ = 66,807 DPMO, 4σ = 6,210 DPMO, 5σ = 233 DPMO. Which description is correct?","options":["DPMO = 31,200; between 3σ and 4σ","DPMO = 6,240; slightly above 4σ","DPMO = 1,248; between 4σ and 5σ","DPMO = 6,240; slightly below 4σ"],"answer":3,"explanation":"DPMO = 780 ÷ (25,000 × 5) × 10⁶ = 6,240. That is a little more than 6,210, so the process is slightly worse than (below) 4σ. Ignoring the 5 opportunities gives 31,200.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-70","question":"Match each quality tool with its main use.\n1. Pareto chart  2. Cause-and-effect (fishbone) diagram  3. Control chart  4. Scatter diagram\na. Separate common-cause from special-cause variation  b. Show a possible relationship between two variables  c. Pick out the vital few problem categories  d. Organise possible root causes into categories","options":["1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-a, 4-b","1-a, 2-d, 3-c, 4-b","1-c, 2-d, 3-b, 4-a"],"answer":1,"explanation":"Pareto ranks problems to find the vital few; fishbone organises causes (man, machine, method, material …); control charts separate common and special causes; scatter diagrams show relationships.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-71","question":"Assertion (A): A process can be in statistical control and still produce many units outside specification.\nReason (R): Control limits come from the process's own variation, whereas specification limits are set by the customer or designer.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both true and R explains A: a stable but wide (or off-centre) process stays within its control limits while many units fall outside specification.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-72","question":"Which statements are correct?\nI. Poka-yoke aims to make errors impossible or immediately obvious.\nII. Kaizen relies mainly on large, infrequent breakthrough projects.\nIII. The 5S are Sort, Set in order, Shine, Standardise and Sustain.\nIV. Jidoka means a machine or line stops automatically when an abnormality is detected.","options":["II, III and IV only","I, II, III and IV","I, III and IV only","I and II only"],"answer":2,"explanation":"Kaizen is continuous, incremental improvement by everyone, the opposite of occasional breakthroughs, so II is false. The others are correct definitions.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-73","question":"A firm's annual quality costs (₹ lakh): employee quality training 4, incoming inspection 6, scrap 9, warranty claims 11, supplier certification 2, calibration of test equipment 3, rework 5. What share of the total cost of quality is failure cost?","options":["27.5%","62.5%","50.0%","37.5%"],"answer":1,"explanation":"Prevention = 4 + 2 = 6; appraisal = 6 + 3 = 9; internal failure = 9 + 5 = 14; external failure = 11. Total = 40. Failure = 25 ÷ 40 = 62.5%. 50% forgets rework; 37.5% is the cost of conformance.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-74","question":"Using the Taguchi loss function, a deviation of 0.5 mm from target causes a loss of ₹200 per unit. What is the loss for a unit that is 0.2 mm off target?","options":["₹128","₹16","₹80","₹32"],"answer":3,"explanation":"L = k(x − T)². k = 200 ÷ 0.5² = 800. Loss = 800 × 0.2² = ₹32. A straight-line (proportional) assumption gives ₹80.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-75","question":"A project's activities (duration in days; immediate predecessors): A 3 (–), B 4 (–), C 5 (A), D 6 (A), E 2 (B), F 4 (C), G 3 (D, E), H 2 (F, G). What is the project duration?","options":["14 days","29 days","11 days","16 days"],"answer":0,"explanation":"Paths: A–C–F–H = 14; A–D–G–H = 14; B–E–G–H = 11. The longest path(s) give 14 days, and here there are two critical paths. 29 is the sum of all durations.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-76","question":"For the project A 3 (–), B 4 (–), C 5 (A), D 6 (A), E 2 (B), F 4 (C), G 3 (D, E), H 2 (F, G), what are the total float and the free float of activity B?","options":["Total float 0, free float 0","Total float 3, free float 3","Total float 3, free float 0","Total float 0, free float 3"],"answer":2,"explanation":"B: ES 0, EF 4. G's latest start = 14 − 2 − 3 = 9, so E's LF = 9, E's LS = 7 and B's LF = 7 → total float = 3. B's only successor E has ES = 4 = B's EF, so free float = 0. The float belongs to the B–E chain as a whole.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-77","question":"For the project A 3 (–), B 4 (–), C 5 (A), D 6 (A), E 2 (B), F 4 (C), G 3 (D, E), H 2 (F, G), what is the earliest start of activity G?","options":["Day 12","Day 9","Day 6","Day 7"],"answer":1,"explanation":"G needs both D and E. EF(D) = 3 + 6 = 9; EF(E) = 4 + 2 = 6. ES(G) = max(9, 6) = 9. Taking the minimum (6) is the classic forward-pass error.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-78","question":"A small project has two parallel paths. Path 1 is A (4 days) → C (6 days); path 2, parallel to it, is B (5 days) → D (4 days). Crash cost per day and maximum crash: A ₹500 (1 day), C ₹300 (2 days), B ₹400 (2 days), D ₹200 (1 day). What is the minimum crashing cost to finish the project in 8 days?","options":["₹500","₹1,000","₹600","₹800"],"answer":3,"explanation":"Normal length = 10 days (A–C); B–D = 9. Day 10 → 9: crash C (₹300); now both paths are 9. Day 9 → 8: both paths must shrink, so crash C again (₹300) and D (₹200). Total = ₹800. ₹600 crashes C twice and forgets that B–D has become critical.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-79","question":"Path 1 is A (4 days) → C (6 days); path 2, parallel to it, is B (5 days) → D (4 days). Crash cost per day and maximum crash: A ₹500 (1 day), C ₹300 (2 days), B ₹400 (2 days), D ₹200 (1 day). Indirect (overhead) cost is ₹450 per day and the normal duration is 10 days. Which project duration minimises total cost?","options":["8 days","7 days","9 days","10 days"],"answer":2,"explanation":"10 → 9: crash C for ₹300 and save ₹450 → worth it. 9 → 8: both paths now critical; cheapest pair is C + D = ₹500 > ₹450 → not worth it. Total costs: 10 days ₹4,500, 9 days ₹4,350, 8 days ₹4,400. Optimum = 9 days.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-80","question":"A PERT activity has an optimistic time of 4 days, most likely 7 days and pessimistic 16 days. What are its expected time and variance?","options":["8 days; variance 4","8 days; variance 144","8 days; variance 2","9 days; variance 4"],"answer":0,"explanation":"te = (a + 4m + b)/6 = (4 + 28 + 16)/6 = 8 days. σ = (b − a)/6 = 12/6 = 2, so variance = 4. A simple average (4 + 7 + 16)/3 = 9 ignores the weight on m.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-81","question":"The critical path of a project has three activities with PERT estimates (a, m, b) in days: (2, 4, 6), (3, 5, 13) and (4, 6, 8). Assuming a normal distribution, what is the probability (approximately) of finishing within 18 days?","options":["15%","75%","85%","70%"],"answer":2,"explanation":"te = 4 + 6 + 6 = 16 days. Variances: 0.444 + 2.778 + 0.444 = 3.667; σ = 1.915. z = (18 − 16)/1.915 = 1.04 → P ≈ 85%. Adding standard deviations instead of variances gives σ = 3 and ≈ 75%.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-82","question":"A project's critical path has an expected length of 40 days and a standard deviation of 3 days. What due date gives a 95% chance of on-time completion (z = 1.645)?","options":["35.1 days","44.9 days","46.0 days","49.0 days"],"answer":1,"explanation":"Due date = 40 + 1.645 × 3 = 44.9 days. Adding the variance (9) gives 49; 35.1 is the 5% point on the wrong side.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-83","question":"In an activity-on-arrow project network, a dummy activity:","options":["represents waiting time for resources","takes the average duration of its neighbours","is always on the critical path","takes no time or resources and only shows a dependency"],"answer":3,"explanation":"Dummies (dashed arrows) carry zero time and cost; they keep event numbering unique and show logical dependencies.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-84","question":"Activities (days; predecessors): A 5 (–), B 3 (–), C 8 (A), D 4 (A, B), E 6 (B), F 3 (C, D), G 7 (D, E), H 4 (F), I 2 (G). If activity G is delayed by 3 days, what does the project duration become?","options":["21 days","23 days","19 days","20 days"],"answer":0,"explanation":"Critical path A–C–F–H = 20 days. G: ES = max(EF D = 9, EF E = 9) = 9, LF = 20 − 2 = 18, LS = 11 → total float 2. A 3-day delay uses the 2 days of float and pushes the end out by 1 day: 21 days. 23 assumes G is critical.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-85","question":"Which statements about float in CPM are correct?\nI. Free float can never exceed total float.\nII. Using up an activity's free float delays the early start of its successors.\nIII. When the deadline equals the critical-path length, critical activities have zero total float.\nIV. Total float is shared by the activities along a non-critical chain.","options":["II, III and IV only","I and II only","I, III and IV only","I, II, III and IV"],"answer":2,"explanation":"Free float is exactly the delay possible without disturbing any successor's early start, so II is false. The rest are true; using total float on one activity reduces what is left for the others on that chain.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-86","question":"An activity's normal time is 10 days at a cost of ₹20,000; its crash time is 6 days at ₹32,000. What is its crash cost per day?","options":["₹3,200","₹3,000","₹1,200","₹2,000"],"answer":1,"explanation":"Cost slope = (crash cost − normal cost) ÷ (normal time − crash time) = 12,000 ÷ 4 = ₹3,000 per day. ₹3,200 divides crash cost by 10; ₹1,200 divides by 10 days.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-87","question":"A project has two independent paths. Path 1: expected 30 days, variance 9. Path 2: expected 29 days, variance 25. What is the approximate probability that the whole project finishes within 32 days?","options":["75%","73%","63%","54%"],"answer":3,"explanation":"Both paths must finish. P(path 1 ≤ 32) = Φ(2/3) = 0.748; P(path 2 ≤ 32) = Φ(3/5) = 0.726. Product = 0.543 ≈ 54%. Using only the 'critical' path 1 gives 75% and overstates the chance, because path 2 has far more variance; pooling the two variances (√34) is also wrong because the paths run in parallel, not in series.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-88","question":"In CPM, the critical path is:","options":["the longest path through the network","the shortest path through the network","the path with the highest total cost","the path with the most activities"],"answer":0,"explanation":"The project cannot finish before its longest path, so that path decides the duration and has zero float.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-89","question":"A work cell uses 200 parts per hour. A container holds 30 parts and the replenishment lead time (waiting plus processing) is 45 minutes. With a 20% safety factor, how many kanban cards are needed?","options":["8","4","6","5"],"answer":2,"explanation":"N = D × L × (1 + α) ÷ C = 200 × 0.75 × 1.2 ÷ 30 = 6. Without the safety factor it is 5.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-90","question":"A dimension has specification 100 ± 6. The process standard deviation is 1.5 and its mean has drifted to 101.5. About how many parts per million fall outside specification?","options":["About 1,350","About 3.4","About 66,800","About 2,700"],"answer":0,"explanation":"Upper side: z = (106 − 101.5)/1.5 = 3 → tail ≈ 0.00135 = 1350 ppm. Lower side: z = (101.5 − 94)/1.5 = 5 → negligible. Total ≈ 1,350 ppm. 2,700 counts a 3σ tail on both sides, which applies only to a centred process with ±3σ specs.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-91","question":"A workshop makes chairs (profit ₹40 each) and tables (profit ₹70 each). A chair needs 2 carpentry hours and 3 finishing hours; a table needs 5 carpentry hours and 2 finishing hours. 100 carpentry hours and 84 finishing hours are available per week. With x chairs and y tables, which is the correct LP formulation?","options":["Min 40x + 70y; 2x + 5y ≥ 100; 3x + 2y ≥ 84; x, y ≥ 0","Max 40x + 70y; 2x + 3y ≤ 100; 5x + 2y ≤ 84; x, y ≥ 0","Max 40x + 70y; 2x + 5y ≤ 84; 3x + 2y ≤ 100; x, y ≥ 0","Max 40x + 70y; 2x + 5y ≤ 100; 3x + 2y ≤ 84; x, y ≥ 0"],"answer":3,"explanation":"Each resource gives one constraint: carpentry 2x + 5y ≤ 100 and finishing 3x + 2y ≤ 84. Profit is maximised. The first distractor mixes up which coefficients belong to which product.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-92","question":"A workshop makes chairs (profit ₹40 each) and tables (profit ₹70 each). A chair needs 2 carpentry hours and 3 finishing hours; a table needs 5 carpentry hours and 2 finishing hours. 100 carpentry hours and 84 finishing hours are available per week. What is the maximum weekly profit?","options":["₹1,120","₹1,640","₹1,720","₹1,400"],"answer":1,"explanation":"Corner points: (0, 0) → 0; (28, 0) → ₹1,120; (0, 20) → ₹1,400; and the intersection of 2x + 5y = 100 with 3x + 2y = 84, which is (20, 12) → 800 + 840 = ₹1,640. Making only tables (the higher-margin product) gives ₹1,400.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-93","question":"A workshop makes chairs (profit ₹40 each) and tables (profit ₹70 each). A chair needs 2 carpentry hours and 3 finishing hours; a table needs 5 carpentry hours and 2 finishing hours. 100 carpentry hours and 84 finishing hours are available per week. Both resources are binding at the optimum. What is the shadow price of one extra carpentry hour (to two decimals)?","options":["₹5.45","₹11.82","₹20.00","₹14.00"],"answer":1,"explanation":"Shadow prices (u carpentry, v finishing) satisfy the dual equalities 2u + 3v = 40 and 5u + 2v = 70 → u = 130/11 ≈ ₹11.82, v = 60/11 ≈ ₹5.45. Check: with 101 hours the optimum moves to (19.818, 12.273) and profit rises by 11.82. ₹14 (= 70/5) wrongly assumes only tables would be made.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-94","question":"Minimise C = 3x + 2y subject to x + y ≥ 8, x + 3y ≥ 12, 2x + y ≥ 10, x, y ≥ 0. What is the minimum value of C?","options":["18","20","22","36"],"answer":0,"explanation":"The feasible region is unbounded upward, with corner points (0, 10) → 20, (2, 6) → 18, (6, 2) → 22 and (12, 0) → 36. Because we minimise and the cost coefficients are positive, the optimum is the cheapest corner: (2, 6), C = 18.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-95","question":"In a two-variable LP solved graphically, the iso-profit line turns out to be parallel to a binding edge of the feasible region at the optimum. What does this indicate?","options":["The solution is degenerate","The problem is unbounded","The problem is infeasible","Multiple (alternative) optimal solutions"],"answer":3,"explanation":"When the objective is parallel to a boundary edge that it touches last, every point on that edge, including both end corners, gives the same optimal value.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-96","question":"Which statements about linear programming are correct?\nI. The feasible region of an LP is a convex set.\nII. If an optimal solution exists, at least one corner point is optimal.\nIII. A constraint with positive slack at the optimum has a positive shadow price.\nIV. Adding a constraint can never improve the optimal objective value.","options":["I, II, III and IV","II, III and IV only","I, II and IV only","I and III only"],"answer":2,"explanation":"A non-binding constraint (positive slack) has a shadow price of zero (complementary slackness), so III is false. Adding a constraint can only shrink or keep the feasible region, so the optimum can only stay or get worse.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-97","question":"Maximise Z = 7x + 5y subject to x + 2y ≤ 14, 3x + y ≤ 18, x − y ≤ 4, x, y ≥ 0. What is the optimal value of Z?","options":["54.8","42","46","35"],"answer":0,"explanation":"Corner points: (0, 0) → 0; (0, 7) → 35; (4, 0) → 28; (5.5, 1.5) [3x + y = 18 with x − y = 4] → 46; (4.4, 4.8) [x + 2y = 14 with 3x + y = 18] → 30.8 + 24 = 54.8. The optimum is at (4.4, 4.8). Stopping at the first intersection found (5.5, 1.5) gives 46.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-98","question":"An LP has the constraints x + y ≤ 4 and x + y ≥ 6 (with x, y ≥ 0). What can be said about it?","options":["It has alternative optima","It has a unique optimum at (4, 0)","It is infeasible","It is unbounded"],"answer":2,"explanation":"No point can have x + y both at most 4 and at least 6, so the feasible region is empty.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-99","question":"A transportation problem has supplies of 120, 80 and 100 units at three plants and demands of 90, 110 and 70 units at three markets. How should it be balanced before solving?","options":["Add a dummy plant with supply 30 and zero transport cost","Add a dummy market with demand 30 and zero transport cost","No change is needed; it is already balanced","Reduce the largest supply by 30"],"answer":1,"explanation":"Total supply = 300, total demand = 270. The excess supply of 30 goes to a dummy destination (column) with zero cost; that allocation is stock left unshipped at the plants.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-100","question":"Unit transport costs (₹) from plants P1, P2, P3 (rows) to markets M1, M2, M3 (columns): P1: 8, 6, 10; P2: 9, 12, 7; P3: 14, 9, 16. Supplies: P1 60, P2 80, P3 60. Demands: M1 50, M2 70, M3 80. What is the total cost of the initial solution found by the North-West Corner Rule?","options":["₹1,710","₹1,560","₹2,040","₹2,280"],"answer":3,"explanation":"NWCR: P1→M1 50 (₹400), P1→M2 10 (₹60), P2→M2 60 (₹720), P2→M3 20 (₹140), P3→M3 60 (₹960). Total = ₹2,280. NWCR ignores costs, which is why it is usually the worst starting solution; ₹1,710 is the least-cost method.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-101","question":"Unit transport costs (₹) from plants P1, P2, P3 (rows) to markets M1, M2, M3 (columns): P1: 8, 6, 10; P2: 9, 12, 7; P3: 14, 9, 16. Supplies: P1 60, P2 80, P3 60. Demands: M1 50, M2 70, M3 80. What is the total cost of the initial solution found by Vogel's Approximation Method?","options":["₹1,620","₹1,560","₹1,710","₹2,280"],"answer":1,"explanation":"Round 1 penalties (gap between the two cheapest cells): P1 2, P2 2, P3 5, M1 1, M2 3, M3 3. P3 is largest → its cheapest cell P3→M2 gets 60 (₹540), exhausting P3. Round 2: M2 now has penalty 12 − 6 = 6, the largest → P1→M2 gets the remaining 10 (₹60). Round 3: M3 penalty 10 − 7 = 3 → P2→M3 80 (₹560). Finally P1→M1 50 (₹400). Total = ₹1,560, which here is already optimal. The least-cost method gives ₹1,710 and NWCR ₹2,280.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-102","question":"Unit transport costs (₹) from plants P1, P2, P3 (rows) to markets M1, M2, M3 (columns): P1: 8, 6, 10; P2: 9, 12, 7; P3: 14, 9, 16. Supplies: P1 60, P2 80, P3 60. Demands: M1 50, M2 70, M3 80. Starting from the North-West Corner solution, the MODI (u–v) method is applied with u1 = 0. Which unused cell enters the basis, and what is its reduced cost cij − ui − vj?","options":["P1→M3, +9","P3→M1, −9","P2→M1, −5","P3→M2, −12"],"answer":3,"explanation":"Basic cells give u1 = 0, v1 = 8, v2 = 6, u2 = 6, v3 = 1, u3 = 15. Reduced costs: P1→M3 = 10 − 0 − 1 = +9; P2→M1 = 9 − 6 − 8 = −5; P3→M1 = 14 − 15 − 8 = −9; P3→M2 = 9 − 15 − 6 = −12. The most negative, P3→M2, enters.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-103","question":"A transportation problem has 4 sources and 5 destinations. An initial basic feasible solution has 7 occupied cells. What does this mean?","options":["The solution is degenerate; it needs 8 occupied cells","The solution is optimal","The solution is non-degenerate","The problem is unbalanced"],"answer":0,"explanation":"A non-degenerate basic solution has m + n − 1 = 4 + 5 − 1 = 8 allocations. With only 7, an ε allocation must be added before MODI can compute all ui and vj.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-104","question":"Three jobs must be assigned one each to three workers. Costs (₹ hundred), rows = jobs J1–J3, columns = workers W1–W3: J1: 9, 11, 14; J2: 6, 15, 13; J3: 12, 13, 6. What is the minimum total cost?","options":["30","21","23","33"],"answer":2,"explanation":"Check the assignments: J1→W2, J2→W1, J3→W3 = 11 + 6 + 6 = 23, the lowest of the six possibilities. 21 adds each row's minimum (9 + 6 + 6) but uses W1 twice; 30 is the diagonal.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-105","question":"Four salespersons P, Q, R, S are to be assigned one each to territories T1–T4. Expected monthly sales (₹ lakh), columns T1–T4: P: 38, 40, 28, 33; Q: 31, 37, 35, 26; R: 42, 34, 30, 29; S: 27, 32, 36, 30. What is the maximum total sales?","options":["₹144 lakh","₹155 lakh","₹135 lakh","₹148 lakh"],"answer":3,"explanation":"Best assignment: P→T4, Q→T2, R→T1, S→T3 = 148. Grabbing the largest cell each time (R→T1 42, P→T2 40, then S→T3 36, Q→T4 26) gives 144; adding each row's maximum (155) is not a valid assignment. For the Hungarian method, first convert to a loss matrix by subtracting every entry from 42.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-106","question":"When the Hungarian method is used for a maximisation assignment problem, what is the first step?","options":["Subtract every entry from the largest entry in the matrix","Subtract each row's maximum from that row","Multiply all entries by −1 and stop","Add a dummy row of zeros"],"answer":0,"explanation":"Converting to an opportunity-loss matrix (largest entry − each entry) turns maximisation into minimisation; the usual row and column reductions then follow. Multiplying by −1 also works, but only if the reductions continue afterwards.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-107","question":"Assertion (A): The assignment problem is a special case of the transportation problem.\nReason (R): In an assignment problem every supply and every demand equals 1.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both true, and R explains A: with unit supplies and demands, the transportation model becomes the one-to-one assignment model (which is highly degenerate, so the Hungarian method is used instead of MODI).","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-108","question":"A firm must choose a plant size. Payoffs (₹ lakh) under low, medium and high demand: Small 40, 45, 50; Medium 20, 60, 80; Large −30, 50, 120. Which plant does an optimist using the maximax criterion choose?","options":["Medium","Small","Large","Medium or Large equally"],"answer":2,"explanation":"Maximax takes each option's best payoff (Small 50, Medium 80, Large 120) and picks the largest: Large.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-109","question":"A firm must choose a plant size. Payoffs (₹ lakh) under low, medium and high demand: Small 40, 45, 50; Medium 20, 60, 80; Large −30, 50, 120. Which plant does the maximin (pessimist) criterion select?","options":["Large","Small","Small or Medium equally","Medium"],"answer":1,"explanation":"Worst payoffs: Small 40, Medium 20, Large −30. Maximin picks the best of these worst cases: Small.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-110","question":"A firm must choose a plant size. Payoffs (₹ lakh) under low, medium and high demand: Small 40, 45, 50; Medium 20, 60, 80; Large −30, 50, 120. Probabilities of low, medium and high demand are 0.3, 0.5 and 0.2. Which plant has the highest expected monetary value, and what is it?","options":["Large, ₹40 lakh","Medium, ₹53.33 lakh","Small, ₹44.5 lakh","Medium, ₹52 lakh"],"answer":3,"explanation":"EMV Small = 12 + 22.5 + 10 = 44.5; Medium = 6 + 30 + 16 = 52; Large = −9 + 25 + 24 = 40. Best: Medium, ₹52 lakh. ₹53.33 lakh is the equal-weight (Laplace) average.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-111","question":"A firm must choose a plant size. Payoffs (₹ lakh) under low, medium and high demand: Small 40, 45, 50; Medium 20, 60, 80; Large −30, 50, 120. Under the minimax-regret criterion, which plant is chosen and what is its maximum regret?","options":["Small, ₹70 lakh","Medium, ₹20 lakh","Medium, ₹40 lakh","Large, ₹70 lakh"],"answer":2,"explanation":"Column bests: 40, 60, 120. Regrets: Small 0, 15, 70 (max 70); Medium 20, 0, 40 (max 40); Large 70, 10, 0 (max 70). Minimax regret = Medium with 40. ₹20 lakh is Medium's regret under low demand only.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-112","question":"A firm must choose a plant size. Payoffs (₹ lakh) under low, medium and high demand: Small 40, 45, 50; Medium 20, 60, 80; Large −30, 50, 120. Probabilities of low, medium and high demand are 0.3, 0.5 and 0.2. What is the expected value of perfect information (EVPI)?","options":["₹68 lakh","₹14 lakh","₹26 lakh","₹66 lakh"],"answer":1,"explanation":"With perfect information the firm picks the best plant for each state: 0.3 × 40 + 0.5 × 60 + 0.2 × 120 = 66. Best EMV without it = 52 (Medium). EVPI = 66 − 52 = ₹14 lakh. 66 is EV under certainty, not the value of the information.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-113","question":"A firm must choose a plant size. Payoffs (₹ lakh) under low, medium and high demand: Small 40, 45, 50; Medium 20, 60, 80; Large −30, 50, 120. Using the Hurwicz criterion with coefficient of optimism α = 0.6, which plant is chosen?","options":["Large, with a score of 60","Medium, with a score of 56","Small, with a score of 46","Medium, with a score of 44"],"answer":0,"explanation":"Score = α × best + (1 − α) × worst. Small 0.6×50 + 0.4×40 = 46; Medium 0.6×80 + 0.4×20 = 56; Large 0.6×120 + 0.4×(−30) = 60. Large wins. Swapping the weights would give Medium 44.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-114","question":"A firm must choose a plant size. Payoffs (₹ lakh) under low, medium and high demand: Small 40, 45, 50; Medium 20, 60, 80; Large −30, 50, 120. Keeping P(low demand) at 0.3, how large must P(high demand) be for the Large plant to have the highest EMV?","options":["More than 0.50","More than 0.27","More than 0.44","More than 0.20"],"answer":2,"explanation":"Let P(high) = p, so P(medium) = 0.7 − p. EMV Small = 43.5 + 5p; Medium = 48 + 20p; Large = 26 + 70p. Large beats Medium when 70p − 20p > 22 → p > 0.44; it beats Small already when p > 0.27, but Medium is the real rival.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-115","question":"A firm can launch a product now: success (probability 0.4) earns ₹100 lakh, failure loses ₹50 lakh; not launching earns 0. A test market reports 'favourable' with probability 0.8 if the product will succeed and 0.3 if it will fail. If the test result is favourable, what is the revised probability of success?","options":["0.80","0.64","0.32","0.50"],"answer":1,"explanation":"P(fav) = 0.8 × 0.4 + 0.3 × 0.6 = 0.32 + 0.18 = 0.50. P(success | fav) = 0.32 ÷ 0.50 = 0.64 (Bayes). 0.80 confuses P(fav | success) with P(success | fav).","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-116","question":"A firm can launch a product now: success (probability 0.4) earns ₹100 lakh, failure loses ₹50 lakh; not launching earns 0. A test market reports 'favourable' with probability 0.8 if the product will succeed and 0.3 if it will fail. What is the most the firm should pay for the test market (the expected value of sample information)?","options":["₹23 lakh","₹10 lakh","₹30 lakh","₹13 lakh"],"answer":3,"explanation":"Without the test: EMV(launch) = 40 − 30 = ₹10 lakh. Favourable (prob 0.5): P(S) = 0.64 → EMV = 64 − 18 = ₹46 lakh → launch. Unfavourable (prob 0.5): P(S) = 0.08/0.5 = 0.16 → EMV = 16 − 42 = −26 → do not launch (0). EV with test = 0.5 × 46 + 0.5 × 0 = ₹23 lakh. EVSI = 23 − 10 = ₹13 lakh. ₹30 lakh is EVPI, an upper bound.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-117","question":"Assertion (A): The action with the highest EMV is also the action with the lowest expected opportunity loss (EOL).\nReason (R): For every action, EMV + EOL equals the expected value under perfect information.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both true and R explains A: since EMV + EOL is the same constant for every action, maximising EMV is the same as minimising EOL, and the minimum EOL equals EVPI.","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-118","question":"A firm must choose a plant size. Payoffs (₹ lakh) under low, medium and high demand: Small 40, 45, 50; Medium 20, 60, 80; Large −30, 50, 120. Using the Laplace (equal-likelihood) criterion, which plant is chosen?","options":["Small, average ₹45 lakh","Medium, average ₹53.33 lakh","Large, average ₹46.67 lakh","Medium, average ₹52 lakh"],"answer":1,"explanation":"Laplace gives each state probability 1/3. Averages: Small 135/3 = 45; Medium 160/3 = 53.33; Large 140/3 = 46.67. Medium. ₹52 lakh is its EMV with the given probabilities, not the Laplace value.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-119","question":"Which decision criterion under uncertainty reflects a pessimistic decision-maker who looks only at the worst outcome of each option?","options":["Maximax","Laplace","Minimax regret","Maximin"],"answer":3,"explanation":"Maximin picks the option whose worst payoff is best. Maximax is optimistic; minimax regret minimises the largest opportunity loss; Laplace weights states equally.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-120","question":"A venture pays ₹100 lakh with probability 0.5 and nothing otherwise. The owner says she is indifferent between the venture and a sure ₹40 lakh. What are the risk premium and her risk attitude?","options":["₹10 lakh; risk-seeking","₹60 lakh; risk-neutral","₹10 lakh; risk-averse","₹40 lakh; risk-averse"],"answer":2,"explanation":"EMV = ₹50 lakh; certainty equivalent = ₹40 lakh. Risk premium = 50 − 40 = ₹10 lakh. Accepting less than the EMV for certainty means she is risk-averse.","difficulty":"moderate","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-121","question":"Monthly salaries (₹ thousand) of seven employees in a team are 30, 32, 35, 38, 40, 42 and 250. Which figure best represents a typical salary, and why?","options":["₹250 thousand, the maximum, because it drives total cost","₹38 thousand, the median, because it is not pulled up by the 250 outlier","₹37.4 thousand, the mean without the top and bottom values","₹66.7 thousand, the mean, because it uses every value"],"answer":1,"explanation":"Mean = 467/7 ≈ 66.7, inflated by one very high salary; six of the seven earn less than that. The median (4th value) = 38 represents the typical employee.","difficulty":"easy","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-122","question":"Store A has mean daily sales of ₹50,000 with a standard deviation of ₹6,000. Store B has mean daily sales of ₹20,000 with a standard deviation of ₹3,000. Which store's sales are more consistent?","options":["Store A, because its coefficient of variation is 12% against B's 15%","Store B, because its coefficient of variation is 12%","Both are equally consistent","Store B, because its standard deviation is smaller"],"answer":0,"explanation":"Different means need a relative measure: CV = σ/mean. A: 6,000/50,000 = 12%; B: 3,000/20,000 = 15%. Lower CV = more consistent, so A. Comparing raw standard deviations favours B wrongly.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-123","question":"A distributor sold 200 units at ₹50, 300 units at ₹45 and 500 units at ₹40 during a quarter. What was the average selling price per unit?","options":["₹44","₹45","₹42","₹43.5"],"answer":3,"explanation":"Weighted average = (200×50 + 300×45 + 500×40) ÷ 1,000 = 43,500 ÷ 1,000 = ₹43.5. The simple average of the three prices (₹45) ignores that most units sold at ₹40.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-124","question":"Delivery times of a food app are normally distributed with mean 30 minutes and standard deviation 5 minutes. On a day with 1,200 orders, about how many take longer than 40 minutes?","options":["About 190","About 2","About 27","About 60"],"answer":2,"explanation":"z = (40 − 30)/5 = 2. P(Z > 2) ≈ 0.0228. Expected count = 1,200 × 0.0228 ≈ 27. 60 uses 5%, which is the share outside ±2σ on both sides; 190 uses z = 1.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-125","question":"A product needs parts from three independent suppliers, each delivering on time with probability 0.9. Production starts on time only if all three deliver on time. What is the probability that at least one delivery is late?","options":["0.100","0.271","0.001","0.300"],"answer":1,"explanation":"P(all on time) = 0.9³ = 0.729, so P(at least one late) = 1 − 0.729 = 0.271. Adding 0.1 three times (0.3) double-counts cases where two are late; 0.001 is the chance that all three are late.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-126","question":"1% of card transactions are fraudulent. A fraud model flags 95% of fraudulent transactions and also flags 4% of genuine ones. If a transaction is flagged, what is the probability that it is actually fraudulent?","options":["95.0%","96.0%","49.0%","19.3%"],"answer":3,"explanation":"P(flag) = 0.01 × 0.95 + 0.99 × 0.04 = 0.0095 + 0.0396 = 0.0491. P(fraud | flag) = 0.0095 ÷ 0.0491 ≈ 19.3%. The low base rate means most flags are false alarms; 95% is P(flag | fraud), not P(fraud | flag).","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-127","question":"A machine produces 10% defectives, independently. In a random sample of 5 items, what is the probability of at most one defective?","options":["0.328","0.672","0.919","0.590"],"answer":2,"explanation":"P(0) = 0.9⁵ = 0.59049; P(1) = 5 × 0.1 × 0.9⁴ = 0.32805. P(≤ 1) = 0.91854 ≈ 0.919. 0.590 counts only zero defectives.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-128","question":"Calls reach a support line at an average of 3 per 10 minutes (Poisson). What is the probability of no calls in a 5-minute window?","options":["0.2231","0.7769","0.0498","0.5000"],"answer":0,"explanation":"For 5 minutes the mean is λ = 1.5. P(0) = e^(−1.5) = 0.2231. Using λ = 3 (the 10-minute rate) gives 0.0498; 0.7769 is P(at least one call).","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-129","question":"A regression of monthly sales on advertising spend (both in ₹ lakh) gives Sales = 120 + 4.5 × AdSpend, with R² = 0.64. Which statements are correct?\nI. Each extra ₹1 lakh of advertising is associated with ₹4.5 lakh more sales.\nII. 64% of the variation in sales is explained by advertising spend.\nIII. The correlation coefficient between sales and advertising is 0.64.\nIV. With zero advertising the model predicts sales of ₹120 lakh.","options":["I and III only","II, III and IV only","I, II and IV only","I, II, III and IV"],"answer":2,"explanation":"The slope and intercept read as in I and IV, and R² is the share of variance explained (II). The correlation is r = +√0.64 = 0.8 (positive because the slope is positive), so III is false.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-130","question":"Weekly sales (y, ₹ lakh) for promotion budgets x = 1, 2, 3, 4, 5 (₹ lakh) were 3, 5, 4, 7 and 8. Using a least-squares line, what sales are predicted for a budget of 7?","options":["₹8.4 lakh","₹11.4 lakh","₹9.6 lakh","₹10.2 lakh"],"answer":3,"explanation":"x̄ = 3, ȳ = 5.4. Sxy = (−2)(−2.4) + (−1)(−0.4) + 0 + (1)(1.6) + (2)(2.6) = 12; Sxx = 10. b = 1.2; a = 5.4 − 1.2 × 3 = 1.8. ŷ(7) = 1.8 + 1.2 × 7 = 10.2. Leaving out the intercept gives 8.4.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-131","question":"In a simple regression of y on x, the slope is 2.5, the standard deviation of x is 4 and the standard deviation of y is 12.5. What is R²?","options":["0.64","0.80","0.40","0.96"],"answer":0,"explanation":"r = b × (σx/σy) = 2.5 × 4/12.5 = 0.8. In simple regression R² = r² = 0.64. 0.80 is r itself.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-132","question":"A salary model (₹ lakh per year) is Salary = 5 + 2.0 × Experience (years) + 4.0 × MBA, where MBA = 1 for an MBA and 0 otherwise. What is the predicted salary of an MBA with 3 years' experience minus that of a non-MBA with 5 years' experience?","options":["−₹4 lakh","₹0","₹8 lakh","₹4 lakh"],"answer":1,"explanation":"MBA, 3 years: 5 + 6 + 4 = 15. Non-MBA, 5 years: 5 + 10 + 0 = 15. Difference = 0: the MBA premium of 4 exactly offsets 2 fewer years at 2 per year.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-133","question":"A multiple regression with 4 predictors fitted on 25 observations has R² = 0.80. What is the adjusted R²?","options":["0.76","0.64","0.80","0.83"],"answer":0,"explanation":"Adjusted R² = 1 − (1 − R²)(n − 1)/(n − k − 1) = 1 − 0.2 × 24/20 = 0.76. Inverting the fraction gives 0.83, which would wrongly reward extra predictors.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-134","question":"A marketer tests H0: 'the new campaign does not increase average sales' against H1: 'it increases sales'. What is a Type I error here?","options":["Using a sample that is too small","Concluding the campaign does not increase sales when in fact it does","Concluding the campaign increases sales when in fact it does not","Rejecting H1 when H1 is false"],"answer":2,"explanation":"A Type I error is rejecting a true H0, so the firm believes in an effect that is not there (a false positive). The first distractor is a Type II error.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-135","question":"A two-tailed test of whether average basket size has changed gives a p-value of 0.032. Which conclusion is correct?","options":["There is a 3.2% probability that H0 is true","Do not reject H0 at the 5% level","Reject H0 at both the 5% and the 1% levels","Reject H0 at the 5% level but not at the 1% level"],"answer":3,"explanation":"Reject when p < α: 0.032 < 0.05 but 0.032 > 0.01. A p-value is the probability of data at least this extreme if H0 were true, not the probability that H0 is true.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-136","question":"A courier claims an average delivery time of 30 minutes. A sample of 64 deliveries has a mean of 31.5 minutes; the population standard deviation is known to be 6 minutes. For a two-tailed test at the 5% level, what is the test statistic and the decision?","options":["z = 2.0; do not reject H0 because 2.0 < 2.58","z = 2.0; reject H0","z = 16.0; reject H0","z = 0.25; do not reject H0"],"answer":1,"explanation":"Standard error = 6/√64 = 0.75. z = (31.5 − 30)/0.75 = 2. The 5% two-tailed critical value is 1.96, and 2.0 > 1.96, so reject H0. 2.58 is the 1% critical value; 0.25 forgets to divide by the standard error.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-137","question":"A survey must estimate the share of customers who would switch brands to within ±2 percentage points at 95% confidence. With no prior estimate (use p = 0.5), what is the minimum sample size?","options":["49","2,401","4,802","2,500"],"answer":1,"explanation":"n = z² p(1 − p)/E² = 1.96² × 0.25/0.02² = 0.9604/0.0004 = 2,401. Using z = 2 gives 2,500; using p(1 − p) = 0.5 gives 4,802; forgetting to square E gives 49.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-138","question":"A sample of 100 invoices has a mean processing time of 250 minutes with a standard deviation of 40 minutes. What is the 95% confidence interval for the mean processing time?","options":["249.22 to 250.78 minutes","171.60 to 328.40 minutes","243.42 to 256.58 minutes","242.16 to 257.84 minutes"],"answer":3,"explanation":"Standard error = 40/√100 = 4. CI = 250 ± 1.96 × 4 = 250 ± 7.84. Using σ instead of the standard error gives the much wider 171.60–328.40; 1.645 is the 90% multiplier.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-139","question":"H0: μ = 100 against H1: μ > 100, with σ = 10, n = 25 and α = 0.05. If the true mean is actually 105, what is the power of the test (approximately)?","options":["0.80","0.95","0.20","0.64"],"answer":0,"explanation":"SE = 10/5 = 2. Reject when x̄ > 100 + 1.645 × 2 = 103.29. If μ = 105: P(x̄ > 103.29) = P(Z > -0.855) ≈ 0.80. That is the power; β = 0.20 is the Type II error probability.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-140","question":"Assertion (A): With the sample size fixed, lowering the significance level from 5% to 1% raises the probability of a Type II error.\nReason (R): A smaller significance level moves the critical value closer to the hypothesised mean.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A is true: a stricter α makes rejection harder, so false null hypotheses are kept more often (β rises). R is false: a smaller α moves the critical value further from the hypothesised mean (1.96 → 2.58 standard errors), widening the acceptance region.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-141","question":"Across 36 months, a retailer's ice-cream sales and air-conditioner sales have a correlation of 0.9. Which conclusion is most defensible?","options":["Ice-cream promotions will raise AC sales","The correlation proves the two products are complements","AC sales cause ice-cream sales","Both may be driven by a third factor such as temperature"],"answer":3,"explanation":"Correlation does not establish causation. A common driver (hot weather) can move both series together.","difficulty":"easy","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-142","question":"A sales pipeline has four deals: ₹10 lakh (win probability 0.5), ₹20 lakh (0.3), ₹5 lakh (0.9) and ₹40 lakh (0.1). What is the expected (probability-weighted) pipeline value?","options":["₹45 lakh","₹75 lakh","₹19.5 lakh","₹18.75 lakh"],"answer":2,"explanation":"Expected value = 5 + 6 + 4.5 + 4 = ₹19.5 lakh. ₹75 lakh is the unweighted total; ₹18.75 lakh is its simple average.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-143","question":"Two warehouses face independent daily demand with standard deviations of 30 and 40 units. Each holds safety stock of 2σ. If both are served from one central warehouse (same z, same lead time), how many units of safety stock are saved?","options":["20 units","40 units","70 units","0 units"],"answer":1,"explanation":"Separate: 2 × 30 + 2 × 40 = 140. Pooled σ = √(30² + 40²) = 50, so central safety stock = 2 × 50 = 100. Saving = 40 units. Variances add, standard deviations do not, which is the risk-pooling effect.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-144","question":"For a set of order values, Q1 = ₹40 and Q3 = ₹70 (in ₹ hundred). By the 1.5 × IQR rule, which value is an outlier?","options":["118","112","100","−4"],"answer":0,"explanation":"IQR = 30; fences = 40 − 45 = −5 and 70 + 45 = 115. Only 118 lies outside; 112 and −4 are just inside the fences.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-145","question":"Order values have mean ₹800 and standard deviation ₹300. What is the approximate probability that the average of a random sample of 36 orders exceeds ₹900?","options":["4.55%","2.28%","15.87%","36.94%"],"answer":1,"explanation":"By the central limit theorem, the sample mean has SE = 300/√36 = 50. z = (900 − 800)/50 = 2 → P ≈ 2.28%. 36.94% is the chance that a single order exceeds ₹900.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-146","question":"Team A converted 40 of 100 small-business leads and 10 of 100 enterprise leads. Team B converted 15 of 30 small-business leads and 30 of 170 enterprise leads. Which statement is correct?","options":["B is better in both segments and overall","A and B have the same overall conversion rate","A is better in both segments and overall","B has the higher rate in both segments but the lower overall rate, because most of its leads are enterprise leads"],"answer":3,"explanation":"Small business: A 40%, B 50%. Enterprise: A 10%, B 17.6%. Overall: A 50/200 = 25%, B 45/200 = 22.5%. B wins every segment yet loses overall because its leads are concentrated in the low-conversion segment (Simpson's paradox).","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-147","question":"A shoe retailer wants to decide which single size to stock the most of. Which measure of the customers' shoe sizes is most useful?","options":["Mode","Mean","Range","Standard deviation"],"answer":0,"explanation":"The most frequently demanded size (the mode) is what matters; a mean size of, say, 7.6 may not even exist as a size.","difficulty":"easy","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-148","question":"Daily units sold over five days were 8, 10, 12, 14 and 16. What is the sample standard deviation?","options":["8.00","10.00","3.16","2.83"],"answer":2,"explanation":"Mean = 12; squared deviations 16, 4, 0, 4, 16 sum to 40. Sample variance = 40/(5 − 1) = 10, so s = √10 ≈ 3.16. Dividing by n gives the population value 2.83; 10 is the variance, not the standard deviation.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-149","question":"Of 400 surveyed customers: 90 saw the ad and purchased, 60 did not see it but purchased, 110 saw it but did not purchase, and 140 neither saw it nor purchased. What is the probability that a purchaser saw the ad?","options":["0.45","0.225","0.60","0.375"],"answer":2,"explanation":"Purchasers = 90 + 60 = 150, of whom 90 saw the ad: 90/150 = 0.60. 0.45 is P(purchase | saw ad) = 90/200; 0.225 is the joint probability 90/400.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-150","question":"In an A/B test, version A converts 200 of 2,000 visitors and version B converts 260 of 2,000. Using a pooled two-proportion z-test, two-tailed, which conclusion is correct?","options":["z ≈ 0.30; not significant","z ≈ 2.97; the difference is significant even at the 1% level","z ≈ 2.97; significant at 5% but not at 1%","z ≈ 1.50; not significant at 5%"],"answer":1,"explanation":"Pooled p = 460/4,000 = 0.115. SE = √[0.115 × 0.885 × (1/2,000 + 1/2,000)] = 0.01009. z = (0.13 − 0.10)/0.01009 ≈ 2.97 > 2.576, so it is significant at 1% (and at 5%).","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-151","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =SUMIFS(D2:D7, A2:A7, \"North\", C2:C7, \"Laptop\") return?","options":["270","150","365","330"],"answer":0,"explanation":"SUMIFS adds Sales only where both conditions hold: rows 2 (120) and 7 (150) = 270. 365 is all North sales; 330 is all Laptop sales.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-152","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =COUNTIFS(B2:B7, \"Asha\", D2:D7, \">60\") return?","options":["2","3","0","1"],"answer":3,"explanation":"Asha's rows have Sales 120, 60 and 45. Only 120 is strictly greater than 60, so the count is 1. Treating \">60\" as ≥ 60 gives 2.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-153","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =VLOOKUP(\"Asha\", B2:D7, 3, FALSE) return?","options":["#N/A","120","225","Laptop"],"answer":1,"explanation":"VLOOKUP searches the first column of B2:D7 (Rep) for an exact match and returns the first one it finds, row 2. Column 3 of B:D is Sales → 120. It does not add Asha's other rows (225); column 2 would give 'Laptop'.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-154","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =VLOOKUP(\"Ravi\", A2:D7, 2, FALSE) return?","options":["80","South","Ravi","#N/A"],"answer":3,"explanation":"VLOOKUP always searches the first column of the table array, here column A (Region). 'Ravi' never appears in column A, so an exact-match lookup returns #N/A.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-155","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =INDEX(A2:A7, MATCH(MAX(D2:D7), D2:D7, 0)) return?","options":["North","Laptop","Ravi","6"],"answer":0,"explanation":"MAX(D2:D7) = 150. MATCH finds it at position 6 of D2:D7. INDEX(A2:A7, 6) returns the 6th Region, North. MATCH alone would return 6; Ravi is in column B, not A.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-156","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =SUMPRODUCT((A2:A7=\"North\")+(C2:C7=\"Laptop\"), D2:D7) return?","options":["425","365","695","270"],"answer":2,"explanation":"Adding the two TRUE/FALSE arrays gives 2 for rows that are both North and Laptop (rows 2 and 7), 1 for rows meeting one condition (rows 4 and 5), 0 otherwise. Sum = 2×120 + 95 + 60 + 2×150 = 695. Rows meeting both conditions are counted twice, so this is not a true OR (425); multiplying the arrays would give the AND total, 270.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-157","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =AVERAGEIF(A2:A7, \"North\", D2:D7) return (to two decimals)?","options":["91.67","121.67","365.00","110.00"],"answer":1,"explanation":"North rows: 120, 95, 150 → sum 365 over 3 rows = 121.67. 91.67 averages every row; 110 is the Laptop average.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-158","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =XLOOKUP(\"Asha\", B2:B7, D2:D7, \"None\", 0, -1) return?","options":["45","225","None","120"],"answer":0,"explanation":"The last argument −1 makes XLOOKUP search from the bottom up, so it finds Asha's last row (row 6) and returns its Sales, 45. A normal top-down search returns 120; 'None' would appear only if Asha were missing.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-159","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. A pivot table puts Rep in Rows and 'Average of Sales' in Values, sorted largest to smallest. Which rep appears first?","options":["Asha (3)","Asha (75)","Meena (95)","Ravi (115)"],"answer":3,"explanation":"Averages: Asha (120 + 60 + 45)/3 = 75; Ravi (80 + 150)/2 = 115; Meena 95. Ravi is first. Asha would lead only if the value field were Count of Sales (3 rows).","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-160","question":"Cell C2 contains =A2*$B$1. It is copied to cell D5. What formula does D5 contain?","options":["=B2*$B$1","=B5*$C$1","=B5*$B$1","=A5*$B$1"],"answer":2,"explanation":"Copying from C2 to D5 moves one column right and three rows down. The relative reference A2 becomes B5; the absolute $B$1 does not change.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-161","question":"Cell E3 contains =$A3+B$2. It is copied to cell G6. What formula does G6 contain?","options":["=$A3+D$2","=$C6+D$2","=$A6+D$2","=$A6+D$5"],"answer":2,"explanation":"The move is +2 columns and +3 rows. In $A3 the column is locked and the row moves: $A6. In B$2 the row is locked and the column moves: D$2.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-162","question":"A2:A6 hold 1, 2, 3, 4, 5 and B1:F1 hold 1, 2, 3, 4, 5. Cell B2 contains =$A2*B$1, and it is filled across and down to F6. What value appears in D5?","options":["15","20","16","12"],"answer":3,"explanation":"D5 holds =$A5*D$1. A5 = 4 (A2 = 1, so A5 is the fourth value) and D1 = 3 (B1 = 1, C1 = 2, D1 = 3). 4 × 3 = 12. Reading A5 as 5 and D1 as 4 gives 20.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-163","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. Column E uses =IF(D2>=100, \"High\", IF(D2>=60, \"Medium\", \"Low\")), filled down to E7. How many rows show \"Medium\"?","options":["2","3","1","4"],"answer":1,"explanation":"Labels: 120 High, 80 Medium, 95 Medium, 60 Medium (60 ≥ 60), 45 Low, 150 High → 3 Medium. Treating ≥ 60 as > 60 drops row 5 and gives 2.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-164","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. Column F uses =IF(AND(A2=\"North\", D2>100), \"Bonus\", IF(OR(C2=\"Phone\", D2<50), \"Review\", \"-\")), filled down. How many rows show \"Review\"?","options":["3","4","2","1"],"answer":0,"explanation":"Row 2 Bonus; row 3 Phone → Review; row 4 North but 95 ≤ 100, Phone → Review; row 5 '-'; row 6 45 < 50 → Review; row 7 Bonus. 3 rows show Review. Row 4 is the trap: it fails the Bonus test and falls through to the second IF.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-165","question":"Commission slabs are in F2:G5: F = 0, 50000, 100000, 200000 and G = 0%, 2%, 5%, 8% (sorted ascending). A rep's sales of ₹150,000 are in A1. What does =A1*VLOOKUP(A1, F2:G5, 2, TRUE) return?","options":["#N/A","3,000","12,000","7,500"],"answer":3,"explanation":"With TRUE (approximate match) VLOOKUP returns the row with the largest F value ≤ 150,000, which is 100,000 → 5%. Commission = 150,000 × 5% = 7,500. 8% would need sales of 200,000 or more; an exact match would give #N/A.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-166","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =COUNTIF(D2:D7, \">\"&AVERAGE(D2:D7)) return?","options":["2","0","3","4"],"answer":2,"explanation":"AVERAGE(D2:D7) = 550/6 ≈ 91.67; the & builds the criterion \">91.67\". Values above it: 120, 95, 150 → 3.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-167","question":"What does =LEFT(\"INV-2026-0457\", 3) & \"/\" & RIGHT(\"INV-2026-0457\", 4) return?","options":["INV/2026","INV/0457","INV-/0457","INV/457"],"answer":1,"explanation":"LEFT(…, 3) takes 'INV' and RIGHT(…, 4) takes '0457' (the leading zero is kept because the value is text). & joins them with '/': INV/0457.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-168","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =IFERROR(VLOOKUP(\"Kiran\", B2:D7, 3, FALSE), 0) + SUMIF(B2:B7, \"Ravi\", D2:D7) return?","options":["230","#N/A","80","150"],"answer":0,"explanation":"Kiran is not in column B, so VLOOKUP gives #N/A, which IFERROR turns into 0. SUMIF adds Ravi's Sales: 80 + 150 = 230. Total = 230.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-169","question":"Which Excel function counts the cells in a range that are not empty, whether they hold numbers or text?","options":["COUNTA","COUNTIF","COUNTBLANK","COUNT"],"answer":0,"explanation":"COUNTA counts every non-empty cell; COUNT counts only numeric cells; COUNTBLANK counts empty cells.","difficulty":"easy","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-170","question":"A1:A7 contain: 12; the text NA; 0; 7.5; an empty cell; the logical value TRUE; and '15 (a number stored as text). What does =COUNTA(A1:A7) − COUNT(A1:A7) return?","options":["1","2","4","3"],"answer":3,"explanation":"COUNT counts numeric cells only: 12, 0 and 7.5 → 3 (TRUE in a range and the text '15' are not counted). COUNTA counts all non-empty cells: 6. 6 − 3 = 3.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-171","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). What does SELECT COUNT(*) FROM orders WHERE region = 'North'; return?","options":["2","7","3","4"],"answer":2,"explanation":"Rows 1, 3 and 6 are North, so COUNT(*) returns 3.","difficulty":"easy","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-172","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). What does SELECT COUNT(amount) FROM orders; return?","options":["5","6","0","7"],"answer":1,"explanation":"COUNT(column) skips NULLs. Order 4 has a NULL amount, so the result is 6; COUNT(*) would return 7.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-173","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). What does SELECT AVG(amount) FROM orders WHERE region = 'East'; return?","options":["175","0","350","NULL"],"answer":2,"explanation":"East has orders 4 (NULL) and 7 (350). AVG ignores NULLs, so it averages one value: 350. Treating NULL as 0 would give 175.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-174","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). Which customers does SELECT customer, SUM(amount) FROM orders GROUP BY customer HAVING SUM(amount) > 600; return?","options":["Ravi (700) only","Asha (700) and Ravi (1000)","Asha (700), Ravi (1000) and John (400)","Ravi (1000) only"],"answer":1,"explanation":"Totals: Asha 500 + 200 = 700; Ravi 300 + 700 = 1,000; Meena 350 (NULL ignored); John 400. HAVING keeps groups whose total exceeds 600: Asha and Ravi. 'Ravi (700) only' is what a row-level filter (WHERE amount > 600) would give.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-175","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). What does SELECT region, COUNT(*) FROM orders WHERE amount > 250 GROUP BY region HAVING COUNT(*) >= 2; return?","options":["North 2, South 2 and East 1","North 3 and South 2","South 2 only","North 2 and South 2"],"answer":3,"explanation":"WHERE runs first and keeps amounts above 250: orders 1 (N), 2 (S), 5 (S), 6 (N) and 7 (E); order 3 (200) and the NULL fail. Groups: North 2, South 2, East 1. HAVING COUNT(*) ≥ 2 drops East. North 3 counts order 3, which WHERE has already removed.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-176","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). Table customers(name, tier) has 4 rows: (Asha, Gold), (Ravi, Silver), (Kiran, Gold), (John, Bronze). What does SELECT c.name, COUNT(o.order_id) FROM customers c LEFT JOIN orders o ON c.name = o.customer GROUP BY c.name; return?","options":["4 rows, with Kiran showing 0","5 rows, including Meena with 2","3 rows; Kiran does not appear","4 rows, with Kiran showing 1"],"answer":0,"explanation":"A LEFT JOIN keeps every customer. Kiran has no orders, so the joined row has NULL order_id, and COUNT(o.order_id) gives 0 (COUNT(*) would wrongly give 1). Meena is not in customers, so she does not appear. Result: Asha 2, Ravi 2, Kiran 0, John 1.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-177","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). Table customers(name, tier) has 4 rows: (Asha, Gold), (Ravi, Silver), (Kiran, Gold), (John, Bronze). How many rows does SELECT * FROM customers c INNER JOIN orders o ON c.name = o.customer; return?","options":["7","4","5","28"],"answer":2,"explanation":"An inner join keeps only matching pairs: Asha 2 orders, Ravi 2, John 1 = 5. Kiran has no orders and Meena is not a customer, so neither appears. 28 = 4 × 7 is the cross join.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-178","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). Which orders does SELECT order_id FROM orders WHERE amount IS NOT NULL ORDER BY amount DESC LIMIT 2 OFFSET 1; return?","options":["Orders 5 and 1","Orders 1, 6 and 7","Orders 6 and 7","Orders 1 and 6"],"answer":3,"explanation":"Sorted by amount, highest first: 5 (700), 1 (500), 6 (400), 7 (350), 2 (300), 3 (200). OFFSET 1 skips order 5, and LIMIT 2 returns the next two: orders 1 and 6.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-179","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). What happens when SELECT region, SUM(amount) FROM orders WHERE SUM(amount) > 500 GROUP BY region; is run?","options":["It raises an error, because aggregate functions cannot be used in WHERE","It returns all three regions","It returns North only","It returns North and South"],"answer":0,"explanation":"WHERE filters individual rows before grouping, so it cannot refer to SUM(). The condition belongs in HAVING: … GROUP BY region HAVING SUM(amount) > 500.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-180","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). How many rows does SELECT order_id FROM orders WHERE amount < (SELECT AVG(amount) FROM orders); return?","options":["3","4","2","5"],"answer":1,"explanation":"AVG ignores the NULL: 2,450/6 ≈ 408.33. Amounts below it: 300, 200, 350 and 400 → 4 rows. The NULL row is never returned, because NULL < x is unknown, not true. Treating NULL as 0 would make the average 350 and give only 2 rows.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-181","question":"A consumer-electronics firm's quarterly figures (₹ crore unless stated), Q1 to Q4: revenue 240, 270, 300, 330; cost of goods sold 150, 165, 186, 210; operating expenses 50, 54, 57, 63; units sold (lakh) 4.8, 5.2, 5.6, 6.0. In which quarter was the gross margin percentage highest?","options":["Q4","Q3","Q2","Q1"],"answer":2,"explanation":"Gross margin = (revenue − COGS)/revenue: Q1 90/240 = 37.5%; Q2 105/270 = 38.9%; Q3 114/300 = 38.0%; Q4 120/330 = 36.4%. Q4 has the largest gross profit in rupees but the lowest percentage.","difficulty":"moderate","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-182","question":"A consumer-electronics firm's quarterly figures (₹ crore unless stated), Q1 to Q4: revenue 240, 270, 300, 330; cost of goods sold 150, 165, 186, 210; operating expenses 50, 54, 57, 63; units sold (lakh) 4.8, 5.2, 5.6, 6.0. By what percentage did operating profit grow from Q1 to Q4?","options":["29.8%","37.5%","17.0%","42.5%"],"answer":3,"explanation":"Operating profit = revenue − COGS − opex: Q1 = 240 − 150 − 50 = 40; Q4 = 330 − 210 − 63 = 57. Growth = 17/40 = 42.5%. 37.5% is revenue growth; 29.8% divides by the Q4 figure.","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-183","question":"A consumer-electronics firm's quarterly figures (₹ crore unless stated), Q1 to Q4: revenue 240, 270, 300, 330; cost of goods sold 150, 165, 186, 210; operating expenses 50, 54, 57, 63; units sold (lakh) 4.8, 5.2, 5.6, 6.0. Revenue grew 37.5% from Q1 to Q4. How does this split into volume growth and growth in average realised price per unit?","options":["Volume +25%, price +10%","Volume +12.5%, price +25%","Volume +25%, price +12.5%","Volume +20%, price +15%"],"answer":0,"explanation":"Average price = revenue ÷ units: Q1 = 240 crore ÷ 4.8 lakh = ₹5,000; Q4 = 330 ÷ 6.0 = ₹5,500, i.e. +10%. Volume: 6.0/4.8 = +25%. The effects multiply: 1.25 × 1.10 = 1.375. Subtracting 25 from 37.5 to get a 12.5% price rise treats the growth rates as additive.","difficulty":"very-hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-184","question":"A consumer-electronics firm's quarterly figures (₹ crore unless stated), Q1 to Q4: revenue 240, 270, 300, 330; cost of goods sold 150, 165, 186, 210; operating expenses 50, 54, 57, 63; units sold (lakh) 4.8, 5.2, 5.6, 6.0. Treat COGS as fully variable and operating expenses as fully fixed. At Q4's cost structure, what quarterly revenue is needed to break even?","options":["₹99.00 crore","₹173.25 crore","₹157.50 crore","₹273.00 crore"],"answer":1,"explanation":"Contribution margin ratio = (330 − 210)/330 = 0.3636. Break-even revenue = fixed costs ÷ CM ratio = 63 ÷ 0.3636 = ₹173.25 crore. Dividing by the variable-cost ratio instead gives ₹99.00 crore; 273 just adds COGS and opex.","difficulty":"very-hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-185","question":"A distributor's three warehouses last year: W1 shipped 12,000 orders (11,280 on time), held average inventory of ₹80 lakh and handled COGS of ₹960 lakh; W2 shipped 9,000 (8,370 on time), inventory ₹50 lakh, COGS ₹750 lakh; W3 shipped 15,000 (13,650 on time), inventory ₹120 lakh, COGS ₹1,080 lakh. What is the network's overall on-time delivery rate?","options":["91.00%","93.00%","92.50%","92.67%"],"answer":2,"explanation":"On-time orders = 11,280 + 8,370 + 13,650 = 33,300 out of 36,000 → 92.50%. The simple average of 94%, 93% and 91% (92.67%) ignores that W3, the weakest, ships the most.","difficulty":"moderate","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-186","question":"A distributor's three warehouses last year: W1 shipped 12,000 orders (11,280 on time), held average inventory of ₹80 lakh and handled COGS of ₹960 lakh; W2 shipped 9,000 (8,370 on time), inventory ₹50 lakh, COGS ₹750 lakh; W3 shipped 15,000 (13,650 on time), inventory ₹120 lakh, COGS ₹1,080 lakh. What is the inventory turnover of the network as a whole?","options":["15.00","12.00","9.00","11.16"],"answer":3,"explanation":"Network turns = total COGS ÷ total inventory = 2,790 ÷ 250 = 11.16. Averaging the three warehouse turns (12, 15, 9) gives 12, which over-weights the small, fast W2.","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-187","question":"A distributor's three warehouses last year: W1 shipped 12,000 orders (11,280 on time), held average inventory of ₹80 lakh and handled COGS of ₹960 lakh; W2 shipped 9,000 (8,370 on time), inventory ₹50 lakh, COGS ₹750 lakh; W3 shipped 15,000 (13,650 on time), inventory ₹120 lakh, COGS ₹1,080 lakh. If W3 raises its own inventory turnover to 12 while handling the same COGS, what will network turnover become?","options":["12.00","12.68","13.00","11.16"],"answer":1,"explanation":"W3's inventory falls to 1,080/12 = ₹90 lakh, so network inventory = 80 + 50 + 90 = ₹220 lakh. Turns = 2,790/220 = 12.68. Averaging 12, 15 and 12 gives 13, which is not how a network ratio is formed.","difficulty":"very-hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-188","question":"A distributor's three warehouses last year: W1 shipped 12,000 orders (11,280 on time), held average inventory of ₹80 lakh and handled COGS of ₹960 lakh; W2 shipped 9,000 (8,370 on time), inventory ₹50 lakh, COGS ₹750 lakh; W3 shipped 15,000 (13,650 on time), inventory ₹120 lakh, COGS ₹1,080 lakh. What share of the network's late orders comes from W3?","options":["50.0%","41.7%","33.3%","26.7%"],"answer":0,"explanation":"Late orders: W1 720, W2 630, W3 1,350; total 2,700. W3's share = 1,350/2,700 = 50.0%. 41.7% is W3's share of all shipments.","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-189","question":"A product market was worth ₹800 crore in 2025 and ₹920 crore in 2026. Market shares in 2025: brand A 30%, B 25%, C 20%, others 25%. In 2026: A 28%, B 27%, C 22%, others 23%. By what percentage did brand A's revenue change from 2025 to 2026?","options":["Rose 15.00%","Rose 7.33%","Fell 6.67%","Fell 2.00%"],"answer":1,"explanation":"A's revenue: 0.30 × 800 = ₹240 crore → 0.28 × 920 = ₹257.6 crore, a rise of 7.33%. Its share fell 2 points (6.67% in relative terms), but the 15% market growth more than offset it.","difficulty":"very-hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-190","question":"A product market was worth ₹800 crore in 2025 and ₹920 crore in 2026. Market shares in 2025: brand A 30%, B 25%, C 20%, others 25%. In 2026: A 28%, B 27%, C 22%, others 23%. By what percentage did the combined revenue of 'others' change from 2025 to 2026?","options":["Fell 2.0%","Rose 15.0%","Rose 5.8%","Fell 8.0%"],"answer":2,"explanation":"Others: 0.25 × 800 = ₹200 crore → 0.23 × 920 = ₹211.6 crore, so revenue rose 5.8% (1.15 × 0.23/0.25 = 1.058). The 8% figure is the relative fall in share, which is not the same as a fall in revenue.","difficulty":"very-hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-191","question":"Assertion (A): A rise in the holding cost per unit raises the economic order quantity.\nReason (R): Annual holding cost increases as the order quantity increases.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"A is false: EOQ = √(2DS/H), so a higher H lowers EOQ (order smaller lots more often). R is true: annual holding cost = QH/2 rises with Q, which is exactly why a higher H pushes the optimum down.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-192","question":"Assertion (A): A higher smoothing constant α makes an exponential-smoothing forecast smoother.\nReason (R): A higher α puts more weight on the most recent demand.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"A is false: a higher α reacts faster and follows random noise more closely, so the forecast is less smooth. R is true: F(t+1) = αA(t) + (1 − α)F(t).","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-193","question":"Assertion (A): In an M/M/1 queue, raising utilisation from 80% to 90% more than doubles the average number waiting in the queue.\nReason (R): Lq = ρ²/(1 − ρ), which grows without bound as ρ approaches 1.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"At ρ = 0.8, Lq = 0.64/0.2 = 3.2; at ρ = 0.9, Lq = 0.81/0.1 = 8.1, about 2.53 times as many. A is true and follows from R: the 1 − ρ denominator shrinks fast near full utilisation.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-194","question":"Assertion (A): A Six Sigma process produces about 3.4 defects per million opportunities.\nReason (R): Six Sigma improvement projects follow the DMAIC cycle.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both statements are true, but DMAIC is the project method; it does not explain why six sigma corresponds to 3.4 DPMO. That figure comes from a 4.5σ one-sided tail after allowing a 1.5σ drift of the mean.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-195","question":"Assertion (A): For household income data, the median is usually a better measure of the typical value than the mean.\nReason (R): For any data set, the median equals the mode.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A is true: income is right-skewed, and a few very high incomes pull the mean up. R is false: the median and mode coincide only for some (for example symmetric unimodal) distributions.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-196","question":"A bottleneck machine has 2,400 minutes a month. Product X earns a contribution of ₹60 and needs 6 bottleneck minutes; Y earns ₹40 and needs 3 minutes; Z earns ₹90 and needs 10 minutes. Monthly demand is 200 X, 300 Y and 150 Z. What is the maximum monthly contribution?","options":["₹26,700","₹37,500","₹22,500","₹24,000"],"answer":0,"explanation":"Rank by contribution per bottleneck minute: Y 40/3 = 13.33, X 60/6 = 10, Z 90/10 = 9. Make all 300 Y (900 min) and all 200 X (1,200 min); the remaining 300 min make 30 Z. Contribution = 12,000 + 12,000 + 2,700 = ₹26,700. Ranking by contribution per unit (Z first) gives only ₹22,500; ₹37,500 ignores the capacity limit.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-197","question":"An e-commerce firm receives 600 returns a day, and each pending return carries an average refund of ₹1,500 owed to the customer. A return currently takes 4 days from receipt to refund. If this is cut to 2.5 days, by how much does the average value of pending refunds fall?","options":["₹22.5 lakh","₹9 lakh","₹13.5 lakh","₹36 lakh"],"answer":2,"explanation":"Little's law: pending returns = 600 × 4 = 2,400 now and 600 × 2.5 = 1,500 after, a fall of 900. Value = 900 × ₹1,500 = ₹13.5 lakh. ₹22.5 lakh is the new level, not the reduction.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-198","question":"A buyer scores three vendors out of 10 on cost (weight 40%), quality (35%) and delivery (25%). V1: 8, 6, 9. V2: 6, 9, 7. V3: 7, 8, 8. Which vendor has the highest weighted score?","options":["V2, 7.30","V3, 7.60","V1, 7.55","V1, 7.67"],"answer":1,"explanation":"Weighted scores: V1 = 3.2 + 2.1 + 2.25 = 7.55; V2 = 2.4 + 3.15 + 1.75 = 7.30; V3 = 2.8 + 2.8 + 2.0 = 7.60. V3 wins narrowly. Unweighted averages tie V1 and V3 at 7.67.","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-199","question":"Which supply-chain metric is calculated as 365 ÷ annual inventory turnover?","options":["Days of inventory on hand","Perfect-order rate","Days sales outstanding","Order fill rate"],"answer":0,"explanation":"365 ÷ (COGS/average inventory) converts turnover into the number of days the average stock would last. Days sales outstanding uses receivables and sales instead.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-200","question":"A firm has days inventory outstanding of 45, days sales outstanding of 30 and days payables outstanding of 50. If it cuts inventory by 5 days and negotiates 10 more days of credit from suppliers, what is its new cash-to-cash cycle?","options":["130 days","20 days","40 days","10 days"],"answer":3,"explanation":"Cash-to-cash = DIO + DSO − DPO = 45 + 30 − 50 = 25 days now. New = 40 + 30 − 60 = 10 days. Adding payables instead of subtracting them leads to figures like 130.","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-201","question":"A firm compares two plant sites on four factors with weights: labour cost 0.30, proximity to market 0.25, infrastructure 0.25 and tax incentives 0.20. Scores out of 100 — Nashik: 70, 85, 60, 80; Hosur: 80, 65, 75, 70. Using the factor-rating method, which site wins and with what weighted score?","options":["Nashik, 73.25","Hosur, 73.00","Hosur, 72.50","Nashik, 73.75"],"answer":0,"explanation":"Nashik = 0.30×70 + 0.25×85 + 0.25×60 + 0.20×80 = 21 + 21.25 + 15 + 16 = 73.25. Hosur = 24 + 16.25 + 18.75 + 14 = 73.00. The margin is only 0.25 points, so a small change in any weight could flip the decision.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-202","question":"A distributor ships 300 tonnes a year to market A at grid point (20, 40), 500 tonnes to market B at (60, 10) and 200 tonnes to market C at (80, 70). Where is the centre of gravity for its new warehouse?","options":["(53.3, 40)","(52, 31)","(31, 52)","(56, 38)"],"answer":1,"explanation":"X = (20×300 + 60×500 + 80×200) ÷ 1,000 = 52,000 ÷ 1,000 = 52. Y = (40×300 + 10×500 + 70×200) ÷ 1,000 = 31,000 ÷ 1,000 = 31. A plain average of the coordinates, ignoring volumes, gives (53.3, 40); swapping the axes gives (31, 52).","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-203","question":"Four stores receive these monthly shipments: S1 at (10, 50) gets 400, S2 at (40, 20) gets 250, S3 at (70, 60) gets 350 and S4 at (90, 10) gets 200. The firm will pick the available site closest (straight-line) to the centre of gravity. Available sites: P (45, 40), Q (55, 35), R (35, 30), S (50, 25). Which site is chosen?","options":["Q","R","P","S"],"answer":2,"explanation":"Centre of gravity: X = (4,000 + 10,000 + 24,500 + 18,000) ÷ 1,200 = 47.08; Y = (20,000 + 5,000 + 21,000 + 2,000) ÷ 1,200 = 40. Distances: P ≈ 2.1, Q ≈ 9.4, R ≈ 15.7, S ≈ 15.3, so P is nearest. Ignoring shipment volumes gives the centre (52.5, 35), which would wrongly point to Q.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-204","question":"Three candidate locations have these annual fixed costs and variable costs per unit — A: ₹30 lakh and ₹750; B: ₹50 lakh and ₹500; C: ₹80 lakh and ₹300. Over what range of annual volume is location B the lowest-cost choice?","options":["8,000 to 11,111 units","11,111 to 15,000 units","Above 15,000 units","8,000 to 15,000 units"],"answer":3,"explanation":"A = B when 30L + 750Q = 50L + 500Q → Q = 20L ÷ 250 = 8,000. B = C when 50L + 500Q = 80L + 300Q → Q = 30L ÷ 200 = 15,000. Below 8,000 A is cheapest, between 8,000 and 15,000 B is cheapest, and above 15,000 C wins. The A–C crossover (≈ 11,111) is irrelevant because B is cheaper than both there.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-205","question":"Locations A, B and C have annual fixed costs of ₹30 lakh, ₹50 lakh and ₹80 lakh and variable costs of ₹750, ₹500 and ₹300 per unit. Expected volume is 12,000 units a year. Which location should be chosen and what is its total annual cost?","options":["C, ₹116 lakh","A, ₹120 lakh","B, ₹110 lakh","C, ₹110 lakh"],"answer":2,"explanation":"Total cost = fixed + variable × 12,000. A = 30 + 90 = ₹120 lakh; B = 50 + 60 = ₹110 lakh; C = 80 + 36 = ₹116 lakh. B is cheapest. Choosing C because it has the lowest variable cost ignores its much larger fixed cost at this volume.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-206","question":"Quarterly demand is 1,400, 2,000, 1,800 and 2,000 units. Each worker makes 100 units a quarter and the firm starts with 15 workers. Hiring costs ₹3,000 per worker, a layoff ₹5,000 per worker, and holding ₹50 per unit per quarter on ending inventory. Plan 1 (chase) matches output to demand each quarter. Plan 2 (level) sets one constant workforce from Q1 that meets total demand with no shortages. Regular wages are the same in both plans. Which plan is cheaper, and by how much?","options":["Chase, by ₹10,000","Level, by ₹10,000","Chase, by ₹1,000","Level, by ₹6,000"],"answer":0,"explanation":"Chase: workers needed 14, 20, 18, 20 → lay off 1, hire 6, lay off 2, hire 2. Cost = 8 × 3,000 + 3 × 5,000 = ₹39,000. Level: 7,200 ÷ 4 = 1,800 a quarter = 18 workers (hire 3 = ₹9,000). Ending inventory 400, 200, 200, 0 → 800 × 50 = ₹40,000. Level total = ₹49,000, so chase is cheaper by ₹10,000. Forgetting the level plan's hiring cost shrinks the gap to ₹1,000. Both plans use 72 worker-quarters, so wages cancel.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-207","question":"A firm produces at a constant rate equal to average demand. Quarterly demand is 1,000, 1,400, 1,600 and 1,200 units, and there is no opening stock. Ending inventory costs ₹40 per unit per quarter and each unit backordered at quarter-end costs ₹100 per quarter. What is the total inventory-plus-backorder cost for the year?","options":["₹20,000","₹24,000","₹40,000","₹30,000"],"answer":3,"explanation":"Output = 5,200 ÷ 4 = 1300 a quarter. Ending position: Q1 +300, Q2 +200, Q3 −100 (backorder), Q4 0. Holding = (300 + 200) × 40 = ₹20,000; backorder = 100 × 100 = ₹10,000; total ₹30,000. Ignoring the backorder gives ₹20,000; charging the shortage at the holding rate gives ₹24,000.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-208","question":"For one week, an item's gross requirement is 120 units. On-hand stock is 35, a scheduled receipt of 25 is due that week, and the firm keeps safety stock of 10. What is the net requirement?","options":["60","70","50","95"],"answer":1,"explanation":"Net requirement = gross − on hand − scheduled receipts + safety stock = 120 − 35 − 25 + 10 = 70. Leaving out safety stock gives 60, subtracting it gives 50, and forgetting the scheduled receipt gives 95.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-209","question":"Product A needs 2 units of B and 3 units of C. Each B needs 2 units of D; each C needs 1 unit of D and 4 units of E. An order for 50 A arrives. On hand: 20 B, 0 C and 30 D. What is the net requirement of D?","options":["320","280","310","350"],"answer":1,"explanation":"Net B = 2 × 50 − 20 = 80; net C = 3 × 50 = 150. Gross D = 2 × 80 + 1 × 150 = 310; net D = 310 − 30 = 280. Ignoring the B on hand gives gross D of 350 and net 320; forgetting the D on hand leaves 310.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-210","question":"Each unit of X needs 2 Y and 1 Z. Each Y needs 3 W. Each Z needs 2 W and 1 Y. With no stock on hand, how many units of W are needed for 40 units of X?","options":["320","400","480","440"],"answer":3,"explanation":"Y appears twice: 2 per X directly plus 1 inside each Z, so Y = 80 + 40 = 120. W = 3 × 120 (from Y) + 2 × 40 (from Z) = 360 + 80 = 440. Missing the Y inside Z gives 3 × 80 + 80 = 320.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-211","question":"Net requirements over six weeks are 50, 60, 70, 60, 95 and 75 units. Setup cost is ₹200 per order and holding cost is ₹1 per unit per week, charged on ending inventory. Orders arrive at the start of the week they are needed. Using a periodic order quantity that covers two weeks per order, what is the total cost over the six weeks?","options":["₹795","₹1,200","₹845","₹600"],"answer":0,"explanation":"Orders: week 1 (50 + 60 = 110), week 3 (70 + 60 = 130), week 5 (95 + 75 = 170). Ending inventory is 60 after weeks 1, 3 and 75 after week 5 (zero otherwise) → holding = 60 + 60 + 75 = ₹195. Setups = 3 × 200 = ₹600. Total ₹795. Lot-for-lot costs 6 × 200 = ₹1,200; a three-week POQ costs ₹845.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-212","question":"An item has gross requirements of 40, 0, 60, 30, 0 and 80 units in weeks 1–6. On-hand stock is 50, a scheduled receipt of 20 arrives in week 3, the lot size is a fixed 50 units (more lots if needed), lead time is 2 weeks and safety stock is zero. What are the planned order releases, and what is the projected on-hand at the end of week 6?","options":["Weeks 3, 4 and 6 (50 each); 10 units","Weeks 1, 2 and 4 (50, 50, 100); 40 units","Weeks 1, 2 and 4 (50 each); 10 units","Weeks 2, 3 and 5 (50 each); 10 units"],"answer":2,"explanation":"Projected on-hand: wk1 10, wk2 10, wk3 10 + 20 − 60 = −30 → receive 50 → 20, wk4 20 − 30 = −10 → receive 50 → 40, wk5 40, wk6 40 − 80 = −40 → receive 50 → 10. Planned receipts in weeks 3, 4, 6 are released 2 weeks earlier: weeks 1, 2, 4. Ignoring the scheduled receipt forces 100 in week 6 and leaves 40; listing the receipt weeks forgets the lead-time offset.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-213","question":"Five jobs go through machine M1 then M2. Times (hours) on M1, M2: A 5, 2; B 1, 6; C 9, 7; D 3, 8; E 10, 4. What sequence does Johnson's rule give?","options":["A–E–C–D–B","B–D–E–C–A","B–A–D–C–E","B–D–C–E–A"],"answer":3,"explanation":"Pick the smallest remaining time: B's 1 (on M1) → first; A's 2 (on M2) → last; D's 3 (M1) → second; E's 4 (M2) → second last; C fills the middle. Sequence B–D–C–E–A.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-214","question":"Five jobs go through machine M1 then M2. Times (hours) on M1, M2: A 5, 2; B 1, 6; C 9, 7; D 3, 8; E 10, 4. Using the Johnson sequence, what is the makespan and by how many hours does it beat processing the jobs in the order A–B–C–D–E?","options":["34 hours; 4 hours shorter","30 hours; 3 hours shorter","30 hours; 4 hours shorter","28 hours; 6 hours shorter"],"answer":2,"explanation":"Sequence B–D–C–E–A. M1 finishes at 1, 4, 13, 23, 28. M2: B 1–7, D 7–15, C 15–22, E 23–27, A 28–30 → makespan 30. In order A–B–C–D–E, M1 ends 5, 6, 15, 18, 28 and M2: 5–7, 7–13, 15–22, 22–30, 30–34 → 34. Saving = 4 hours. (M2 idles 3 hours under Johnson — that is not the saving.)","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-215","question":"Five jobs wait at one machine (processing days; due day, all available now): P 6 (10), Q 2 (6), R 8 (18), S 3 (15), T 9 (23). What is the average flow time under the SPT rule?","options":["13.6 days","13 days","5.6 days","28 days"],"answer":1,"explanation":"SPT order Q, S, P, R, T: completions 2, 5, 11, 19, 28. Average flow time = 65 ÷ 5 = 13 days. EDD (Q, P, S, R, T) gives 13.6; 5.6 is the mean processing time and 28 is the makespan.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-216","question":"Five jobs wait at one machine (processing days; due day, all available now): P 6 (10), Q 2 (6), R 8 (18), S 3 (15), T 9 (23). Compare SPT and EDD. Which statements are correct?\nI. SPT gives the lower average flow time.\nII. EDD gives the lower total tardiness.\nIII. Both rules give the same makespan.\nIV. EDD leaves no job tardy.","options":["I, II and III only","I and II only","I, III and IV only","II, III and IV only"],"answer":0,"explanation":"SPT (Q, S, P, R, T): completions 2, 5, 11, 19, 28 → flow 13.0, tardiness 0, 0, 1, 1, 5 = 7 (3 tardy jobs). EDD (Q, P, S, R, T): completions 2, 8, 11, 19, 28 → flow 13.6, tardiness 0, 0, 0, 1, 5 = 6 (2 tardy jobs). Makespan is 28 for any order. IV fails because R and T are still late.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-217","question":"Five jobs wait at one machine (processing days; due day, all available now): P 6 (10), Q 2 (6), R 8 (18), S 3 (15), T 9 (23). Using Moore–Hodgson's algorithm to minimise the number of tardy jobs, what is the minimum number of tardy jobs and which job is pushed to the end?","options":["1; job R","2; jobs R and T","0; no job","1; job T"],"answer":0,"explanation":"Start with EDD: Q, P, S, R, T → completions 2, 8, 11, 19, 28. The first tardy job is R (19 > 18). Remove the longest job so far (R, 8 days) and put it at the end. New schedule Q, P, S, T, R → completions 2, 8, 11, 20, 28: only R is late. Zero is impossible: Q, P, S and R are all due by day 18 but need 19 days of work together, so at least one of them must be late. Hence 1 is the minimum.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-218","question":"Four jobs pass through M1, M2 and M3 in that order. Times (hours): J1 8, 3, 6; J2 5, 4, 7; J3 6, 2, 5; J4 7, 5, 9. Using Johnson's rule extended to three machines (check its condition first), what are the sequence and the makespan?","options":["J2–J4–J1–J3; 40 hours","J2–J4–J1–J3; 37 hours","J3–J2–J4–J1; 37 hours","J1–J2–J3–J4; 40 hours"],"answer":1,"explanation":"Condition: min M1 time (5) ≥ max M2 time (5), so the method applies. Form G = M1 + M2 and H = M2 + M3: J1 (11, 9), J2 (9, 11), J3 (8, 7), J4 (12, 14). Johnson on (G, H): J3's 7 (H) → last; J2's 9 (G) → first; J1's 9 (H) → second last; J4 in the middle → J2–J4–J1–J3. Simulating: M3 completes at 37 hours (no order does better). The natural order J1–J4 takes 40 hours.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-219","question":"Today is day 20. Four jobs remain (due day; days of work left): A (30; 4), B (26; 8), C (32; 6), D (25; 3). Sequencing by critical ratio, lowest first, what is the order?","options":["D–B–A–C","D–A–C–B","B–D–C–A","B–D–A–C"],"answer":2,"explanation":"CR = (due − today) ÷ work left: A 10/4 = 2.5, B 6/8 = 0.75, C 12/6 = 2.0, D 5/3 ≈ 1.67. Ascending: B–D–C–A. EDD would give D–B–A–C and SPT D–A–C–B. B is already behind (CR < 1) despite not being due first.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-220","question":"Three markets with annual loads: M1 at (2, 8) with 300, M2 at (6, 2) with 200 and M3 at (9, 6) with 500. Distances are rectilinear. Site X is at (5, 5) and site Y at (7, 6). Which site has the lower total load × distance, and by how much?","options":["X, by 1,000","Y, by 527","Y, by 600","Y, by 1,000"],"answer":3,"explanation":"X: 300 × (3 + 3) + 200 × (1 + 3) + 500 × (4 + 1) = 1,800 + 800 + 2,500 = 5,100. Y: 300 × (5 + 2) + 200 × (1 + 4) + 500 × (2 + 0) = 2,100 + 1,000 + 1,000 = 4,100. Y wins by 1,000. Straight-line distances would give a gap of about 527 instead.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-221","question":"For jobs waiting at a single machine, all available at the start, which sequencing rule minimises the average flow time (and the average number of jobs in the system)?","options":["Earliest due date (EDD)","First come, first served (FCFS)","Shortest processing time (SPT)","Longest processing time (LPT)"],"answer":2,"explanation":"Putting short jobs first reduces the waiting added to every later job, so SPT minimises mean flow time on a single machine. EDD instead minimises maximum lateness; the makespan is the same for every order.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-222","question":"Which statements about aggregate planning strategies are correct?\nI. A chase strategy keeps finished-goods inventory low.\nII. A level strategy suits firms whose hiring and layoff costs are high.\nIII. A chase strategy suits work that needs highly skilled, hard-to-hire staff.\nIV. A level strategy builds inventory in slack periods to cover peak demand.","options":["I, II and IV only","I and III only","II, III and IV only","All four"],"answer":0,"explanation":"Chase changes output (often the workforce) to match demand, so little stock is built (I). Level keeps output steady, building stock in slack periods (IV), which pays when changing the workforce is costly (II). Hiring and firing skilled staff each period is exactly what a chase plan does badly, so III is false.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-223","question":"Markets with annual loads: M1 at (2, 8) with 300, M2 at (6, 2) with 150 and M3 at (9, 6) with 550. Distances are rectilinear. What location minimises total load × distance, and what is that minimum?","options":["(6.45, 6); 4,005","(6, 6); 4,050","(9, 8); 4,550","(9, 6); 3,750"],"answer":3,"explanation":"With rectilinear distance, use the weighted median on each axis (half the load = 500). X sorted: 2 (300), 6 (cumulative 450), 9 (1,000) → median x = 9. Y sorted: 2 (150), 6 (cumulative 700) → median y = 6. Cost at (9, 6) = 300 × (7 + 2) + 150 × (3 + 4) + 0 = 2,700 + 1,050 = 3,750. The centre of gravity (6.45, 6) costs 4,005 — it is not the rectilinear optimum.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-224","question":"Twenty units are life-tested for 1,000 hours each; any unit that fails is replaced at once, so the test covers 20,000 unit-hours, and 4 failures occur. Assume a constant failure rate. Two such units are installed in parallel (either one keeps the system running). What is the probability that the system survives a 1,000-hour mission?","options":["0.670","0.967","0.819","0.960"],"answer":1,"explanation":"Failure rate λ = 4 ÷ 20,000 = 0.0002 per hour (MTBF 5,000 hours). One unit survives 1,000 hours with probability e^(−0.0002 × 1,000) = e^(−0.2) ≈ 0.819. Parallel pair = 1 − (1 − 0.819)² ≈ 0.967. Two units in series give 0.670; using λt = 0.2 as the failure probability (instead of 1 − e^(−0.2)) gives 1 − 0.2² = 0.960.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-225","question":"The first unit of a new aircraft sub-assembly took 100 labour hours. The work follows an 80% unit learning curve. How long should the 8th unit take?","options":["64 hours","51.2 hours","40.96 hours","80 hours"],"answer":1,"explanation":"Each doubling of cumulative output multiplies unit time by 0.8. Unit 8 is three doublings from unit 1: 100 × 0.8³ = 51.2 hours. 64 hours is unit 4 and 40.96 hours is unit 16.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-226","question":"Unit 1 of a custom machine took 200 hours, and production follows an 85% unit learning curve. Approximately how many hours will unit 10 take? (Use Tₙ = T₁ × n^b with b = log 0.85 ÷ log 2.)","options":["104.4 hours","122.8 hours","170.0 hours","116.6 hours"],"answer":3,"explanation":"b = log 0.85 ÷ log 2 ≈ -0.2345. T₁₀ = 200 × 10^(-0.2345) ≈ 200 × 0.5828 ≈ 116.6 hours. 122.8 is unit 8 (three doublings) and 104.4 is unit 16 (four doublings); 170 applies the 85% only once.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-227","question":"A contractor's first unit took 50 hours and work follows a 90% unit learning curve (Tₙ = T₁ × n^b, b = log 0.9 ÷ log 2 ≈ −0.152). Four units are already built. Labour costs ₹400 an hour. What is the labour cost of the next four units (units 5 to 8), to the nearest hundred rupees?","options":["≈ ₹60,400","≈ ₹58,300","≈ ₹71,100","₹80,000"],"answer":0,"explanation":"Unit times: T₅ ≈ 39.15, T₆ ≈ 38.08, T₇ ≈ 37.2, T₈ = 50 × 0.9³ = 36.45 hours. Sum ≈ 150.88 hours × ₹400 ≈ ₹60,400. Using T₈ for all four units understates it (≈ ₹58,300); units 1–4 cost about ₹71,100; ₹80,000 ignores learning altogether.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-228","question":"On a learning-curve job, the 4th unit took 72 hours and the 16th unit took 46.08 hours. What is the learning rate?","options":["64%","90%","80%","85%"],"answer":2,"explanation":"From unit 4 to unit 16 there are two doublings (4 → 8 → 16). So rate² = 46.08 ÷ 72 = 0.64, and rate = 0.8, i.e. 80%. Taking 0.64 itself as the rate forgets that two doublings occurred.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-229","question":"A cooling system has a controller (reliability 0.98) in series with a pair of identical pumps in parallel, each with reliability 0.90; the system works if the controller and at least one pump work. What is the system reliability?","options":["0.7938","0.8820","0.9900","0.9702"],"answer":3,"explanation":"Pump pair = 1 − (0.10 × 0.10) = 0.99. System = 0.98 × 0.99 = 0.9702. Treating everything as series gives 0.98 × 0.9 × 0.9 = 0.7938; one pump only gives 0.882; 0.99 forgets the controller.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-230","question":"A packing line has three stages in series: a feeder (reliability 0.95), a sealing stage with two identical sealers in parallel (each 0.80, either one suffices), and a labeller (0.90). What is the line's reliability, and what would it be without the backup sealer?","options":["0.9120 with backup; 0.684 without","0.8208 with backup; 0.760 without","0.8208 with backup; 0.684 without","0.8550 with backup; 0.684 without"],"answer":2,"explanation":"Sealer pair = 1 − 0.2² = 0.96. Line = 0.95 × 0.96 × 0.90 = 0.8208. Without the backup: 0.95 × 0.80 × 0.90 = 0.684. 0.912 leaves out the labeller; 0.855 drops the sealing stage entirely.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-231","question":"A critical sensor has reliability 0.85. Identical sensors can be installed in parallel (the stage works if at least one works). What is the smallest number of sensors needed for the stage reliability to reach at least 0.999?","options":["3","4","5","7"],"answer":1,"explanation":"Stage reliability = 1 − 0.15ⁿ. n = 3: 1 − 0.003375 = 0.996625 (short). n = 4: 1 − 0.00050625 ≈ 0.99949 ≥ 0.999. So 4 sensors. Thinking each extra unit adds a fixed amount of reliability leads to much larger answers like 7.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-232","question":"A buyer uses a single sampling plan: inspect n = 20 items from each lot and accept the lot if at most c = 1 is defective. If a lot is 5% defective, what is the probability it is accepted (binomial)?","options":["0.736","0.358","0.377","0.264"],"answer":0,"explanation":"P(accept) = P(0) + P(1) = 0.95²⁰ + 20 × 0.05 × 0.95¹⁹ = 0.3585 + 0.3774 ≈ 0.736. 0.358 counts only zero defectives; 0.264 is the rejection probability.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-233","question":"Lots of N = 1,000 are checked with the plan n = 20, c = 1. Rejected lots are screened 100% and all defectives replaced; in accepted lots only the sampled defectives are replaced. If incoming quality is 5% defective, what is the average outgoing quality (AOQ)?","options":["≈ 3.61%","≈ 3.68%","5.00%","≈ 1.32%"],"answer":0,"explanation":"P(accept) ≈ 0.7358. AOQ = p × Pa × (N − n) ÷ N = 0.05 × 0.7358 × 980 ÷ 1,000 ≈ 3.61%. Dropping the (N − n)/N factor gives 3.68%; using the rejection probability gives 1.32%. Rejected lots leave defect-free, which is why AOQ is below 5%.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-234","question":"Match each acceptance-sampling term with its meaning.\n1. AQL  2. LTPD  3. Producer's risk (α)  4. Consumer's risk (β)\na. Probability of accepting a lot whose quality is as bad as the LTPD\nb. Worst average defect level the buyer still regards as satisfactory\nc. Probability of rejecting a lot whose quality is at the AQL\nd. Defect level at which the buyer regards a lot as bad","options":["1-d, 2-b, 3-c, 4-a","1-b, 2-d, 3-c, 4-a","1-b, 2-d, 3-a, 4-c","1-c, 2-a, 3-b, 4-d"],"answer":1,"explanation":"AQL is the acceptable quality level (good lots); LTPD is the lot tolerance percent defective (bad lots). Producer's risk is rejecting a good (AQL) lot; consumer's risk is accepting a bad (LTPD) lot. Swapping the two risks is the classic mistake.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-235","question":"A sampling plan inspects n = 50 items and accepts the lot if c ≤ 2 defectives are found. Using the Poisson approximation, what is the probability of accepting a lot that is 2% defective?","options":["0.736","0.632","0.920","0.981"],"answer":2,"explanation":"np = 50 × 0.02 = 1. P(≤ 2) = e⁻¹ (1 + 1 + 1/2) = 2.5 × 0.3679 ≈ 0.92. 0.736 stops at one defective; 0.632 is 1 − e⁻¹; 0.981 wrongly includes 3 defectives.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-236","question":"Over 40 replenishment cycles a store ran out of an item in 5 cycles. Customers asked for 4,500 units in total, of which 4,230 were supplied immediately from stock. What are the cycle-service level and the fill rate?","options":["Cycle-service level 94%; fill rate 87.5%","Cycle-service level 87.5%; fill rate 87.5%","Cycle-service level 12.5%; fill rate 6%","Cycle-service level 87.5%; fill rate 94%"],"answer":3,"explanation":"Cycle-service level = cycles without a stockout ÷ cycles = 35 ÷ 40 = 87.5%. Fill rate = demand met from stock ÷ total demand = 4,230 ÷ 4,500 = 94%. Fill rate is usually higher, because a stockout cycle still fills most of its demand.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-237","question":"An item is ordered 500 units at a time. Lead-time demand is normal with σ = 40 units, and the firm holds safety stock of 40 units (z = 1). For z = 1, the cumulative normal probability is 0.8413 and the standard loss function L(z) = 0.0833. What are the cycle-service level and the fill rate?","options":["CSL 99.3%; fill rate 84.1%","CSL 84.1%; fill rate 84.1%","CSL 84.1%; fill rate 99.3%","CSL 84.1%; fill rate 91.7%"],"answer":2,"explanation":"CSL = P(lead-time demand ≤ ROP) = 84.1%. Expected shortage per cycle = L(z) × σ = 0.0833 × 40 ≈ 3.33 units. Fill rate = 1 − 3.33 ÷ 500 ≈ 99.3%. 91.7% wrongly uses 1 − L(z). A modest CSL can still give a very high fill rate when the order quantity is large.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-238","question":"An importer buys a part at US$12 FOB. Take ₹83 per dollar. Freight is ₹40 per unit, insurance is 1% of the FOB value, customs duty is 10% of the CIF value, and clearing and handling cost ₹8 per unit. What is the landed cost per unit?","options":["₹1,158.56","₹1,153.56","₹1,147.60","₹1,053.96"],"answer":0,"explanation":"FOB = 12 × 83 = ₹996. Insurance = ₹9.96. CIF = 996 + 40 + 9.96 = ₹1045.96. Duty = 10% of CIF = ₹104.596. Landed = 1045.96 + 104.596 + 8 ≈ ₹1158.56. Charging duty on FOB only gives ₹1153.56; leaving out insurance gives ₹1147.60; skipping duty gives ₹1053.96.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-239","question":"A firm needs 10,000 units of a component a year. A supplier quotes ₹85 per unit. Making it costs, per unit: materials ₹40, direct labour ₹20, variable overhead ₹10 and allocated fixed overhead ₹25. If the part is bought, 60% of that fixed overhead will continue anyway. Should the firm make or buy, and what is the annual saving from the better option?","options":["Buy; saves ₹1,00,000","Make; saves ₹1,50,000","Buy; saves ₹50,000","Make; saves ₹50,000"],"answer":3,"explanation":"Relevant make cost = variable ₹70 + avoidable fixed (40% of ₹25 = ₹10) = ₹80 per unit, versus ₹85 to buy. Making saves ₹5 × 10,000 = ₹50,000. Using the full ₹95 cost wrongly favours buying (₹1,00,000); ignoring the avoidable fixed cost overstates the saving (₹1,50,000).","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-240","question":"A firm needs 10,000 units of a component a year. A supplier quotes ₹85 per unit. Making it costs, per unit: materials ₹40, direct labour ₹20, variable overhead ₹10 and allocated fixed overhead ₹25. If the part is bought, 60% of that fixed overhead will continue anyway. If the part is bought, the freed capacity can make another product earning a contribution of ₹2,00,000 a year. What should the firm do now, and what is the annual advantage?","options":["Make; saves ₹50,000","Buy; saves ₹1,50,000","Buy; saves ₹2,00,000","Buy; saves ₹3,00,000"],"answer":1,"explanation":"Making costs ₹80 × 10,000 = ₹8,00,000 in relevant cost plus ₹2,00,000 of lost contribution (opportunity cost) = ₹10,00,000. Buying costs ₹8,50,000. Buying is better by ₹1,50,000. Ignoring the opportunity cost keeps the old 'make' answer; using the full ₹95 cost as well inflates the gap to ₹3,00,000.","difficulty":"very-hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-241","question":"Making a part needs new equipment with fixed cost ₹6 lakh a year plus ₹45 variable cost per unit. Buying it costs ₹60 per unit. At what annual volume are the two options equally costly?","options":["13,333 units","40,000 units","10,000 units","24,000 units"],"answer":1,"explanation":"Indifference: 6,00,000 + 45Q = 60Q → Q = 6,00,000 ÷ 15 = 40,000. Above it, making is cheaper. Dividing by 45 or 60 instead of the ₹15 difference gives 13,333 or 10,000.","difficulty":"easy","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-242","question":"A firm compares one national warehouse with two regional ones (₹ lakh a year). One warehouse: fixed cost 40, outbound freight 90, inbound freight 20, inventory carrying cost 60. Two warehouses: fixed cost 40 each, outbound freight 55, inbound freight 26; inventory carrying cost follows the square-root law. Which option is cheaper and by about how much?","options":["One warehouse, by ₹11 lakh","Two warehouses, by ₹4.15 lakh","One warehouse, by ₹71 lakh","One warehouse, by ₹35.85 lakh"],"answer":3,"explanation":"Square-root law: inventory with 2 sites = 60 × √2 ≈ ₹84.85 lakh. One site: 40 + 90 + 20 + 60 = ₹210 lakh. Two sites: 80 + 55 + 26 + 84.85 ≈ ₹245.85 lakh. One warehouse is cheaper by ≈ ₹35.85 lakh. Keeping inventory at 60 gives a gap of 11; doubling it gives 71; counting only one fixed cost makes two sites look cheaper.","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-243","question":"Each shipment carries goods worth ₹1 crore, and the firm's inventory carrying cost is 20% a year (365 days). Options per shipment — rail: freight ₹60,000, 12 days in transit; road: ₹85,000, 5 days; air: ₹2,40,000, 1 day. Counting freight plus in-transit carrying cost, which mode is cheapest and about what does it cost per shipment?","options":["Road, ≈ ₹1,12,397","Rail, ₹60,000","Rail, ≈ ₹1,25,753","Air, ≈ ₹2,45,479"],"answer":0,"explanation":"In-transit cost = 1 crore × 20% × days ÷ 365 = ₹5,479 a day. Rail = 60,000 + 12 × 5,479 ≈ ₹1,25,753; road = 85,000 + 5 × 5,479 ≈ ₹1,12,397; air = 2,40,000 + 5,479 ≈ ₹2,45,479. Road wins. Looking at freight alone wrongly picks rail.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-244","question":"A firm can open distribution centre A (fixed cost ₹4,000 a week), B (₹5,000) or both; each has ample capacity. Weekly demand: M1 400 units, M2 300, M3 300. Shipping cost per unit from A: ₹10, ₹14, ₹20 to M1, M2, M3; from B: ₹18, ₹12, ₹9. Each market is served from the cheapest open centre. Which configuration minimises total weekly cost, and what is that cost?","options":["Open B only; ₹18,500","Open both; ₹19,300","Open A only; ₹18,200","Open both; ₹10,300"],"answer":2,"explanation":"A only: 4,000 + 4,000 + 4,200 + 6,000 = ₹18,200. B only: 5,000 + 7,200 + 3,600 + 2,700 = ₹18,500. Both: 9,000 + 4,000 (M1 from A) + 3,600 + 2,700 (M2, M3 from B) = ₹19,300. Both has the lowest freight (₹10,300) but the second fixed cost outweighs the saving.","difficulty":"very-hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-245","question":"Daily demand for a spare part is 0, 1, 2 or 3 units with probabilities 0.10, 0.30, 0.40 and 0.20. Random numbers 00–99 are assigned in that order, starting at 00 (so 0 units = 00–09, and so on). Using the random numbers 10, 87, 40, 06, 79, 59, 92, 39 for eight days, what is the total simulated demand?","options":["12 units","13.6 units","16 units","14 units"],"answer":3,"explanation":"Ranges: 0 → 00–09, 1 → 10–39, 2 → 40–79, 3 → 80–99. The numbers give 1, 3, 2, 0, 2, 2, 3, 1 = 14. Starting the ranges at 01 shifts the boundary numbers 10 and 40 and gives 12; 13.6 is the expected value (1.7 × 8), not the simulated result.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-246","question":"A one-person counter is simulated for six customers. Inter-arrival time: 1 min (RN 00–19), 2 min (20–69), 3 min (70–99). Service time: 1 min (00–29), 2 min (30–69), 3 min (70–99). The clock starts at 0 with the counter empty, and the first customer arrives after the first inter-arrival time. Inter-arrival RNs: 45, 12, 78, 05, 33, 91. Service RNs: 81, 50, 22, 73, 64, 10. What are the total customer waiting time and the counter's idle time until the last customer leaves?","options":["Waiting 5 min; idle 2 min","Waiting 7 min; idle 0 min","Waiting 7 min; idle 2 min","Waiting 9 min; idle 3 min"],"answer":2,"explanation":"Inter-arrivals 2, 1, 3, 1, 2, 3 → arrivals at 2, 3, 6, 7, 9, 12. Services 3, 2, 1, 3, 2, 1. Starts/ends: C1 2–5; C2 5–7 (waits 2); C3 7–8 (1); C4 8–11 (1); C5 11–13 (2); C6 13–14 (1). Total wait = 7 min. The counter is idle only from 0 to 2, so 2 min, and the last customer leaves at 14.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-247","question":"Each month 80% of brand A's buyers stay with A and 20% switch to B; 70% of B's buyers stay and 30% switch to A. Today each brand has 50% of the market. What will A's share be two months from now?","options":["55%","57.5%","60%","65%"],"answer":1,"explanation":"Month 1: A = 0.5 × 0.8 + 0.5 × 0.3 = 55%. Month 2: A = 0.55 × 0.8 + 0.45 × 0.3 = 0.44 + 0.135 = 57.5%. 55% is only one month ahead; 60% is the long-run share, 0.3 ÷ (0.2 + 0.3).","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-248","question":"Monthly switching among three brands (rows = this month's brand, columns = next month's): X → X 0.7, Y 0.2, Z 0.1; Y → X 0.1, Y 0.8, Z 0.1; Z → X 0.2, Y 0.2, Z 0.6. Current shares are X 40%, Y 35%, Z 25%. What are the long-run (steady-state) shares?","options":["X 30%, Y 50%, Z 20%","X 36.5%, Y 41%, Z 22.5%","X 40%, Y 35%, Z 25%","X 33.3%, Y 33.3%, Z 33.3%"],"answer":0,"explanation":"Solve π = πP with shares summing to 1: X = 0.7X + 0.1Y + 0.2Z and Z = 0.1X + 0.1Y + 0.6Z. These give X = 30%, Y = 50%, Z = 20% (the X equation gives Y = 5X/3, the Z equation gives Z = (X + Y)/4 = 2X/3, so X × 10/3 = 1). The first set of wrong figures is just next month's shares; steady state does not depend on today's shares.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-249","question":"In a sheet, A2 = 500, B2 = 0 and B3 = 4. What do =IFERROR(A2/B2, \"n/a\") and =IFERROR(A2/B3, \"n/a\") return?","options":["n/a and 125","#DIV/0! and 125","0 and 125","n/a and n/a"],"answer":0,"explanation":"500/0 raises #DIV/0!, which IFERROR replaces with the text n/a. 500/4 = 125 is not an error, so IFERROR passes it through unchanged.","difficulty":"easy","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-250","question":"Cell C2 holds the value 0.4567 (a gross margin). What does =\"Margin: \" & TEXT(C2, \"0.0%\") return?","options":["Margin: 0.4567","Margin: 45.7%","Margin: 45.67%","Margin: 46%"],"answer":1,"explanation":"Joining text to a raw number shows 0.4567. TEXT with the format \"0.0%\" multiplies by 100 and keeps one decimal, giving 45.7%, and the & operator joins it to the label. 45.67% would need \"0.00%\" and 46% would need \"0%\".","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-251","question":"A1 holds an employee's joining date, 15-Mar-2024, and B1 holds 10-Nov-2026. What does =DATEDIF(A1, B1, \"Y\") & \" yr \" & DATEDIF(A1, B1, \"YM\") & \" mo\" return?","options":["2 yr 8 mo","2 yr 31 mo","2 yr 7 mo","3 yr 7 mo"],"answer":2,"explanation":"\"Y\" counts complete years: 15-Mar-2024 to 15-Mar-2026 = 2. \"YM\" counts complete months left over after those years: to 15-Oct-2026 is 7; 15-Nov is not yet reached, so 7. Using \"M\" (total complete months, 31) gives \"2 yr 31 mo\"; counting the partial month gives 8.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-252","question":"1 December 2026 is a Tuesday. A project tracker computes =NETWORKDAYS(DATE(2026,12,1), DATE(2026,12,31), DATE(2026,12,25)), with 25 December as the only holiday. What does it return?","options":["23","30","21","22"],"answer":3,"explanation":"NETWORKDAYS counts Monday–Friday dates, including both end dates, and drops listed holidays that fall on weekdays. December 2026 has 23 weekdays (it starts on a Tuesday and ends on a Thursday). 25 December 2026 is a Friday, so 23 − 1 = 22. 23 ignores the holiday; 30 is DATEDIF-style day counting.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-253","question":"A planner needs to pack 1,250 units into cartons of 48. What does =ROUNDUP(1250/48, 0) + ROUND(1250/48, 0) + ROUNDDOWN(-1250/48, 0) return?","options":["26","28","27","25"],"answer":2,"explanation":"1250/48 ≈ 26.04. ROUNDUP moves away from zero → 27 (cartons actually needed). ROUND → 26. ROUNDDOWN moves toward zero, so −26.04 becomes −26 (not −27). Total = 27 + 26 − 26 = 27. Treating ROUNDDOWN like FLOOR (−27) gives 26.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-254","question":"B2:B7 hold 45, 80, 62, 80, 30 and 55. What does =RANK(B5, B2:B7) + RANK(B4, B2:B7) + RANK(B4, B2:B7, 1) return?","options":["8","7","9","10"],"answer":0,"explanation":"B5 = 80: tied for the top, both 80s get rank 1. B4 = 62 in descending order comes after the two 80s → rank 3 (RANK skips 2 after a tie). Ascending (order = 1), 62 follows 30, 45, 55 → rank 4. Sum = 1 + 3 + 4 = 8. Dense-style ranking (62 → 2) gives 7; ranking the second 80 as 2 gives 9.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-255","question":"An analyst models a ₹5,00,000 equipment loan at 10% a year, repaid monthly over 3 years, using =PMT(10%/12, 36, -500000). What monthly payment does it return, and what is the total interest paid over the loan?","options":["₹18,055.56; ₹1,50,000","₹16,133.59; ≈ ₹1,50,000","₹13,888.89; ₹0","₹16,133.59; ≈ ₹80,809"],"answer":3,"explanation":"PMT = P × i ÷ (1 − (1 + i)⁻ⁿ) with i = 0.10/12 and n = 36 → ≈ ₹16,133.59 (positive because the loan amount was entered as negative). Total paid = 36 × 16,133.59 ≈ ₹5,80,809, so interest ≈ ₹80,809. A flat 10% on the full principal for 3 years (₹1,50,000) overstates interest because the balance falls each month; ₹13,888.89 is principal ÷ 36 with no interest.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-256","question":"An app's dashboard shows average daily active users of 30,000 and monthly active users of 1,20,000. What is its DAU/MAU 'stickiness' ratio?","options":["4%","25%","400%","75%"],"answer":1,"explanation":"Stickiness = DAU ÷ MAU = 30,000 ÷ 1,20,000 = 25%: the typical monthly user opens the app on about a quarter of the days (≈ 7–8 days a month). Inverting the ratio gives 400%.","difficulty":"easy","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-257","question":"Table emp_sales(rep, region, amount) has 8 rows: (Asha, North, 500), (Ravi, North, 700), (Meena, North, 700), (Kiran, North, 300), (Dev, South, 400), (Sara, South, 900), (John, South, 400), (Neha, South, 200). A query computes, within each region ordered by amount descending, RANK(), DENSE_RANK() and ROW_NUMBER(). What values does Asha get, in that order?","options":["2, 2, 3","3, 2, 3","3, 3, 3","3, 2, 2"],"answer":1,"explanation":"North sorted: Ravi 700, Meena 700, Asha 500, Kiran 300. RANK gives the tie 1, 1 and then skips to 3 for Asha. DENSE_RANK does not skip, so Asha is 2. ROW_NUMBER numbers rows 1, 2, 3, 4 regardless of ties, so Asha is 3.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-258","question":"Table emp_sales(rep, region, amount) has 8 rows: (Asha, North, 500), (Ravi, North, 700), (Meena, North, 700), (Kiran, North, 300), (Dev, South, 400), (Sara, South, 900), (John, South, 400), (Neha, South, 200). How many rows does this query return?\nSELECT rep FROM (SELECT rep, RANK() OVER (PARTITION BY region ORDER BY amount DESC) AS rk FROM emp_sales) t WHERE rk <= 2;","options":["4","6","3","5"],"answer":3,"explanation":"North: Ravi and Meena tie at rank 1; Asha is rank 3, so 2 rows. South: Sara rank 1; Dev and John tie at 400 → both rank 2, so 3 rows. Total 5. ROW_NUMBER would return exactly 4; DENSE_RANK would also keep Asha and return 6.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-259","question":"Table daily(day, amount) has rows (1, 120), (2, 80), (3, 100), (4, 160), (5, 140). What values does AVG(amount) OVER (ORDER BY day ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) give for day 2 and day 5?","options":["100 and 133.33","66.67 and 133.33","NULL and 133.33","100 and 120.00"],"answer":0,"explanation":"The frame for day 2 has only days 1–2 (no earlier row exists), so AVG = (120 + 80) ÷ 2 = 100 — AVG divides by the rows present, not by 3. Day 5 averages days 3–5: (100 + 160 + 140) ÷ 3 ≈ 133.33. 120 is the mean of all five days.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-260","question":"Table orders(dt, amount) has rows (1 Jan, 100), (2 Jan, 50), (2 Jan, 70), (3 Jan, 30). A query adds SUM(amount) OVER (ORDER BY dt) with no frame clause. What running-total value appears on the row (2 Jan, 50)?","options":["150","170","220","250"],"answer":2,"explanation":"With ORDER BY and no frame, the default frame is RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW, which includes all peer rows with the same dt. Both 2 Jan rows therefore show 100 + 50 + 70 = 220. 150 (or 170) is what a ROWS frame would give, depending on the row order; 250 is the grand total.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-261","question":"Table monthly(m, mon, rev) holds Jan 200, Feb 240, Mar 210, Apr 260 (m = 1–4). A query computes ROUND(100.0 * (rev − LAG(rev) OVER (ORDER BY m)) / LAG(rev) OVER (ORDER BY m), 1). Which month shows the highest value, and what does January show?","options":["February (20.0); January shows 0","April (23.8); January shows 0","April (19.2); January shows NULL","April (23.8); January shows NULL"],"answer":3,"explanation":"LAG has no earlier row for January, so it returns NULL and the whole expression is NULL. Growth: Feb 40/200 = 20.0, Mar −30/240 = −12.5, Apr 50/210 ≈ 23.8. Dividing by the current month (50/260) gives 19.2.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-262","question":"An e-commerce funnel for one month: 50,000 visits → 12,000 product views → 3,600 add-to-carts → 1,080 checkouts → 756 purchases. What is the overall conversion rate, and which step has the lowest step conversion?","options":["6.3%; cart → checkout (30%)","1.51%; product view → cart (30%)","1.51%; visit → product view (24%)","2.16%; visit → product view (24%)"],"answer":2,"explanation":"Overall = 756 ÷ 50,000 = 1.512% ≈ 1.51%. Step rates: 12,000/50,000 = 24%, 3,600/12,000 = 30%, 1,080/3,600 = 30%, 756/1,080 = 70%. The weakest step is visit → product view. 6.3% measures from product view, and 2.16% stops at checkout.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-263","question":"Funnel: 50,000 visits → 12,000 product views (24%) → 3,600 add-to-carts (30%) → 1,080 checkouts (30%) → 756 purchases (70%). Three projects are proposed, each changing only its own step and leaving other step rates unchanged: A raises cart → checkout to 40%; B raises visit → view to 26%; C raises checkout → purchase to 80%. Which project adds the most purchases, and how many?","options":["C, +108 purchases","A, +252 purchases","B, +63 purchases","A, +360 purchases"],"answer":1,"explanation":"A: 3,600 × 0.40 × 0.70 = 1,008 → +252. B: 50,000 × 0.26 = 13,000 views → 13,000 × 0.3 × 0.3 × 0.7 = 819 → +63. C: 1,080 × 0.80 = 864 → +108. A wins. +360 counts extra checkouts (3,600 × 10%), not purchases.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-264","question":"Signup cohorts and active users — Jan: 1,000 signups; month 1: 600, month 2: 450, month 3: 400. Feb: 1,500 signups; month 1: 840, month 2: 600. Mar: 2,000 signups; month 1: 1,000 (later months not yet observed). What is the blended month-2 retention rate, weighted by cohort size, across the cohorts that have reached month 2?","options":["42%","42.5%","23.3%","45%"],"answer":0,"explanation":"Only Jan and Feb have reached month 2. Blended = (450 + 600) ÷ (1,000 + 1,500) = 1,050 ÷ 2,500 = 42%. The simple average of 45% and 40% gives 42.5%; dividing by all 4,500 signups (including Mar, which has not reached month 2) gives 23.3%.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-265","question":"Signup cohorts and active users — Jan: 1,000 signups; month 1: 600, month 2: 450, month 3: 400. Feb: 1,500 signups; month 1: 840, month 2: 600. Mar: 2,000 signups; month 1: 1,000 (later months not yet observed). Which statements are correct?\nI. Month-1 retention falls with each newer cohort.\nII. Of Jan users active in month 2, about 88.9% were still active in month 3.\nIII. Month-1 retention weighted by cohort size is 55.3%.\nIV. Because Mar is the largest cohort, its weak month-1 retention pulls the blended month-1 rate below the simple average of the three cohort rates.","options":["I, II and IV only","I, II and III only","I and II only","II, III and IV only"],"answer":0,"explanation":"Month-1 rates: Jan 60%, Feb 56%, Mar 50% — falling (I). Jan month 2 → 3: 400 ÷ 450 ≈ 88.9% (II). Weighted month-1 = (600 + 840 + 1,000) ÷ 4,500 ≈ 54.2%; 55.3% is the simple average, so III is false. The weighted figure is below the simple average because the biggest cohort has the lowest rate (IV).","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-266","question":"A retail chain finds that stores running its new loyalty programme have 18% higher sales than stores without it. The programme was launched first in the stores with the highest footfall. What is the strongest objection to claiming that the programme lifted sales by 18%?","options":["The difference is too small to be meaningful","The stores were not comparable: high-footfall stores would probably outsell others anyway","Loyalty programmes cannot affect sales in the short term","The analysis should have used median sales instead of mean sales"],"answer":1,"explanation":"The programme stores were chosen because they were already strong, so the 18% gap mixes the programme effect with a pre-existing difference (selection bias / confounding by footfall). A fair test compares like-for-like stores, ideally randomly assigned, or looks at the change before and after against a control group.","difficulty":"moderate","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-267","question":"Match each finding with the trap it most illustrates.\n1. Firms with bigger ad budgets have higher sales, but budgets are set at 10% of last year's sales.\n2. Umbrella sales and taxi bookings rise together on the same days.\n3. Employees who volunteered for an optional course later show higher productivity.\n4. Out of 20 dashboard metrics tested, one shows a 'significant' change at the 5% level.\na. Common cause (confounder)  b. Reverse causation  c. Self-selection bias  d. Chance finding from multiple comparisons","options":["1-a, 2-b, 3-c, 4-d","1-b, 2-a, 3-d, 4-c","1-b, 2-a, 3-c, 4-d","1-c, 2-a, 3-b, 4-d"],"answer":2,"explanation":"(1) Sales drive the budget, not the other way round — reverse causation. (2) Rain drives both — a common cause. (3) Keen employees chose the course, so they differ from the rest — self-selection. (4) With 20 tests at 5%, about one false positive is expected by chance.","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-268","question":"A pivot table of last quarter's revenue (₹ lakh) and orders: North–Online 48 (1,200 orders), North–Store 72 (1,600), South–Online 60 (2,000), South–Store 40 (800). Which statements does the pivot support?\nI. South earns a larger share of its revenue online than North does.\nII. Store average order value exceeds online average order value in both regions.\nIII. Online has more orders than stores overall but less revenue.\nIV. South has the higher overall average order value.","options":["I and II only","II, III and IV only","All four","I, II and III only"],"answer":3,"explanation":"Online share: South 60/100 = 60% vs North 48/120 = 40% (I). AOV: North online ₹4,000, store ₹4,500; South online ₹3,000, store ₹5,000 (II). Online 3,200 orders and ₹108 lakh vs store 2,400 orders and ₹112 lakh (III). Overall AOV: North ₹120 lakh ÷ 2,800 ≈ ₹4,286, South ₹100 lakh ÷ 2,800 ≈ ₹3,571, so IV is false.","difficulty":"very-hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-269","question":"A pivot has regions as rows and channels as columns, showing revenue (₹ lakh): North — Online 48, Store 72; South — Online 60, Store 40. If the values are shown as '% of Column Total', what appears in the South–Online cell?","options":["27.3%","60.0%","55.6%","50.0%"],"answer":2,"explanation":"The Online column total is 48 + 60 = 108, so South–Online = 60 ÷ 108 ≈ 55.6%. '% of Grand Total' would give 60 ÷ 220 ≈ 27.3%, and '% of Row Total' 60 ÷ 100 = 60%.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-270","question":"A sales dashboard shows revenue up 10% and order count up 20% versus last month. By how much has the average order value changed?","options":["−8.3%","−10.0%","+8.3%","−9.1%"],"answer":0,"explanation":"AOV = revenue ÷ orders, so the new AOV is 1.10 ÷ 1.20 = 0.9167 times the old one: a change of −8.3%. Simply subtracting growth rates gives −10%; 1 − 1.20/1.10 gives −9.1%. Revenue growth slower than order growth means smaller baskets.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-271","question":"A subscription dashboard shows a steady monthly churn of 5%. ARPU is ₹500 a month and gross margin 60%. Which statements are correct?\nI. About 54% of customers starting a year are still subscribed at its end.\nII. Annual churn is 60%.\nIII. Average customer lifetime is about 20 months.\nIV. A simple customer lifetime value (margin × lifetime) is about ₹6,000.","options":["I, II and III only","II and IV only","All four","I, III and IV only"],"answer":3,"explanation":"Retention compounds: 0.95¹² ≈ 0.540, so about 54% remain and annual churn is about 46%, not 5% × 12 = 60% (II false). Lifetime ≈ 1 ÷ 0.05 = 20 months. CLV ≈ ₹500 × 60% × 20 = ₹6,000.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-272","question":"A SaaS firm started the year with ₹100 lakh of monthly recurring revenue (MRR). During the year: new customers added ₹15 lakh, existing customers expanded by ₹12 lakh, downgrades cut ₹4 lakh and churned customers took away ₹6 lakh. What are the net revenue retention (NRR) and gross revenue retention (GRR)?","options":["NRR 117%; GRR 90%","NRR 102%; GRR 90%","NRR 102%; GRR 94%","NRR 108%; GRR 90%"],"answer":1,"explanation":"Both measure only the opening customer base, so new-customer MRR is excluded. NRR = (100 + 12 − 4 − 6) ÷ 100 = 102%. GRR ignores expansion: (100 − 4 − 6) ÷ 100 = 90%. Including new business gives 117%; leaving out downgrades gives GRR 94%.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-273","question":"A single-server ATM queue (M/M/1) has customers arriving at 24 per hour and served at 30 per hour. What is the probability that more than 3 customers are in the system (queue plus service) at a random moment?","options":["0.512","0.4096","0.5904","0.0819"],"answer":1,"explanation":"In M/M/1, P(n ≥ k) = ρᵏ, so P(n > 3) = P(n ≥ 4) = 0.8⁴ = 0.4096. Using ρ³ = 0.512 counts 'at least 3', and (1 − ρ)ρ⁴ is the probability of exactly 4.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-274","question":"A single-server desk (M/M/1) has λ = 10 per hour and μ = 12 per hour. Demand doubles and the firm buys a machine that exactly doubles the service rate. What happens to the average queue length Lq and the average wait in queue Wq?","options":["Both Lq and Wq are unchanged","Lq doubles and Wq is unchanged","Lq is unchanged and Wq halves","Both Lq and Wq halve"],"answer":2,"explanation":"Lq = ρ²/(1 − ρ) depends only on ρ, which stays 10/12. By Little's law Wq = Lq/λ, and λ has doubled, so Wq falls from 25 to 12.5 minutes.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-275","question":"Customers arrive at 8 per hour (Poisson). Option P: two clerks, each serving 5 per hour (exponential), fed from one common queue (M/M/2). Option Q: one clerk who serves 10 per hour (M/M/1). Which statement is correct?","options":["P is better on both wait in queue and time in system","Q is better on both wait in queue and time in system","Both options give identical waits because total capacity is the same","P has the shorter average wait in queue, but Q has the shorter average time in the system"],"answer":3,"explanation":"Q: Wq = λ/[μ(μ − λ)] = 24 min and W = 1/(μ − λ) = 30 min. P: P₀ = 1/9, Lq ≈ 2.84, so Wq ≈ 21.3 min, but each service takes 12 min, so W ≈ 33.3 min. Pooling cuts queueing, yet the fast single server wins on total time.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-276","question":"An emergency department receives 120 patients a day, arriving evenly round the clock. 30% are admitted and spend on average 6 hours in the department before transfer; the rest spend 3 hours. On average, how many patients are in the department at any moment?","options":["19.5","22.5","468","13.5"],"answer":0,"explanation":"Little's law: λ = 120/24 = 5 per hour, and W = 0.3 × 6 + 0.7 × 3 = 3.9 hours, so L = 5 × 3.9 = 19.5. Averaging 6 and 3 without weights gives 22.5; using 120 per day with W in hours gives 468.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-277","question":"Requests reach a single server (M/M/1) at 22 per hour. Management wants the average number waiting in the queue, Lq, to be at most 2. What is the minimum service rate needed?","options":["33 per hour","27.5 per hour","44 per hour","30.05 per hour"],"answer":3,"explanation":"Lq = ρ²/(1 − ρ) ≤ 2 gives ρ² + 2ρ − 2 ≤ 0, so ρ ≤ √3 − 1 ≈ 0.732 and μ ≥ 22/0.732 ≈ 30.05. Setting L = ρ/(1 − ρ) ≤ 2 instead gives ρ ≤ 2/3 and the trap answer 33.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-278","question":"An automated car wash takes exactly 5 minutes per car (constant service time). Cars arrive at random (Poisson) at 9 per hour. What is the average time a car waits before its wash starts?","options":["7.5 minutes","15 minutes","12.5 minutes","3.75 minutes"],"answer":0,"explanation":"For M/D/1, Lq = ρ²/[2(1 − ρ)] — half the M/M/1 value. ρ = 0.75, so Lq = 1.125 and Wq = 1.125/9 h = 7.5 min. 15 min is the M/M/1 answer; 12.5 min adds the 5-minute wash (time in system).","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-279","question":"A product is forecast with Holt's trend-adjusted exponential smoothing (α = 0.4 for the level, β = 0.3 for the trend). At the end of last month the level was 200 and the trend 10. This month's actual demand is 220. What is the forecast for next month?","options":["224","214","225.2","231.2"],"answer":2,"explanation":"This month's forecast was 200 + 10 = 210. New level = 0.4 × 220 + 0.6 × 210 = 214; new trend = 0.3 × (214 − 200) + 0.7 × 10 = 11.2; next forecast = 225.2. Keeping the old trend gives 224.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-280","question":"An analyst wants a simple exponential-smoothing forecast whose data have the same average age as those of a 9-month simple moving average. Which smoothing constant should she use?","options":["0.111","0.2","0.9","0.25"],"answer":1,"explanation":"Average age of an N-period moving average is (N + 1)/2 = 5 periods; for exponential smoothing it is 1/α. So 1/α = 5 and α = 2/(N + 1) = 0.2. Taking α = 1/N = 0.111 is the common slip.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-281","question":"Annual sales (₹ crore) for years 1 to 5 were 12, 15, 19, 22 and 27. Using a least-squares linear trend, what is the forecast for year 6?","options":["30.75","30.1","33.8","29.5"],"answer":1,"explanation":"With x̄ = 3 and ȳ = 19, slope b = Σ(x − x̄)(y − ȳ)/Σ(x − x̄)² = 37/10 = 3.7 and a = 19 − 3 × 3.7 = 7.9. Year 6: 7.9 + 3.7 × 6 = 30.1. Adding the average year-on-year change to the last value gives 30.75, which over-weights the end points.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-282","question":"Next year's demand is forecast at 4,800 units. The multiplicative seasonal indices for Q1–Q4 are 0.8, 1.1, 1.3 and 0.8. What is the forecast for Q3?","options":["1,200 units","6,240 units","923 units","1,560 units"],"answer":3,"explanation":"Average quarterly demand = 4,800/4 = 1,200; Q3 = 1,200 × 1.3 = 1,560. Applying the index to the annual total gives 6,240; dividing by the index (deseasonalising instead of reseasonalising) gives 923.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-283","question":"Annual demand is 4,800 units, ordering cost ₹400 per order, holding cost ₹12 per unit per year. Customers accept backorders, and the backorder cost is ₹36 per unit per year. What is the optimal order quantity under the planned-shortage EOQ model?","options":["About 566 units","About 490 units","About 653 units","About 1,131 units"],"answer":2,"explanation":"Q* = √(2DS/H) × √((H + B)/B) = 565.7 × √(48/36) ≈ 653. Allowing cheap backorders raises the lot size above the classic EOQ of 566; inverting the ratio gives 490.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-284","question":"An item's EOQ is 700 units, but the supplier ships only in pallets of 500 units, so the buyer must order either 500 or 1,000 units. Which is cheaper in annual ordering-plus-holding cost, and by roughly how much relative to the EOQ cost?","options":["500 units; it costs about 5.7% above the EOQ cost versus about 6.4% for 1,000","1,000 units, because it is closer in ratio terms to the EOQ","Both cost exactly the same because the cost curve is symmetric","500 units; it costs about 28.6% above the EOQ cost versus about 42.9% for 1,000"],"answer":0,"explanation":"Cost relative to the EOQ cost is ½(Q/Q* + Q*/Q): for 500 it is ½(0.714 + 1.4) = 1.0571; for 1,000 it is ½(1.429 + 0.7) = 1.0643. The curve is flat and asymmetric, so the 'percentage gap in quantity' (28.6% vs 42.9%) overstates the cost penalty.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-285","question":"A bakery sells a cake for ₹600 that costs ₹200 to make; unsold cakes are sold next day to a canteen for ₹100. Daily demand is normal with mean 500 and standard deviation 100. Using z = 0.84 for the 80th percentile and z = 0.67 for the 75th, how many cakes should it bake?","options":["567","584","416","500"],"answer":1,"explanation":"Underage cost Cu = 600 − 200 = 400; overage cost Co = 200 − 100 = 100; critical ratio = 400/500 = 0.8, so Q = 500 + 0.84 × 100 = 584. Also deducting the salvage value from the underage cost gives 300/400 = 0.75 and 567; flipping the sign of z gives 416.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-286","question":"Twenty inspected car bodies show a total of 180 paint blemishes. What are the 3-sigma limits of the c-chart for blemishes per body?","options":["UCL = 12, LCL = 6","UCL = 36, LCL = 0","UCL = 27, LCL = 0","UCL = 18, LCL = 0"],"answer":3,"explanation":"c̄ = 180/20 = 9 and for a Poisson count σ = √c̄ = 3, so limits are 9 ± 9: UCL = 18, LCL = 0. Using σ = c̄ = 9 gives 36; using one sigma gives 12 and 6.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-287","question":"Samples of 100 tubes are checked each hour; over many samples the average fraction defective is 4%. What is the upper control limit of the np-chart (number defective per sample)?","options":["10","0.0988","9.88","5.96"],"answer":2,"explanation":"np̄ = 4 and σ = √(np̄(1 − p̄)) = √3.84 ≈ 1.96, so UCL = 4 + 3 × 1.96 ≈ 9.88. Using √np̄ (a c-chart) gives 10; 0.0988 is the p-chart limit; 5.96 is only a one-sigma limit.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-288","question":"A process has Cp = 1.5 and Cpk = 1.0, with a standard deviation of 2 mm. How far is the process mean from the midpoint of the specification range?","options":["3 mm","1.5 mm","6 mm","9 mm"],"answer":0,"explanation":"Cp = (USL − LSL)/6σ = 1.5 gives a half-width of 9 mm. Cpk = (distance to nearer limit)/3σ = 1 gives 6 mm to the nearer limit, so the mean sits 9 − 6 = 3 mm off centre. 6 mm and 9 mm are the two distances themselves.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-289","question":"An assembly averages 0.25 defects per unit, and defects occur at random (Poisson). Approximately what fraction of units come through with zero defects?","options":["77.9%","75.0%","25.0%","97.5%"],"answer":0,"explanation":"Under a Poisson model, yield = P(0 defects) = e^(−DPU) = e^(−0.25) ≈ 0.779. Subtracting DPU from 1 (75%) wrongly treats every defect as falling on a different unit.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-290","question":"Which of these patterns on an X̄ control chart signals that the process may be out of control even though every point lies inside the 3-sigma limits?\nI. Eight consecutive points above the centre line\nII. Six consecutive points steadily increasing\nIII. Points alternating above and below the centre line in a random-looking way","options":["I only","I and II only","II and III only","I, II and III"],"answer":1,"explanation":"A long run on one side of the centre line (shift) and a steady trend are non-random patterns flagged by standard run rules. Points scattered randomly around the centre line are exactly what a stable process produces.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-291","question":"Activities (days; immediate predecessors): A 4 (–), B 6 (–), C 3 (A), D 5 (A), E 4 (B, C), F 6 (D), G 2 (E, F). What are the total float and the free float of activity B?","options":["Total float 5 days, free float 5 days","Total float 1 day, free float 1 day","Total float 4 days, free float 1 day","Total float 5 days, free float 1 day"],"answer":3,"explanation":"Critical path A–D–F–G = 17 days. LS(G) = 15, so LF(E) = 15 and LS(E) = 11; LF(B) = 11 gives LS(B) = 5 and total float 5. Free float = ES(E) − EF(B) = 7 − 6 = 1, because C pushes E's earliest start to day 7.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-292","question":"A project's critical path has three activities with PERT estimates (optimistic, most likely, pessimistic) in weeks: (3, 5, 9), (2, 4, 12) and (6, 8, 10). What is the probability of finishing within 21 weeks? (Use Φ(1.30) ≈ 0.903, Φ(0.80) ≈ 0.788, Φ(0.63) ≈ 0.736.)","options":["About 78.8%","About 73.6%","About 90.3%","About 50%"],"answer":2,"explanation":"Expected times are 5.33, 5 and 8, so T = 18.33 weeks; variances are 1, 2.78 and 0.44, so σ = √4.22 ≈ 2.05. z = (21 − 18.33)/2.05 ≈ 1.3, about 90.3%. Adding the activity standard deviations (σ = 3.33) gives z = 0.80, and dividing by the variance 4.22 gives z ≈ 0.63.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-293","question":"A project has two parallel paths from start to finish: A (6 days) → B (8 days) → C (5 days), and D (7 days) → E (9 days). Crash cost per day and maximum crash: A ₹2,000 (2 days), B ₹1,500 (3 days), C ₹2,500 (1 day), D ₹1,000 (2 days), E ₹1,200 (2 days). What is the minimum extra cost to finish the project in 15 days?","options":["₹6,500","₹7,500","₹5,500","₹8,000"],"answer":1,"explanation":"Path ABC is 19 days, DE 16. Crash B by 3 days (₹4,500) to reach 16, when both paths are critical. The 16th → 15th day needs one day off each path: A (₹2,000) + D (₹1,000) = ₹3,000, total ₹7,500. Forgetting that DE also becomes critical gives ₹6,500.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-294","question":"Maximise Z = 5x + 4y subject to 6x + 4y ≤ 24 (machine hours), x + 2y ≤ 6 (labour hours), x, y ≥ 0. The optimum is Z = 21. What is the shadow price of one extra machine hour?","options":["₹0.75","₹0.5","₹0.83","₹0"],"answer":0,"explanation":"Both constraints bind at x = 3, y = 1.5. Raising machine hours to 25 moves the corner to x = 3.25, y = 1.375, giving Z = 21.75, so the shadow price is 0.75. ₹0.50 is the labour-hour shadow price; ₹0 would apply only to a slack constraint.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-295","question":"A maximisation LP has 3 '≤' constraints and 2 decision variables, and it has a finite optimal solution. Which statements are correct?\nI. Its dual has 2 constraints and 3 variables.\nII. The optimal objective values of the primal and the dual are equal.\nIII. If a primal constraint has positive slack at the optimum, its dual variable (shadow price) is zero.","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":3,"explanation":"Each primal constraint becomes a dual variable and each primal variable a dual constraint (I). Strong duality gives equal optimal values (II), and complementary slackness makes the shadow price of a non-binding constraint zero (III).","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-296","question":"During the simplex method for a maximisation problem, the entering variable has been chosen, but every entry in its column of the constraint rows is zero or negative. What does this indicate?","options":["The problem is infeasible","There are alternative optimal solutions","The problem is unbounded","The current solution is degenerate"],"answer":2,"explanation":"With no positive entry there is no ratio to test, so the entering variable can rise without limit while the objective keeps improving – an unbounded LP. Infeasibility shows up as an artificial variable stuck in the final basis; alternative optima show as a zero reduced cost for a non-basic variable.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-297","question":"Payoffs (₹ lakh) of three strategies under three demand states with probabilities 0.3, 0.5 and 0.2: X: 50, 30, 10; Y: 80, 20, −20; Z: 20, 40, 60. What is the expected value of perfect information?","options":["₹24 lakh","₹26 lakh","₹18 lakh","₹56 lakh"],"answer":2,"explanation":"EMVs: X = 32, Y = 30, Z = 38, so the best is Z at 38. With perfect information the firm picks the best act in each state: 0.3 × 80 + 0.5 × 40 + 0.2 × 60 = 56. EVPI = 56 − 38 = 18. Subtracting X's or Y's EMV gives the traps 24 and 26.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-298","question":"Supplier A provides 60% of a part with a 3% defect rate; supplier B provides the rest with a 5% defect rate. A part picked at random is found defective. What is the probability that it came from B?","options":["0.5263","0.4","0.4737","0.05"],"answer":0,"explanation":"P(defective) = 0.6 × 0.03 + 0.4 × 0.05 = 0.038. P(B | defective) = 0.020/0.038 ≈ 0.5263. The prior 0.4 ignores the evidence, and 0.05 is P(defective | B), the reverse conditional.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-299","question":"A sample of 16 checkouts has a mean basket value of ₹520 with a sample standard deviation of ₹80. H0: μ = ₹480. Critical t-values with 15 degrees of freedom at α = 0.05 are 1.753 (one-tailed) and 2.131 (two-tailed). Which conclusion is correct?","options":["H0 is rejected in both the one-tailed and the two-tailed test","H0 is rejected in the one-tailed test (H1: μ > 480) but not in the two-tailed test","H0 is rejected in neither test","H0 is rejected in the two-tailed test but not in the one-tailed test"],"answer":1,"explanation":"t = (520 − 480)/(80/√16) = 40/20 = 2.0. It exceeds 1.753 but not 2.131, so only the one-tailed test rejects. A two-tailed test splits α between both tails, which makes its cut-off stricter.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-300","question":"A regression on weekly store data gives ln(Sales) = 6.2 + 0.04 × Discount, where Discount is in percentage points. Holding other factors fixed, what does the model imply for one more percentage point of discount?","options":["Sales rise by 0.04 units","Sales rise by about 0.04%","Sales rise by about 40%","Sales rise by about 4%"],"answer":3,"explanation":"In a log-level model a one-unit rise in x multiplies y by e^0.04 ≈ 1.041, i.e. about a 4% increase. Reading the coefficient as a unit change ignores the log; 0.04% confuses it with a log-log elasticity scaled wrongly.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-301","question":"A2:A6 hold the score cut-offs 0, 50, 70, 80, 100 (ascending) and B2:B6 hold the grades E, D, C, B, A. What does =INDEX(B2:B6, MATCH(78, A2:A6, 1)) return?","options":["B","#N/A","C","D"],"answer":2,"explanation":"MATCH with match type 1 returns the position of the largest value ≤ 78 in a sorted list: 70, at position 3. INDEX(B2:B6, 3) is C. Expecting the next cut-off up gives B; #N/A would appear only with match type 0.","difficulty":"moderate","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-302","question":"A2:A6 hold regions North, South, North, North, South; B2:B6 hold prices 120, 90, 80, 150, 200; C2:C6 hold quantities 5, 4, 6, 2, 3. What does =SUMPRODUCT((A2:A6=\"North\")*(B2:B6>100), B2:B6, C2:C6) return?","options":["900","7","1,380","1,500"],"answer":0,"explanation":"The condition array is 1 only for rows 2 and 5 (North and price above 100). SUMPRODUCT multiplies it by price and quantity: 120 × 5 + 150 × 2 = 900. 7 sums only the quantities; 1,380 drops the price filter and 1,500 drops the region filter.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-303","question":"customers(id, name) has rows (1, Asha), (2, Ravi), (3, Meena), (4, Kiran). orders(oid, cid, status) has rows (10, 1, 'paid'), (11, 1, 'refunded'), (12, 2, 'paid'), (13, 3, 'refunded'). Query P: SELECT COUNT(*) FROM customers c LEFT JOIN orders o ON c.id = o.cid WHERE o.status = 'paid'. Query Q is the same but with AND o.status = 'paid' moved into the ON clause (no WHERE). What do P and Q return?","options":["P = 4, Q = 4","P = 2, Q = 4","P = 2, Q = 2","P = 2, Q = 5"],"answer":1,"explanation":"P filters after the join, discarding the NULL rows of unmatched customers, so it behaves like an inner join: 2 rows. In Q the filter is part of the join condition, so every customer is kept – Asha and Ravi matched, Meena and Kiran with NULLs – giving 4.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-304","question":"A press needs a 40-minute setup before each batch and then 2 minutes per unit. It currently runs batches of 100. By what percentage does its hourly capacity rise if the batch size is doubled to 200?","options":["100%","About 9.1%","About 16.7%","About 4.5%"],"answer":1,"explanation":"Capacity = batch ÷ (setup + batch × unit time): 100/240 min = 25/hr, and 200/440 min = 27.27/hr, a rise of about 9.1%. Doubling the batch only spreads the setup more thinly; output cannot exceed 30/hr however big the batch.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-305","question":"A packaging line has an OEE of 60%. Its availability is 80% and its quality rate is 95%. What is its performance efficiency?","options":["About 45.6%","About 75.0%","About 78.9%","About 85.0%"],"answer":2,"explanation":"OEE = availability × performance × quality, so performance = 0.60 ÷ (0.80 × 0.95) ≈ 78.9%. Multiplying the three (0.6 × 0.8 × 0.95 = 45.6%) treats OEE as a factor; 75% ignores the quality rate.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-306","question":"Assembly tasks (time in seconds; immediate predecessors): A 5 (–), B 3 (A), C 4 (A), D 6 (B), E 2 (C), F 5 (D, E). Using the ranked positional weight method, what is the positional weight of task C?","options":["6 seconds","9 seconds","25 seconds","11 seconds"],"answer":3,"explanation":"A task's positional weight is its own time plus the times of all tasks that follow it: C (4) + E (2) + F (5) = 11. Counting only the immediate successor gives 6; 25 is A's weight, since every task follows A.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-307","question":"Two stages are in series. Stage 1 scraps 10% of what it processes, and Stage 2 scraps 5% of what it receives. Scrapped units are not reworked. How many units must enter Stage 1 to get 900 good units out of Stage 2?","options":["1,053","1,035","1,000","990"],"answer":0,"explanation":"Overall yield = 0.90 × 0.95 = 0.855, so input = 900 ÷ 0.855 ≈ 1,052.6, i.e. 1,053 units. Adding the scrap rates (15%) gives 900 × 1.15 = 1,035; dividing by 0.9 only gives 1,000.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-308","question":"Patients arrive at 20 per hour. 60% go to station X (3 nurses, 12 minutes each), 40% go to station Y (3 doctors, 18 minutes each), and every patient then goes to billing station Z (2 clerks, 5 minutes each). Which station has the highest implied utilisation?","options":["X, at 80%","Z, at about 83%","Y, at 80%","Y, at 100%"],"answer":1,"explanation":"Load per hour: X = 12 × 12 = 144 min on 180 available (80%); Y = 8 × 18 = 144 min on 180 (80%); Z = 20 × 5 = 100 min on 120 (83.3%). Z has the shortest task time but sees every patient, so it is the bottleneck.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-309","question":"At a single-server counter (M/M/1), customers arrive at 15 per hour and are served at 20 per hour. What fraction of arriving customers have to wait before their service starts?","options":["25%","56.25%","75%","33.3%"],"answer":2,"explanation":"With Poisson arrivals, an arrival finds the server busy with probability ρ = λ/μ = 0.75. 25% is P₀, the chance the server is idle; 56.25% is ρ², the chance of at least two in the system.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-310","question":"A call centre receives 20 calls an hour, and each call takes an average of 6 minutes. What is the smallest number of agents for which the queue will not grow without limit?","options":["3","2","4","1"],"answer":0,"explanation":"Offered load = λ/μ = 20 × 6/60 = 2 agent-hours per hour. With 2 agents utilisation is exactly 100%, which is unstable in a random system, so at least 3 are needed.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-311","question":"For the call centre with λ = 20 calls/hour, μ = 10 calls/hour per agent and 3 agents (M/M/3), P₀ = 1/9. What is the average time a caller waits before an agent answers?","options":["About 6 minutes","About 1.33 minutes","About 8.67 minutes","About 2.67 minutes"],"answer":3,"explanation":"Lq = P₀ (λ/μ)^c ρ / [c! (1 − ρ)²] = (1/9) × 8 × (2/3) / (6 × 1/9) ≈ 0.889. Wq = Lq/λ = 0.889/20 h ≈ 2.67 min. 8.67 min adds the 6-minute service (time in system).","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-312","question":"A forecasting system reports a mean absolute deviation (MAD) of 40 units for lead-time demand, and forecast errors are roughly normal. For z = 2, what safety stock should be held?","options":["80 units","64 units","50 units","100 units"],"answer":3,"explanation":"For normal errors σ ≈ 1.25 × MAD = 50 units, so safety stock = z σ = 2 × 50 = 100. Using MAD directly as σ understates it (80); dividing by 1.25 (64) inverts the conversion.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-313","question":"Demand rises by exactly 10 units every month; this month's demand was 200. A 5-month simple moving average is used to forecast next month. By how much will the forecast miss next month's demand?","options":["It will be 20 units too low","It will be 30 units too low","It will be 10 units too low","It will be exact"],"answer":1,"explanation":"The last five months are 160–200, so the forecast is 180, but next month's demand is 210 – an under-forecast of 30. A moving average lags a trend by (N + 1)/2 periods × trend = 3 × 10.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-314","question":"A store's annual sales are ₹120 lakh at a gross margin of 30%, and its average inventory at cost is ₹20 lakh. What is its gross margin return on inventory investment (GMROI)?","options":["6.0","4.2","1.8","0.3"],"answer":2,"explanation":"GMROI = gross margin ÷ average inventory at cost = 36 ÷ 20 = 1.8. Sales ÷ inventory (6.0) is a turnover figure, and COGS ÷ inventory (84 ÷ 20 = 4.2) is inventory turnover at cost.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-315","question":"A florist buys bouquets at ₹70 and sells them at ₹100; unsold ones are worth ₹50 next day. Daily demand is 10, 11, 12 or 13 with probabilities 0.2, 0.3, 0.3 and 0.2. How many bouquets should she stock to maximise expected profit?","options":["12","11","10","13"],"answer":0,"explanation":"Cu = 100 − 70 = 30 and Co = 70 − 50 = 20, so the critical ratio is 0.6. Cumulative probabilities are 0.2, 0.5, 0.8, 1.0; the first to reach 0.6 is at 12. Ignoring the ₹50 salvage value makes Co = 70 and the ratio 0.3, which wrongly points to 11.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-316","question":"An item is ordered 600 units at a time and the firm keeps 150 units of safety stock. Each unit costs ₹200, and annual holding cost is 20% of cost. What is the annual holding cost?","options":["₹18,000","₹12,000","₹30,000","₹6,000"],"answer":0,"explanation":"Average inventory = Q/2 + safety stock = 300 + 150 = 450 units; holding cost = 450 × ₹40 = ₹18,000. Ignoring safety stock gives ₹12,000; using Q + SS (750) gives ₹30,000.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-317","question":"A filling process has a target mean of 500 ml and a known standard deviation of 6 ml. Samples of 9 bottles are taken. What are the 3-sigma control limits for the sample mean?","options":["482 ml and 518 ml","498 ml and 502 ml","494 ml and 506 ml","496 ml and 504 ml"],"answer":2,"explanation":"The standard error of the mean is σ/√n = 6/3 = 2 ml, so limits are 500 ± 3 × 2 = 494 and 506. Using σ itself gives 482–518 – limits for individual bottles, not sample means.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-318","question":"A process that is in control is monitored with 3-sigma limits (each point has a 0.27% chance of falling outside by chance). Over 25 independent samples, what is the probability of at least one false alarm?","options":["About 0.27%","About 0.01%","About 25%","About 6.5%"],"answer":3,"explanation":"P(no false alarm in 25) = 0.9973²⁵ ≈ 0.9346, so P(at least one) ≈ 6.5%. 0.27% is the single-sample rate; even good limits throw occasional false signals when many samples are plotted.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-319","question":"A dimension has specification 50 ± 3 mm, and the process mean is 50.5 mm. What is the largest process standard deviation that still gives Cpk = 1.33?","options":["About 0.752 mm","About 0.627 mm","About 0.877 mm","About 0.501 mm"],"answer":1,"explanation":"The nearer limit is USL = 53, 2.5 mm from the mean. Cpk = 2.5/(3σ) ≥ 1.33 gives σ ≤ 2.5/3.99 ≈ 0.627. Using the full half-width of 3 mm (a Cp calculation) gives 0.752; using the far limit 3.5 mm gives 0.877.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-320","question":"For an in-control process using 3-sigma limits, about how many samples will be plotted, on average, before a false out-of-control signal?","options":["About 27","About 100","About 3","About 370"],"answer":3,"explanation":"The chance of a point outside 3-sigma limits is 0.0027, and the average run length is 1/p ≈ 370. 27 comes from confusing 0.27% with 2.7%.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-321","question":"An X̄ chart with 3-sigma limits uses samples of n = 4. The process mean suddenly shifts up by one process standard deviation (1σ). What is the probability that the next sample mean falls above the UCL? (Φ(1) ≈ 0.8413, Φ(2) ≈ 0.9772.)","options":["About 0.023","About 0.159","About 0.0013","About 0.50"],"answer":1,"explanation":"σ of the mean = σ/2, so a 1σ shift is 2 standard errors. The UCL is 3 standard errors above the old mean, i.e. 1 standard error above the new mean: P(Z > 1) ≈ 0.159. Forgetting to divide by √n gives P(Z > 2) ≈ 0.023.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-322","question":"Daily demand is independent from day to day and lead time is constant. If the supplier's lead time doubles from 8 to 16 days, with the same service level, what happens to the safety stock?","options":["It rises by about 41%","It doubles","It rises by 4 times","It is unchanged"],"answer":0,"explanation":"Safety stock = z σ_d √L, so it scales with the square root of lead time: √2 ≈ 1.414, a 41% rise. The reorder point's cycle-stock part (d × L) does double, but safety stock does not.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-323","question":"A plant needs to produce 5,000 units of P (1.2 machine-hours each) and 8,000 units of Q (0.75 machine-hours each) a year, plus a setup allowance of 10% of run time. Each machine works 2,000 hours a year at 80% utilisation. How many machines are needed?","options":["8","7","9","10"],"answer":2,"explanation":"Run hours = 5,000 × 1.2 + 8,000 × 0.75 = 12,000; with setups 13,200 hours. Effective hours per machine = 2,000 × 0.8 = 1,600, so 13,200/1,600 = 8.25 → round up to 9. Ignoring setups gives 7.5 → 8.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-324","question":"An online lender approves 400 loans a week and has, on average, 1,000 applications in process. It wants to grow to 600 approvals a week without increasing the applications in process. What must happen to average processing time?","options":["Fall from 2.5 weeks to 1.5 weeks","Fall from 2.5 weeks to about 1.67 weeks","Stay at 2.5 weeks","Rise to 3.75 weeks"],"answer":1,"explanation":"Little's law W = L/λ: today 1,000/400 = 2.5 weeks; target 1,000/600 ≈ 1.67 weeks. Keeping W at 2.5 would raise WIP to 1,500; 3.75 weeks would mean even more WIP.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-325","question":"A firm's accounts receivable average ₹90 lakh, and credit sales are ₹6 crore a year (360 days). It wants to cut average receivables to ₹60 lakh without changing sales. What must happen to the average collection period?","options":["It must fall from 54 days to 36 days","It must fall from 54 days to 18 days","Receivables turnover must fall from 10 to 6.67","It must fall from 54 days to 40.5 days"],"answer":0,"explanation":"Collection period = receivables ÷ daily sales: 90 ÷ (600/360) = 54 days, and 60 ÷ 1.667 = 36 days. This is Little's law with rupees as the flow unit. 18 days is the size of the cut, not the new period; turnover must rise (6.67 to 10), not fall.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-326","question":"Machine A has a design capacity of 120 units/day, effective capacity 100, actual output 90. Machine B has a design capacity of 100, effective capacity 95, actual output 85. Which statement is correct?","options":["A has higher utilisation and higher efficiency than B","B has higher efficiency and lower utilisation than A","A has higher efficiency but lower utilisation than B","Both have the same utilisation"],"answer":2,"explanation":"A: utilisation 90/120 = 75%, efficiency 90/100 = 90%. B: utilisation 85/100 = 85%, efficiency 85/95 ≈ 89.5%. So A is slightly more efficient but less utilised.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-327","question":"A line's tasks total 4.2 minutes of work per unit, and the longest single task takes 0.9 minutes. The line will have exactly 6 stations and runs 420 productive minutes a day. Even if tasks could be grouped perfectly, what is the maximum daily output?","options":["600 units","100 units","700 units","466 units"],"answer":3,"explanation":"Perfect balance would give a cycle time of 4.2/6 = 0.7 min, but no station can cycle faster than its longest indivisible task, 0.9 min. Output = 420/0.9 ≈ 466 units. The trap 600 uses the 0.7-minute cycle.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-328","question":"Activities (days; immediate predecessors): A 3 (–), B 5 (–), C 4 (A), D 2 (A, B), E 6 (C), F 3 (D), G 4 (E, F). A new method can cut activity E from 6 days to 1 day. What will the project duration become?","options":["12 days","17 days","15 days","14 days"],"answer":3,"explanation":"Paths: A–C–E–G = 17, B–D–F–G = 14, A–D–F–G = 12. Cutting E by 5 days drops A–C–E–G to 12, but B–D–F–G (14 days) now becomes critical, so the project takes 14 days, not 17 − 5 = 12.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-329","question":"A project has a budget at completion of ₹100 lakh. At the end of month 6 the planned value is ₹50 lakh, the earned value ₹40 lakh and the actual cost ₹50 lakh. If the current cost performance continues, what is the estimate at completion (EAC)?","options":["₹110 lakh","₹100 lakh","₹125 lakh","₹80 lakh"],"answer":2,"explanation":"CPI = EV/AC = 40/50 = 0.8, so EAC = BAC/CPI = 100/0.8 = ₹125 lakh. ₹110 lakh (AC + remaining budget) assumes future work will be done at budget rates, which contradicts 'current performance continues'.","difficulty":"hard","source":"Project analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-330","question":"A project has a single critical path of 20 days and no other path longer than 12 days. Indirect costs are ₹5,000 a day. Activities on the path can be crashed: P at ₹3,000/day (up to 2 days), Q at ₹4,500/day (up to 2 days), R at ₹6,000/day (up to 3 days). What duration minimises total project cost?","options":["16 days","18 days","13 days","20 days"],"answer":0,"explanation":"Crash a day only while its cost is below the ₹5,000 daily saving: P (2 days) and Q (2 days) qualify, R does not. Duration = 20 − 4 = 16 days, saving ₹20,000 − ₹15,000 = ₹5,000. Crashing R as well (13 days) costs more than it saves.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-331","question":"Maximise Z = 4x + 3y subject to 2x + y ≤ 20, x + 3y ≤ 30, x ≤ 8, x, y ≥ 0. What is the optimal value of Z, and which constraint is not binding at the optimum?","options":["Z = 44; x + 3y ≤ 30 has a slack of 10","Z = 48; x ≤ 8 has a slack of 2","Z = 48; 2x + y ≤ 20 has a slack of 2","Z = 40; x ≤ 8 has a slack of 0"],"answer":1,"explanation":"Corners: (0,0) 0, (8,0) 32, (8,4) 44, (6,8) 48, (0,10) 30. The optimum is (6,8), where 2x + y = 20 and x + 3y = 30 both bind, while x = 6 leaves 2 units of slack in x ≤ 8. Stopping at (8,4) gives 44.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-332","question":"Maximise Z = 4x + 5y subject to x + y ≤ 8, x + 3y ≤ 18, x, y ≥ 0. The optimum is x = 3, y = 5. Keeping everything else fixed, over what range can the profit per unit of x vary without changing the optimal corner?","options":["From about ₹1.67 to ₹5","From ₹3 to ₹15","From ₹1 to ₹3","From about ₹1.67 to ₹8"],"answer":0,"explanation":"The corner stays optimal while the objective's slope −c/5 lies between the slopes of the binding lines, −1 (x + y = 8) and −1/3 (x + 3y = 18). So 1/3 ≤ c/5 ≤ 1, i.e. 5/3 ≤ c ≤ 5. Multiplying by 3 instead of 5 gives the ₹1–₹3 trap.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-333","question":"A refinery makes products A (x litres) and B (y litres). Management insists that A must be at least 30% of total output. Which linear constraint correctly expresses this?","options":["x ≥ 0.3y","0.3x − 0.7y ≥ 0","0.7x − 0.3y ≥ 0","x − 0.3y ≥ 0"],"answer":2,"explanation":"x ≥ 0.3(x + y) rearranges to 0.7x − 0.3y ≥ 0. Writing x ≥ 0.3y compares A with B alone, not with the total; 0.3x − 0.7y ≥ 0 would force A to be at least 70% of output.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-334","question":"In the optimal LP solution of a product-mix problem, product T is not produced and its reduced cost is −₹6 per unit. What does this mean?","options":["Producing one unit of T would increase total profit by ₹6","T makes a loss of ₹6 per unit","The resource used by T has a shadow price of ₹6","T's unit profit would have to rise by more than ₹6 before producing it could improve the optimum"],"answer":3,"explanation":"A reduced cost of −6 for a non-basic variable means forcing one unit of T into the solution lowers the objective by ₹6, given the shadow prices of the resources it uses. Its profit must improve by more than ₹6 for T to enter.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-335","question":"An LP for the number of trucks to buy gives x = 3.6, y = 2.4 at the optimum. Which statement about simply rounding to x = 4, y = 2 is correct?","options":["Rounding always gives the optimal integer solution","The rounded point may be infeasible or not the best integer solution, so an integer method is needed","Rounding is always feasible because the LP was feasible","Rounding down both values always gives the best integer solution"],"answer":1,"explanation":"The integer optimum need not lie next to the LP optimum: rounding can break a constraint, and a feasible rounded point may be beaten by another integer point. Rounding down keeps feasibility only for '≤' constraints with non-negative coefficients, not optimality.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-336","question":"Unit costs (₹) from sources S1, S2, S3 (rows) to destinations D1, D2, D3 (columns): S1: 4, 10, 7; S2: 9, 6, 5; S3: 3, 2, 8. Supplies are 50, 60, 40 and demands 30, 70, 50. What is the total cost of the initial solution given by the north-west corner rule?","options":["₹710","₹670","₹1,050","₹990"],"answer":3,"explanation":"NWC: S1→D1 30, S1→D2 20, S2→D2 50, S2→D3 10, S3→D3 40. Cost = 120 + 200 + 300 + 50 + 320 = ₹990. The rule ignores costs entirely, which is why least-cost (₹710) or VAM starts are usually far better.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-337","question":"Unit costs (₹) from sources S1, S2, S3 (rows) to destinations D1, D2, D3 (columns): S1: 4, 10, 7; S2: 9, 6, 5; S3: 3, 2, 8. Supplies are 50, 60, 40 and demands 30, 70, 50. What is the minimum possible total transportation cost?","options":["₹710","₹670","₹990","₹630"],"answer":1,"explanation":"Optimal plan: S1→D1 30, S1→D3 20, S2→D2 30, S2→D3 30, S3→D2 40, costing 120 + 140 + 180 + 150 + 80 = ₹670; MODI shows no unused cell with a negative improvement index. The least-cost start (₹710) ships 20 units on the ₹10 route S1→D2, which the optimum avoids.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-338","question":"A transportation problem has total supply of 300 units and total demand of 350. Each unit of unmet demand at market M2 costs a penalty of ₹5; shortfalls at other markets have no penalty. How should the problem be set up?","options":["Add a dummy market of 50 units with zero costs","Add a dummy source of 50 units with zero cost to every market","Add a dummy source of 50 units with cost ₹5 to M2 and ₹0 to other markets","Reduce M2's demand by 50 units and solve"],"answer":2,"explanation":"Demand exceeds supply, so a dummy source supplies the 50-unit gap; its 'shipments' are unmet demand. Putting the ₹5 penalty in the dummy-to-M2 cell makes the model ration M2 last. A dummy market fits the opposite case (excess supply).","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-339","question":"Four jobs J1–J4 are to be assigned one each to machines M1–M4. Costs (₹ hundred), rows J1–J4, columns M1–M4: J1: 14, 5, 8, 7; J2: 2, 12, 6, 5; J3: 7, 8, 3, 9; J4: 2, 4, 6, 10. What is the minimum total cost?","options":["₹15 hundred","₹12 hundred","₹17 hundred","₹14 hundred"],"answer":0,"explanation":"Optimal: J1→M2 (5), J2→M4 (5), J3→M3 (3), J4→M1 (2) = 15. Picking each row's minimum (5 + 2 + 3 + 2 = 12) is infeasible because J2 and J4 both want M1; the Hungarian method resolves this clash at a cost of 15.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-340","question":"In an assignment problem, worker W3 is not allowed to operate machine M2 for safety reasons. How is this handled in the Hungarian method for a minimisation problem?","options":["Put a very large cost (M) in the W3–M2 cell","Put zero in the W3–M2 cell","Delete row W3 from the matrix","Put a negative cost in the W3–M2 cell"],"answer":0,"explanation":"A very large cost guarantees the cell is never chosen in an optimal assignment. Zero or negative costs would make it attractive; deleting the row would leave W3 unassigned and unbalance the problem.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-341","question":"In a two-person zero-sum game, the row player's payoffs are: R1: 4, 2, 5; R2: 6, 3, 7; R3: 1, 0, 8 (columns C1–C3). What is the value of the game?","options":["2, with pure strategies R1 and C2","3, with pure strategies R2 and C2","6, with pure strategies R2 and C1","No saddle point; the players must mix strategies"],"answer":1,"explanation":"Row minima are 2, 3, 0 → maximin 3 (R2). Column maxima are 6, 3, 8 → minimax 3 (C2). Since maximin = minimax, (R2, C2) is a saddle point and the value is 3.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-342","question":"A two-person zero-sum game has the row player's payoff matrix R1: 5, 1; R2: 2, 4 (columns C1, C2). What is the value of the game?","options":["2","4","3.5","3"],"answer":3,"explanation":"No saddle point (maximin 2 < minimax 4). The row player plays R1 with probability p so that 5p + 2(1 − p) = p + 4(1 − p), giving p = 1/3 and value = 5/3 + 4/3 = 3. 2 and 4 are only the pure-strategy bounds.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-343","question":"A firm can spend ₹20 lakh on R&D that succeeds with probability 0.6 (failure is worth nothing). If it succeeds, the firm can either license the product for ₹80 lakh or launch it itself, earning ₹200 lakh if demand is high (probability 0.5) or ₹20 lakh if low. What is the expected net value of doing the R&D, with optimal later decisions?","options":["₹28 lakh","₹66 lakh","₹46 lakh","₹40 lakh"],"answer":2,"explanation":"Fold back: launch EMV = 0.5 × 200 + 0.5 × 20 = 110 > 80, so launch. R&D EMV = 0.6 × 110 − 20 = ₹46 lakh. Choosing to license gives 0.6 × 80 − 20 = 28; forgetting the R&D cost gives 66.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-344","question":"A machine produces 5% defective parts, independently. In a box of 10 parts, what is the probability of finding at least 2 defectives?","options":["0.0861","0.4013","0.3151","0.0500"],"answer":0,"explanation":"P(0) = 0.95¹⁰ ≈ 0.5987 and P(1) = 10 × 0.05 × 0.95⁹ ≈ 0.3151, so P(≥2) = 1 − 0.9139 ≈ 0.0861. 0.4013 is P(at least one); 0.3151 is P(exactly one).","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-345","question":"Urgent tickets reach an IT team at an average of 2 per hour (Poisson). What is the probability of 3 or more urgent tickets in a given hour?","options":["0.594","0.1804","0.1429","0.3233"],"answer":3,"explanation":"P(0) + P(1) + P(2) = e⁻²(1 + 2 + 2) ≈ 0.6767, so P(≥3) ≈ 0.3233. 0.5940 stops at P(1); 0.1804 is P(exactly 3) only.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-346","question":"Customers arrive at a kiosk with exponentially distributed gaps averaging 4 minutes. No one has arrived for the last 5 minutes. What is the probability that the next customer arrives within the next 2 minutes?","options":["0.8262","0.6065","0.3935","0.5000"],"answer":2,"explanation":"The exponential distribution is memoryless: past waiting is irrelevant, so P(T ≤ 2) = 1 − e^(−2/4) ≈ 0.3935. Using 7 minutes of total wait (1 − e^(−7/4)) ignores memorylessness.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-347","question":"Delivery times are normal with mean 40 minutes and standard deviation 8 minutes. The app wants to promise a time that 90% of deliveries meet. What should it promise? (z for the 90th percentile ≈ 1.28.)","options":["About 29.8 minutes","About 50.2 minutes","About 48.0 minutes","About 53.2 minutes"],"answer":1,"explanation":"90th percentile = μ + 1.28σ = 40 + 10.24 ≈ 50.2 min. Subtracting gives the 10th percentile (29.8); μ + σ (48) covers only about 84%.","difficulty":"moderate","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-348","question":"Weekly demand X at store 1 has mean 100 and variance 400; weekly returns Y at store 2 have mean 50 and variance 225, independent of X. A planner tracks Z = 2X − Y. What are the mean and standard deviation of Z?","options":["Mean 150, standard deviation about 37.1","Mean 150, standard deviation 25","Mean 250, standard deviation about 42.7","Mean 150, standard deviation about 42.7"],"answer":3,"explanation":"E[Z] = 2(100) − 50 = 150. Var(Z) = 4 Var(X) + Var(Y) = 1,600 + 225 = 1,825 (variances add even when Y is subtracted), so σ ≈ 42.7. Subtracting Var(Y) gives √1,375 ≈ 37.1; 25 = 2 × 20 − 15 combines standard deviations directly.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-349","question":"A churn model is run on 1,000 customers, of whom 100 actually churn. It flags 150 customers, and 60 of the flagged customers actually churn. Which statement is correct?","options":["Precision is 60%, recall is 40% and accuracy is 87%","Precision is 40%, recall is 60% and accuracy is 87%","Precision is 40%, recall is 60% and accuracy is 60%","Precision is 40%, recall is 15% and accuracy is 91%"],"answer":1,"explanation":"Precision = true positives ÷ flagged = 60/150 = 40%. Recall = true positives ÷ actual churners = 60/100 = 60%. True negatives = 900 − 90 = 810, so accuracy = (60 + 810)/1,000 = 87%. Swapping precision and recall is the classic slip.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-350","question":"For the churn model with precision 40% and recall 60%, what is the F1 score?","options":["0.48","0.50","0.24","0.96"],"answer":0,"explanation":"F1 is the harmonic mean: 2PR/(P + R) = 2 × 0.4 × 0.6 / 1.0 = 0.48. The arithmetic mean (0.50) overstates a model whose two scores differ; 0.24 is the product P × R.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-351","question":"A supplier claims its defect rate is 20%. In a random sample of 400 units, 92 are defective. Testing H0: p = 0.20 against H1: p ≠ 0.20 at the 5% level, what is the conclusion?","options":["z = 1.5; reject H0","z = 1.43; reject H0","z = 1.5; do not reject H0","z = 3.0; reject H0"],"answer":2,"explanation":"p̂ = 92/400 = 0.23. Under H0 the standard error is √(0.2 × 0.8/400) = 0.02, so z = 0.03/0.02 = 1.5 < 1.96. Using p̂ in the standard error gives about 1.43; forgetting the square root gives a huge z.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-352","question":"Average order values: city A sample n = 100, mean ₹520, s = ₹100; city B sample n = 100, mean ₹490, s = ₹120. Treat the samples as large and independent. What is the z-statistic for the difference in means?","options":["About 0.27","About 1.92","About 2.73","About 1.36"],"answer":1,"explanation":"SE = √(100²/100 + 120²/100) = √(100 + 144) ≈ ₹15.62, so z = 30/15.62 ≈ 1.92. Adding the two standard errors (10 + 12 = 22) gives 1.36; dividing by a single average SE of 11 gives 2.73.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-353","question":"A test of whether a new layout changes conversion gives p = 0.03. Which interpretation is correct?","options":["If the layout truly had no effect, a difference at least this large would arise about 3% of the time","There is a 3% probability that the layout has no effect","There is a 97% probability that the layout works","The effect of the layout is small, about 3%"],"answer":0,"explanation":"A p-value is computed assuming H0 is true: it is P(data this extreme | H0), not P(H0 | data). It says nothing directly about the size of the effect.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-354","question":"A survey estimates average spend with a margin of error of ±₹40 at 95% confidence from 400 respondents. Roughly how many respondents are needed to cut the margin to ±₹20, other things equal?","options":["800","566","1,600","3,200"],"answer":2,"explanation":"Margin of error ∝ 1/√n, so halving it needs four times the sample: 4 × 400 = 1,600. Doubling n (800) only cuts the margin by about 29%.","difficulty":"moderate","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-355","question":"An analyst wants to estimate mean call-handling time within ±2 minutes at 95% confidence. A pilot suggests σ = 15 minutes. What is the minimum sample size?","options":["216","55","57","217"],"answer":3,"explanation":"n = (zσ/E)² = (1.96 × 15/2)² ≈ 216.09, which must be rounded up to 217. Rounding down to 216 misses the target precision; 55 uses the full interval width (4) as E; 57 uses z = 1.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-356","question":"A chi-square test of independence uses a contingency table of 3 regions × 4 product categories, with 400 customers in all. The North row total is 120 and the 'Electronics' column total is 80. What are the degrees of freedom and the expected count for the North–Electronics cell?","options":["6 degrees of freedom; expected count 24","12 degrees of freedom; expected count 24","6 degrees of freedom; expected count 30","11 degrees of freedom; expected count 40"],"answer":0,"explanation":"df = (rows − 1)(columns − 1) = 2 × 3 = 6. Expected count = row total × column total ÷ grand total = 120 × 80/400 = 24. 12 is rows × columns; 11 is cells minus one.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-357","question":"A one-way ANOVA compares mean sales under 3 store layouts, with 10 stores per layout. What are the degrees of freedom of the F-statistic?","options":["3 and 30","2 and 29","3 and 27","2 and 27"],"answer":3,"explanation":"Between-groups df = k − 1 = 2; within-groups df = N − k = 30 − 3 = 27. 29 is the total df (N − 1), which is the sum of the two.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-358","question":"Advertising (x) and sales (y) have means x̄ = 20 and ȳ = 50, standard deviations 4 and 10, and correlation 0.8. Using the regression of y on x, what sales are predicted when advertising is 25?","options":["62.5","55","60","70"],"answer":2,"explanation":"Slope = r × s_y/s_x = 0.8 × 10/4 = 2, and the line passes through (20, 50): ŷ = 50 + 2 × 5 = 60. Ignoring r (slope 2.5) gives 62.5 – it forgets regression towards the mean.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-359","question":"In a regression with 32 observations and one predictor, the estimated slope is 3.2 with a standard error of 1.25. The two-tailed 5% critical t with 30 df is 2.04. Which is correct?","options":["t = 4.0, so the slope is significant at 5%","t = 2.56, so the slope is significant at 5%","t = 0.39, so the slope is not significant","t = 2.56, but the slope is not significant because 2.56 < 3.2"],"answer":1,"explanation":"t = estimate ÷ standard error = 3.2/1.25 = 2.56 > 2.04, so H0: slope = 0 is rejected. Multiplying (4.0) or inverting (0.39) the ratio are the usual slips.","difficulty":"moderate","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-360","question":"A sales regression has R² = 0.92 and a significant overall F-test, yet the t-statistics of advertising and promotions are both insignificant and advertising has an unexpected negative sign. The two predictors have a correlation of 0.97. What is the most likely problem?","options":["Multicollinearity between advertising and promotions","Heteroscedasticity of the residuals","Autocorrelation of the residuals","An omitted intercept"],"answer":0,"explanation":"Highly correlated predictors inflate the standard errors of their coefficients, so each looks insignificant and signs can flip, while the model as a whole fits well. Heteroscedasticity and autocorrelation show up in residual patterns, not this combination.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-361","question":"A regression of sales on region uses an intercept and a dummy variable for each of the 4 regions (North, South, East, West). What goes wrong?","options":["Nothing, as long as each region has enough observations","The R² is understated","Perfect multicollinearity – the dummies sum to the intercept column, so one must be dropped","The residuals become heteroscedastic"],"answer":2,"explanation":"With an intercept, 4 categories need only 3 dummies; including all 4 makes them sum to 1 for every row, an exact linear dependence with the intercept (the dummy-variable trap). The omitted region becomes the baseline.","difficulty":"moderate","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-362","question":"A model gives Sales = 10 + 2 × Ad + 5 × Online + 1.5 × (Ad × Online), where Online = 1 for online stores and 0 otherwise and Ad is advertising spend. What is the effect of one more unit of advertising on sales in an online store?","options":["2","3.5","6.5","8.5"],"answer":1,"explanation":"With an interaction, ∂Sales/∂Ad = 2 + 1.5 × Online. For online stores (Online = 1) it is 3.5; 2 applies only to offline stores. Adding the Online coefficient (5) is a mistake because it is a level shift, not a slope.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-363","question":"A demand model estimated in logs is ln Q = 5 − 1.8 ln P. If the price is raised by 10%, what happens to revenue (P × Q), approximately?","options":["It falls by about 18%","It rises by about 10%","It falls by about 8%","It falls by about 7.3%"],"answer":3,"explanation":"The elasticity is −1.8, so Q changes by 1.1^(−1.8) ≈ 0.842 (about −15.8%). Revenue factor = 1.1 × 0.842 ≈ 0.927, a fall of about 7.3%. The linear shortcut (−18% + 10% = −8%) is close but overstates the fall; −18% is the quantity effect alone.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-364","question":"The correlation between monthly ad spend X and sales Y is 0.6. An analyst defines U = 3 − 2Y (an 'unsold capacity' index). What is the correlation between X and U?","options":["+0.6 (positive)","−1.2 (negative)","−0.6 (negative)","−0.3 (negative)"],"answer":2,"explanation":"Correlation is unaffected by adding constants or rescaling, except that a negative multiplier flips the sign. So corr(X, 3 − 2Y) = −corr(X, Y) = −0.6. The magnitude cannot exceed 1.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-365","question":"Three weeks of data: promotions x = 2, 4, 6 and sales y = 5, 9, 10. What is the Pearson correlation coefficient?","options":["About 0.833","About 0.893","1.000","About 0.945"],"answer":3,"explanation":"Deviations: x: −2, 0, 2; y: −3, 1, 2. Σdxdy = 6 + 0 + 4 = 10, Σdx² = 8, Σdy² = 14. r = 10/√(8 × 14) ≈ 0.945. The points are not exactly collinear (the slope falls from 2 to 0.5), so r is not 1.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-366","question":"A buyer spends ₹1,000 on a commodity at ₹20 a kg and another ₹1,000 at ₹30 a kg. What is her average cost per kg?","options":["₹24","₹25","₹24.5","₹26"],"answer":0,"explanation":"She buys 50 kg + 33.33 kg = 83.33 kg for ₹2,000, so the average is ₹24 – the harmonic mean of 20 and 30, because equal rupee amounts (not equal quantities) were spent. The simple average ₹25 is the trap.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-367","question":"A start-up's revenue grew 50% in year 1 and fell 20% in year 2. What was its compound annual growth rate over the two years?","options":["15%","About 9.5%","About 10.0%","About 7.2%"],"answer":1,"explanation":"Overall factor = 1.5 × 0.8 = 1.2, so CAGR = √1.2 − 1 ≈ 9.5%. The arithmetic mean of +50% and −20% (15%) overstates growth; 10% is simply the total gain of 20% halved.","difficulty":"moderate","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-368","question":"An order passes through four independent systems, each unavailable 2% of the time. What is the probability that at least one is down when an order arrives?","options":["8%","About 7.76%","About 0.00002%","2%"],"answer":1,"explanation":"P(all up) = 0.98⁴ ≈ 0.9224, so P(at least one down) ≈ 7.76%. Adding the four 2% figures (8%) double-counts overlaps; 0.02⁴ is the chance that all four are down.","difficulty":"moderate","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-369","question":"Each sales call converts independently with probability 4%. What is the probability that a rep's first sale comes on or before the 10th call?","options":["40%","About 2.8%","About 33.5%","About 66.5%"],"answer":2,"explanation":"P(no sale in 10 calls) = 0.96¹⁰ ≈ 0.665, so P(first sale by call 10) ≈ 33.5%. 40% simply adds 4% ten times; 66.5% is the chance of no sale; 2.8% is P(first sale exactly on call 10).","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-370","question":"Daily sales at two stores have standard deviations of ₹30,000 and ₹40,000, and their correlation is 0.5. What is the standard deviation of their combined daily sales?","options":["₹50 thousand","₹70 thousand","About ₹36.1 thousand","About ₹60.8 thousand"],"answer":3,"explanation":"Var = 30² + 40² + 2 × 0.5 × 30 × 40 = 900 + 1,600 + 1,200 = 3,700, so σ ≈ 60.8 thousand. ₹50 thousand assumes independence; ₹70 thousand assumes perfect correlation; 36.1 subtracts the covariance term.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-371","question":"A product team tests 20 independent metrics in an A/B test, each at the 5% significance level, when in truth the change affects none of them. What is the probability that at least one metric shows a 'significant' result?","options":["About 64%","5%","100%","About 36%"],"answer":0,"explanation":"P(no false positive) = 0.95²⁰ ≈ 0.358, so P(at least one) ≈ 64%. The expected number of false positives is 20 × 0.05 = 1, but that is not a probability. Corrections such as Bonferroni (α/20) control this.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-372","question":"Residuals from a regression of household spending on income fan out – small at low incomes and much larger at high incomes. Which statement is correct?","options":["The coefficients are biased, so the model must be discarded","This shows multicollinearity between income and spending","This is autocorrelation, which only arises in time series","The errors are heteroscedastic; coefficient estimates stay unbiased, but the usual standard errors are unreliable"],"answer":3,"explanation":"A funnel-shaped residual plot signals non-constant error variance. OLS remains unbiased, but the usual standard errors and t-tests are wrong; robust standard errors or a log transformation are typical fixes.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-373","question":"What do =INT(-3.7) and =TRUNC(-3.7) return in Excel?","options":["−3 and −3","−3 and −4","−4 and −3","−4 and −4"],"answer":2,"explanation":"INT rounds down to the next lower integer, so INT(−3.7) = −4. TRUNC simply chops off the decimals, giving −3. They agree for positive numbers but differ for negatives.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-374","question":"What does =MOD(-7, 3) return in Excel?","options":["Minus 1","1","Minus 2","2"],"answer":3,"explanation":"Excel's MOD returns a result with the same sign as the divisor: MOD(n, d) = n − d × INT(n/d) = −7 − 3 × INT(−2.33) = −7 − 3 × (−3) = 2. Languages that truncate towards zero would give −1.","difficulty":"very-hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-375","question":"What does =ROUND(-2.5, 0) + ROUND(2.45, 1) return in Excel?","options":["Minus 0.5","0.4","Minus 0.6","0.5"],"answer":0,"explanation":"Excel rounds halves away from zero: ROUND(−2.5, 0) = −3, and ROUND(2.45, 1) = 2.5. The sum is −0.5. Rounding −2.5 to −2 (towards zero, or 'banker's rounding') would give 0.5.","difficulty":"very-hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-376","question":"A1 contains the text 'Delhi-North-Zone7'. What does =MID(A1, FIND(\"-\", A1) + 1, FIND(\"-\", A1, FIND(\"-\", A1) + 1) - FIND(\"-\", A1) - 1) return?","options":["Nort","North","North-Zone7","Delhi"],"answer":1,"explanation":"The first '-' is at position 6, so the second search starts at 7 and finds the second '-' at 12. MID starts at 7 and takes 12 − 6 − 1 = 5 characters: 'North'. The nested FIND is what locates the second hyphen; without it you would get the rest of the string or the first segment.","difficulty":"very-hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-377","question":"A1 holds 'mumbai' and B1 holds 'MUMBAI'. What do =FIND(\"M\", A1) and =SEARCH(\"M\", A1) return?","options":["#VALUE! and 1","1 and 1","1 and #VALUE!","#VALUE! and #VALUE!"],"answer":0,"explanation":"FIND is case-sensitive, so it cannot find a capital 'M' in 'mumbai' and returns #VALUE!. SEARCH ignores case and finds 'm' at position 1. B1 is not referenced at all – a distraction.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-378","question":"A2:A7 hold product names: 'iPhone 15', 'Galaxy Phone', 'Phone Case', 'Laptop', 'Smartphone stand', 'Earphones'; B2:B7 hold sales 50, 40, 10, 90, 15, 20. What does =SUMIF(A2:A7, \"*phone*\", B2:B7) return?","options":["40","135","125","60"],"answer":1,"explanation":"The wildcard pattern '*phone*' matches any text containing 'phone', and SUMIF is not case-sensitive. 'iPhone 15', 'Galaxy Phone', 'Phone Case', 'Smartphone stand' and 'Earphones' all match: 50 + 40 + 10 + 15 + 20 = 135. Only 'Laptop' is excluded.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-379","question":"A1:A6 contain 10, an empty cell, 0, the text 'n/a', 20 and 30. What does =AVERAGE(A1:A6) return?","options":["12","20","15","10"],"answer":2,"explanation":"AVERAGE ignores empty cells and text in a range but includes zeros: (10 + 0 + 20 + 30)/4 = 15. Treating the blank and text as zero gives 60/6 = 10; ignoring the zero gives 20.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-380","question":"A2:A9 hold the regions N, S, N, E, N, S, W, N and B2:B9 hold sales 100, 200, 150, 50, 300, 120, 80, 90. What does =COUNTIFS(A2:A9, \"N\", B2:B9, \">=\"&B2) return?","options":["2","4","3","5"],"answer":2,"explanation":"B2 = 100, so the criteria are region N and sales ≥ 100. North rows have 100, 150, 300 and 90: three pass (100, 150, 300). Writing \">B2\" as literal text, or using '>' instead of '>=', are the usual slips (the latter gives 2).","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-381","question":"A sheet has employee IDs in A2:A100 and departments in C2:C100. In row 1, the headers are A1 'ID', B1 'Name', C1 'Dept'. Which formula returns the department of the ID in F1 and still works if a new column is later inserted between B and C?","options":["=INDEX(C2:C100, MATCH(F1, A2:A100, 0))","=VLOOKUP(F1, A2:C100, 3, FALSE)","=VLOOKUP(F1, A2:C100, 3, TRUE)","=INDEX(A2:C100, MATCH(F1, A2:A100, 0), 3)"],"answer":0,"explanation":"INDEX/MATCH refers to the return column directly, so the reference shifts automatically when a column is inserted. VLOOKUP and INDEX with a hard-coded column number 3 would then return the wrong column, and TRUE would also allow an approximate match.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-382","question":"An analyst uses =VLOOKUP(\"P-104\", A2:B6, 2, TRUE) on a product list sorted as P-101, P-103, P-105, P-102, P-104 in A2:A6 (not in ascending order). What is the main problem?","options":["It always returns #N/A on unsorted data","With TRUE (approximate match), VLOOKUP assumes the first column is sorted, so on unsorted data it can return a wrong row without any error","TRUE makes the lookup case-sensitive","TRUE returns the last matching row instead of the first"],"answer":1,"explanation":"Approximate-match lookups use a binary-search style that relies on ascending order. On unsorted data the result is unreliable and may silently be wrong. For codes, FALSE (exact match) is the correct choice.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-383","question":"What does =XLOOKUP(\"Pune\", A2:A10, B2:B10, \"Not found\") return if 'Pune' does not appear in A2:A10?","options":["#N/A","0","The value in B10","Not found"],"answer":3,"explanation":"XLOOKUP's fourth argument, if_not_found, is returned when there is no match. Without it XLOOKUP would return #N/A. Its default match mode is exact.","difficulty":"moderate","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-384","question":"A cash-flow model has an initial outlay of ₹1,000 at time 0 in B1 (entered as −1000) and inflows of ₹400, ₹400 and ₹400 at the end of years 1–3 in B2:B4. The discount rate is 10%. Which formula gives the correct NPV?","options":["=NPV(10%, B1:B4)","=B1 + NPV(10%, B2:B4)","=NPV(10%, B2:B4)","=NPV(10%, B1:B4) * (1 + 10%) - B1"],"answer":1,"explanation":"Excel's NPV discounts its first value by one full period, so the time-0 outlay must be kept outside: −1,000 + 994.74 ≈ −5.26. NPV(10%, B1:B4) wrongly discounts the outlay too, overstating NPV.","difficulty":"very-hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-385","question":"For an outlay of ₹1,000 now followed by inflows of ₹400 at the end of each of the next three years, at 10%, an analyst wrongly enters =NPV(10%, -1000, 400, 400, 400). Approximately what does Excel show, compared with the true NPV?","options":["About -4.78 instead of about -5.26","About -5.26 – the same as the true NPV","About -5.79 instead of about -5.26","About 200.00 instead of about -5.26"],"answer":0,"explanation":"NPV treats −1,000 as a cash flow at the end of year 1 and the inflows at years 2–4, giving -4.78. The correct NPV, with the outlay undiscounted, is -5.26. The mistake shifts every cash flow one period later.","difficulty":"very-hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-386","question":"A loan of ₹10,00,000 at 9% a year is repaid in 60 equal monthly instalments. Which formula correctly gives the instalment as a positive number?","options":["=PMT(9%, 60, -1000000)","=PMT(9%/12, 5, -1000000)","=PMT(9%/12, 60, -1000000)","=PMT(9%, 5, -1000000)/12"],"answer":2,"explanation":"The rate and number of periods must match the payment frequency: monthly rate 9%/12 and 60 months. Entering the loan as a negative present value makes the payment positive. Dividing an annual payment by 12 ignores interest earned within the year, so it is not the true monthly instalment.","difficulty":"moderate","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-387","question":"An investor deposits ₹5,000 at the start of every month for 24 months at 12% a year compounded monthly. Which formula gives the value at the end of 24 months?","options":["=FV(12%, 24, -5000, 0, 1)","=FV(1%, 24, -5000)","=FV(1%, 2, -5000, 0, 1)","=FV(1%, 24, -5000, 0, 1)"],"answer":3,"explanation":"Monthly rate 1%, 24 periods, payment −5,000, and type = 1 because deposits are made at the start of each period. The result is about ₹136,216. Omitting the type argument assumes end-of-period deposits and understates the value by one month's interest on each deposit.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-388","question":"A1 holds the date 31-Jan-2026. What do =EDATE(A1, 1) and =EOMONTH(A1, 1) return?","options":["3-Mar-2026 and 28-Feb-2026","28-Feb-2026 and 31-Mar-2026","29-Feb-2026 and 28-Feb-2026","28-Feb-2026 and 28-Feb-2026"],"answer":3,"explanation":"EDATE moves one month forward and, because 31 February does not exist, returns the last day of February: 28-Feb-2026 (2026 is not a leap year). EOMONTH(A1, 1) gives the last day of the month one month ahead: also 28-Feb-2026.","difficulty":"very-hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-389","question":"B2:B11 hold ten sales figures with no ties. Which formula returns the third-highest value?","options":["=SMALL(B2:B11, 3)","=LARGE(B2:B11, 3)","=MAX(B2:B11) - 3","=RANK(3, B2:B11)"],"answer":1,"explanation":"LARGE(range, k) returns the k-th largest value. SMALL returns the k-th smallest; MAX − 3 subtracts 3 from the maximum; RANK returns a position, not a value.","difficulty":"moderate","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-390","question":"A column holds the scores of all 40 employees in a department (the whole population of interest). Which function correctly gives their standard deviation?","options":["STDEV.P","STDEV.S","VAR.P","AVEDEV"],"answer":0,"explanation":"When the data are the entire population, divide by n: STDEV.P. STDEV.S divides by n − 1 for a sample and would overstate it; VAR.P gives the variance, not the standard deviation; AVEDEV is the mean absolute deviation.","difficulty":"moderate","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-391","question":"A manager wants to find the advertising budget that makes projected profit (in cell D10, which depends on the budget in B3) exactly ₹50 lakh. Which Excel tool is designed for this?","options":["A one-variable data table","Conditional formatting","Goal Seek","Remove Duplicates"],"answer":2,"explanation":"Goal Seek changes one input cell until a formula cell reaches a target value. A data table shows outputs for a list of inputs you supply, and Solver is needed when there are several changing cells or constraints.","difficulty":"moderate","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-392","question":"A1 contains '  Ravi   Kumar ' (with extra spaces at the start, in the middle and at the end). What does =LEN(TRIM(A1)) return?","options":["14","11","9","10"],"answer":3,"explanation":"TRIM removes leading and trailing spaces and reduces runs of internal spaces to one, giving 'Ravi Kumar', which has 10 characters (4 + 1 + 5). Excel's TRIM, unlike some tools, does collapse internal spaces.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-393","question":"A2:A6 hold 'North', 'South', 'North', 'East', 'South'. What does =SUMPRODUCT(1/COUNTIF(A2:A6, A2:A6)) return?","options":["5","2","3","1"],"answer":2,"explanation":"COUNTIF(A2:A6, A2:A6) returns 2, 2, 2, 1, 2. Their reciprocals 0.5, 0.5, 0.5, 1, 0.5 sum to 3 – the number of distinct regions (North, South, East).","difficulty":"very-hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-394","question":"Which range does =SUM(OFFSET(A1, 2, 1, 3, 1)) add up?","options":["C2:C4","B3:B5","A3:A5","B2:B4"],"answer":1,"explanation":"OFFSET starts at A1, moves 2 rows down and 1 column right to B3, then takes a range 3 rows high and 1 column wide: B3:B5.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-395","question":"Table emp has ids 1–6. Table blocked(id) has two rows: 2 and NULL. What do these return? P: SELECT COUNT(*) FROM emp WHERE id NOT IN (SELECT id FROM blocked); Q: SELECT COUNT(*) FROM emp e WHERE NOT EXISTS (SELECT 1 FROM blocked b WHERE b.id = e.id);","options":["P = 0, Q = 5","P = 5, Q = 5","P = 0, Q = 0","P = 5, Q = 6"],"answer":0,"explanation":"For id NOT IN (2, NULL), every comparison with NULL is unknown, so the condition is never true and P returns 0. NOT EXISTS only checks for matching rows, so it excludes id 2 and returns 5. This is why NOT EXISTS is safer when the subquery can contain NULLs.","difficulty":"very-hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-396","question":"Table emp(id, name, dept, salary, mgr) has rows (1, Asha, Sales, 90, NULL), (2, Ravi, Sales, 60, 1), (3, Meena, Sales, 75, 1), (4, Kiran, Ops, 50, NULL), (5, Dev, Ops, 70, 4), (6, Neha, Ops, NULL, 4). What does SELECT COUNT(*), COUNT(salary), AVG(salary) FROM emp return?","options":["6, 6, 57.5","5, 5, 69","6, 5, 57.5","6, 5, 69"],"answer":3,"explanation":"COUNT(*) counts rows (6); COUNT(salary) skips the NULL (5); AVG ignores NULLs, so it is 345/5 = 69. Treating NULL as zero would give 345/6 = 57.5.","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-397","question":"Table emp(id, name, dept, salary, mgr) has rows (1, Asha, Sales, 90, NULL), (2, Ravi, Sales, 60, 1), (3, Meena, Sales, 75, 1), (4, Kiran, Ops, 50, NULL), (5, Dev, Ops, 70, 4), (6, Neha, Ops, NULL, 4). How many rows does SELECT * FROM emp WHERE NOT (salary <= 65) return?","options":["4","3","2","6"],"answer":1,"explanation":"Rows with salary > 65 qualify: Asha 90, Meena 75, Dev 70 = 3. Neha's NULL salary makes 'salary <= 65' unknown, and NOT(unknown) is still unknown, so she is excluded too. Expecting NULL rows to pass a negated condition gives 4.","difficulty":"very-hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-398","question":"Table emp(id, name, dept, salary, mgr) has rows (1, Asha, Sales, 90, NULL), (2, Ravi, Sales, 60, 1), (3, Meena, Sales, 75, 1), (4, Kiran, Ops, 50, NULL), (5, Dev, Ops, 70, 4), (6, Neha, Ops, NULL, 4). How many employees earn more than their own manager, as found by SELECT COUNT(*) FROM emp e JOIN emp m ON e.mgr = m.id WHERE e.salary > m.salary?","options":["1","0","2","3"],"answer":0,"explanation":"The self-join pairs each employee with his manager: Ravi 60 vs Asha 90, Meena 75 vs Asha 90, Dev 70 vs Kiran 50, Neha NULL vs Kiran 50. Only Dev earns more, so the count is 1; Neha's NULL comparison is unknown and is dropped.","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-399","question":"Table emp(id, name, dept, salary, mgr) has rows (1, Asha, Sales, 90, NULL), (2, Ravi, Sales, 60, 1), (3, Meena, Sales, 75, 1), (4, Kiran, Ops, 50, NULL), (5, Dev, Ops, 70, 4), (6, Neha, Ops, NULL, 4). What does SELECT dept, COUNT(*) FROM emp GROUP BY dept HAVING AVG(salary) > 70 return?","options":["Sales, 3 and Ops, 3","No rows","Sales, 3","Ops, 3"],"answer":2,"explanation":"Sales averages (90 + 60 + 75)/3 = 75 > 70. Ops averages (50 + 70)/2 = 60, because AVG ignores Neha's NULL, so it fails. COUNT(*) still counts all three Sales rows.","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-400","question":"orders(oid, cust, amount) has rows (1, A, 100), (2, A, 200), (3, B, 300). items(oid, sku) lists the products in each order: order 1 has 2 items, order 2 has 1, order 3 has 3. An analyst runs SELECT SUM(o.amount) FROM orders o JOIN items i ON o.oid = i.oid to get total revenue. What does it return?","options":["600","1300","1,400","6"],"answer":1,"explanation":"The join repeats each order once per item: 100 × 2 + 200 × 1 + 300 × 3 = 1300. True revenue is 600. Joining to a 'many' table before aggregating a 'one'-side column inflates totals – aggregate first or sum from orders alone.","difficulty":"very-hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-401","question":"Order 1 contains SKUs x and y; order 3 contains SKUs x, y and z. Query P combines the SKU lists of the two orders with UNION; query Q uses UNION ALL. How many rows does each return?","options":["P = 5, Q = 3","P = 5, Q = 5","P = 3, Q = 5","P = 2, Q = 5"],"answer":2,"explanation":"UNION removes duplicate rows, leaving x, y, z (3 rows). UNION ALL keeps every row from both inputs: 2 + 3 = 5.","difficulty":"moderate","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-402","question":"Which statement about the logical order in which a SELECT query is evaluated is correct?","options":["WHERE is applied before GROUP BY, and HAVING after it, so aggregates can be filtered only in HAVING","HAVING is applied before WHERE","A column alias defined in SELECT can always be used in WHERE","ORDER BY is applied before GROUP BY"],"answer":0,"explanation":"Logical order: FROM/JOIN → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT. WHERE cannot see aggregates or (in standard SQL) SELECT aliases, because they are computed later.","difficulty":"moderate","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-403","question":"Table orders has 3 rows and table items has 6 rows. How many rows does SELECT * FROM orders CROSS JOIN items return?","options":["9","6","18","3"],"answer":2,"explanation":"A cross join pairs every row of one table with every row of the other: 3 × 6 = 18. 9 would be the sum, and 6 the result of a matching inner join on oid.","difficulty":"moderate","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-404","question":"Table emp(id, name, dept, salary, mgr) has rows (1, Asha, Sales, 90, NULL), (2, Ravi, Sales, 60, 1), (3, Meena, Sales, 75, 1), (4, Kiran, Ops, 50, NULL), (5, Dev, Ops, 70, 4), (6, Neha, Ops, NULL, 4). Which employees does this return? SELECT name FROM emp e WHERE salary > (SELECT AVG(salary) FROM emp e2 WHERE e2.dept = e.dept)","options":["Asha and Dev","Asha, Meena and Dev","Asha only","Asha, Meena, Dev and Neha"],"answer":0,"explanation":"The correlated subquery computes each department's average: Sales 75, Ops 60 (NULL ignored). Asha (90 > 75) and Dev (70 > 60) qualify; Meena's 75 is not greater than 75; Neha's NULL comparison is unknown.","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-405","question":"Table emp(id, name, dept, salary, mgr) has rows (1, Asha, Sales, 90, NULL), (2, Ravi, Sales, 60, 1), (3, Meena, Sales, 75, 1), (4, Kiran, Ops, 50, NULL), (5, Dev, Ops, 70, 4), (6, Neha, Ops, NULL, 4). What does SELECT SUM(COALESCE(salary, 0)) FROM emp WHERE dept = 'Ops' return, compared with SELECT SUM(salary) FROM emp WHERE dept = 'Ops'?","options":["120 and NULL","Both return 120","120 and 0","NULL and 120"],"answer":1,"explanation":"SUM already ignores NULLs, so SUM(salary) = 50 + 70 = 120; COALESCE turns Neha's NULL into 0 and also gives 120. COALESCE matters for AVG (60 vs 40) or row-level arithmetic, not for SUM.","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-406","question":"Daily demand is a steady 50 units, the order quantity is 200 units, and the supplier's lead time is 10 days. At what on-hand stock level should a new order be placed (no safety stock)?","options":["500 units","300 units, with one order outstanding","0 units, since lead time exceeds the order cycle","100 units, with two orders already outstanding"],"answer":3,"explanation":"Lead-time demand is 50 × 10 = 500, so the reorder point in inventory position is 500. Each cycle lasts 200/50 = 4 days, so 2 earlier orders (400 units) are always in the pipeline when you reorder: on-hand = 500 − 400 = 100.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-407","question":"Lead-time demand is normal with a standard deviation of 40 units, and the firm holds 60 units of safety stock. What cycle-service level does this give? (Φ(1.5) ≈ 0.933, Φ(0.67) ≈ 0.749.)","options":["About 93.3%","About 74.9%","About 66.7%","About 98.5%"],"answer":0,"explanation":"z = safety stock ÷ σ_LT = 60/40 = 1.5, so the probability of no stockout in a cycle is Φ(1.5) ≈ 93.3%. Dividing the other way (40/60 = 0.67) gives 74.9%.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-408","question":"Product X (lead time 1 week) needs 2 units of Y; Y (lead time 2 weeks) needs 3 units of Z; Z has a lead time of 1 week. 100 units of X are due in week 8. There are 50 units of Y on hand and nothing else. When must an order for Z be released, and for how many units?","options":["600 units in week 4","450 units in week 4","450 units in week 5","600 units in week 6"],"answer":1,"explanation":"X is released in week 7, so Y's gross need is 200 in week 7; net of 50 on hand it is 150, released in week 5. Z's gross need is 3 × 150 = 450 in week 5, released one week earlier in week 4. Ignoring Y's stock gives 600.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-409","question":"Four jobs wait at one machine (processing hours; weight = importance): A (4; 1), B (2; 3), C (6; 2), D (3; 3). Using the weighted shortest processing time rule to minimise total weighted completion time, what is the minimum total weighted completion time?","options":["60","48","58","15"],"answer":2,"explanation":"WSPT orders jobs by processing time ÷ weight: B 0.67, D 1.0, C 3.0, A 4.0. Completion times 2, 5, 11, 15 give 2×3 + 5×3 + 11×2 + 15×1 = 58. Plain SPT (B, D, A, C) gives 60.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-410","question":"Seven jobs taking 8, 7, 6, 5, 4, 3 and 2 hours are to be run on three identical parallel machines. Using the longest-processing-time (LPT) rule – assign each job, longest first, to the machine that is free earliest – what makespan results, and is it optimal?","options":["13 hours; not optimal, since 12 hours is achievable","12 hours; optimal","13 hours; optimal, since LPT is always optimal","11.67 hours; optimal"],"answer":0,"explanation":"LPT loads: 8+3+2 = 13, 7+4 = 11, 6+5 = 11, so the makespan is 13. But {8, 4}, {7, 5}, {6, 3, 2} gives 12, 12, 11 – a 12-hour schedule. LPT is a good heuristic, not a guarantee; 11.67 (35/3) is only a lower bound.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-411","question":"A machine has a mean time between failures of 400 hours and a mean time to repair of 20 hours. What is its steady-state availability?","options":["95.0%","About 95.2%","About 105%","About 4.8%"],"answer":1,"explanation":"Availability = MTBF ÷ (MTBF + MTTR) = 400/420 ≈ 95.2%. 1 − 20/400 = 95.0% uses the wrong denominator; 4.8% is the unavailability.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-412","question":"A pump fails at random (constant failure rate) with a mean time between failures of 400 hours. What is the probability that it runs a 100-hour mission without failure?","options":["75.0%","About 22.1%","About 25.0%","About 77.9%"],"answer":3,"explanation":"With a constant failure rate λ = 1/400 per hour, reliability R(t) = e^(−λt) = e^(−0.25) ≈ 0.7788. The linear shortcut 1 − 100/400 = 75% ignores the exponential form; 22.1% is the failure probability.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-413","question":"A subscriber yields a margin of ₹600 a year, paid at the end of each year he stays. The annual retention rate is 80% and the discount rate 10%. Using CLV = m × r/(1 + d − r), counting only future years for a customer just acquired, what is the customer lifetime value?","options":["₹2,200","₹3,000","₹1,600","₹2,400"],"answer":2,"explanation":"CLV = 600 × 0.8 / (1 + 0.10 − 0.8) = 480/0.30 = ₹1,600. ₹2,200 uses the version where a margin is also received immediately; ₹3,000 is 600 ÷ (1 − 0.8), which ignores discounting.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-414","question":"Acquiring a customer costs ₹3,000. Each customer pays ₹500 a month at a 60% gross margin and is retained throughout. Ignoring discounting, what is the CAC payback period?","options":["6 months","10 months","16.7 months","5 months"],"answer":1,"explanation":"Payback = CAC ÷ monthly gross profit = 3,000 ÷ (500 × 0.6) = 10 months. Using revenue instead of gross profit (3,000/500) gives 6 months, which overstates how fast the cost is recovered.","difficulty":"moderate","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-415","question":"When a product's price rose from ₹100 to ₹120, monthly sales fell from 1,000 to 850 units. What is the arc (midpoint) price elasticity of demand?","options":["About minus 0.75","About minus 1.06","About minus 0.82","About minus 0.89"],"answer":3,"explanation":"Arc elasticity = [(850 − 1,000)/925] ÷ [(120 − 100)/110] ≈ (−0.162) ÷ (0.182) ≈ -0.89. Using the starting values (−15% ÷ 20%) gives −0.75; using the ending values (−17.6% ÷ 16.7%) gives about −1.06, and other bases give other answers – which is why the midpoint method is used.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-416","question":"Three SKUs have actual sales of 10, 100 and 1,000 units and forecasts of 20, 90 and 1,010. Which statement about the accuracy metrics is correct?","options":["MAPE and WAPE are both about 2.7%","MAPE is about 3.7% and WAPE about 27%","MAPE is about 37% but WAPE (total absolute error ÷ total actual) is about 2.7%","MAPE is about 37% and WAPE is also about 37%"],"answer":2,"explanation":"Each absolute error is 10. MAPE averages percentage errors: (100% + 10% + 1%)/3 = 37%, dominated by the tiny SKU. WAPE = 30/1,110 ≈ 2.7%, weighting by volume. This is why low-volume items distort MAPE.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-417","question":"A single-bay car wash has room for only one car to wait; arriving cars that find the bay busy and the waiting spot taken drive away. Cars arrive at 6 per hour (Poisson) and are washed at 12 per hour (exponential). What fraction of arriving cars are turned away?","options":["About 14.3%","25.0%","50.0%","12.5%"],"answer":0,"explanation":"This is M/M/1/2 (2 cars at most). With ρ = 0.5, Pₙ = ρⁿ(1 − ρ)/(1 − ρ³): P₂ = 0.25 × 0.5/0.875 ≈ 0.1429. Arrivals finding 2 cars leave, so about 14.3%. 25% would be ρ² from the infinite-queue model.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-418","question":"A bank has two tellers, each serving 5 customers an hour (exponential). Customers arrive at 8 an hour in total (Poisson). Option 1: two separate lines, each with 4 arrivals an hour. Option 2: one common line feeding both tellers. What is the average wait in queue under each?","options":["Both about 48 min, because utilisation is 80% in each case","Separate lines: about 21.3 min; common line: 48 min","Separate lines: 12 min; common line: 12 min","Separate lines: 48 min; common line: about 21.3 min"],"answer":3,"explanation":"Each separate line is M/M/1 with ρ = 0.8: Wq = λ/[μ(μ − λ)] = 4/5 h = 48 min. The pooled M/M/2 has P₀ = 1/9 and Lq ≈ 2.84, so Wq ≈ 21.3 min. Same utilisation, but pooling stops one teller idling while the other has a queue.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-419","question":"A process is exactly centred within its specification limits and has Cp = 1.0. Assuming normality, about how many parts per million fall outside specification?","options":["About 1,350","About 2,700","About 64","About 3.4"],"answer":1,"explanation":"Cp = 1 puts each limit 3σ from the mean, so the fraction outside is 2 × P(Z > 3) ≈ 0.0027, i.e. about 2,700 ppm. 1,350 counts only one tail; 3.4 ppm is the six-sigma figure with a 1.5σ shift.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-420","question":"An individuals (X) chart is used for a daily metric. The average of the readings is 50 and the average moving range of consecutive readings is 4. Using the constant 2.66, what is the upper control limit?","options":["62.00","54.00","60.64","58.00"],"answer":2,"explanation":"For an individuals chart, UCL = x̄ + 2.66 × MR̄ = 50 + 10.64 = 60.64 (2.66 = 3/d₂ with d₂ = 1.128). Using 3 × MR̄ gives 62; using MR̄ alone as one sigma gives other wrong limits.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-421","question":"Samples of size 5 have an average range R̄ = 5.0 mm. With D3 = 0 and D4 = 2.114 for n = 5, what are the control limits of the R chart?","options":["LCL 0, UCL 10.57 mm","LCL 0, UCL 2.89 mm","LCL 2.11, UCL 7.89 mm","LCL 0, UCL 15.0 mm"],"answer":0,"explanation":"R chart limits are D3 R̄ and D4 R̄: 0 and 2.114 × 5 = 10.57 mm. Using A2 (0.577 × 5 = 2.89) mixes up the X̄-chart constant; R̄ ± 3R̄ ignores the tabulated constants.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-422","question":"Nine sales reps' weekly sales were measured before and after a training programme. The mean improvement is 4 units with a standard deviation of the differences of 6. Testing H1: training raises sales at α = 0.05 (one-tailed t with 8 df = 1.860), what is the conclusion?","options":["t = 0.67; do not reject H0","t = 2.0; reject H0 – the improvement is significant","t = 2.0; do not reject H0 because 2.0 < 2.306","t = 6.0; reject H0"],"answer":1,"explanation":"A paired test uses the differences: t = d̄/(s_d/√n) = 4/(6/3) = 2.0 > 1.860, so H0 is rejected. 2.306 is the two-tailed critical value, which does not apply to a one-sided alternative; 0.67 forgets √n.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-423","question":"A simple regression of units sold on price has total sum of squares 500 and residual (error) sum of squares 125, and the estimated slope is negative. What is the correlation between price and units sold?","options":["About plus 0.866","0.75","About minus 0.866","About minus 0.75"],"answer":2,"explanation":"R² = 1 − SSE/SST = 1 − 125/500 = 0.75. In simple regression r = ±√R², taking the sign of the slope: r = −√0.75 ≈ −0.866. Reporting R² itself, or forgetting the sign, are the traps.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-424","question":"The regression above (SSE = 125) was fitted on 25 observations with one predictor. What is the standard error of the estimate?","options":["About 2.24","5.0","About 11.18","About 2.33"],"answer":3,"explanation":"Standard error of estimate = √[SSE/(n − 2)] = √(125/23) ≈ 2.33. Dividing by n (√5 ≈ 2.24) ignores the degrees of freedom lost to the two estimated coefficients; √125 ≈ 11.18 forgets to divide.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-425","question":"A firm's fixed costs are ₹12 lakh a month; it sells at ₹500 a unit with a variable cost of ₹300. How many units must it sell to earn a monthly profit of ₹3 lakh?","options":["6,000","1,500","7,500","3,000"],"answer":2,"explanation":"Contribution per unit = 500 − 300 = ₹200, so units = (fixed cost + target profit) ÷ contribution = 15,00,000/200 = 7,500. 6,000 is only break-even; 1,500 covers just the target profit; 3,000 divides ₹15 lakh by the price.","difficulty":"moderate","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-426","question":"A quarterly sales regression is Sales = 200 + 5t − 20 Q1 + 30 Q4, where t = 1 for Q1 of year 1 and Q1, Q4 are dummies (Q2 and Q3 are the base). What is the forecast for t = 13?","options":["265","245","295","235"],"answer":1,"explanation":"t = 13 is Q1 of year 4 (t = 1, 5, 9, 13 are first quarters), so Q1 = 1 and Q4 = 0: 200 + 65 − 20 = 245. Ignoring the seasonal dummy gives 265; treating t = 13 as a Q4 gives 295.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-427","question":"In simple exponential smoothing with α = 0.3, how much weight does the current forecast give to the actual demand of 3 periods before the most recent one (i.e. the 4th most recent observation)?","options":["0.3","About 0.027","About 0.1029","About 0.147"],"answer":2,"explanation":"The k-th most recent observation (k = 0 for the latest) gets weight α(1 − α)ᵏ. For k = 3: 0.3 × 0.7³ ≈ 0.1029. 0.147 is the weight for k = 2; 0.027 cubes α instead of (1 − α).","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-428","question":"A firm buys 10,000 units a year and always orders 500 units at a time. Holding cost is ₹4 per unit per year. For what ordering cost per order would this policy be exactly the EOQ?","options":["₹100","₹25","₹200","₹50"],"answer":3,"explanation":"EOQ = √(2DS/H) = 500 ⇒ S = Q²H/(2D) = 250,000 × 4/20,000 = ₹50. Forgetting the 2 gives ₹100; equating ordering cost to the holding cost of one unit-year is a different (wrong) idea.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-429","question":"A retailer switches from continuous review (lead time 5 days) to a periodic review every 7 days with the same 5-day lead time. Daily demand is independent with the same σ, and the service level is unchanged. By roughly what percentage does safety stock rise?","options":["About 55%","140%","About 18%","No change"],"answer":0,"explanation":"Continuous review protects only the lead time: SS ∝ √5. Periodic review must protect the review period plus lead time: SS ∝ √12. Ratio √(12/5) ≈ 1.549, a rise of about 55%. 140% compares 12 with 5 without square roots.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-430","question":"A distributor measures four order attributes: delivered on time 95%, complete 97%, damage-free 99%, and with correct documents 98%. Assuming independence, what is its perfect-order rate?","options":["About 97.3%","95.0%","About 91.0%","About 89.4%"],"answer":3,"explanation":"A perfect order must pass every test: 0.95 × 0.97 × 0.99 × 0.98 ≈ 0.894. The simple average (97.3%) or the weakest link (95%) overstates performance.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-431","question":"A process holds an average of 600 units of WIP and completes 200 units per 8-hour working day. The value-added work on each unit totals 30 minutes. What is its process cycle efficiency?","options":["About 6.25%","About 2.08%","About 0.69%","About 33.3%"],"answer":1,"explanation":"Little's law: lead time = WIP ÷ throughput = 600/200 = 3 working days = 1,440 minutes. PCE = 30/1,440 ≈ 2.08%. Using one day as the lead time gives 6.25%; using 24-hour days gives 0.69%.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-432","question":"A machine has a mean processing time of 4 minutes and runs at 90% utilisation. The squared coefficient of variation is 1 for inter-arrival times and 0.5 for processing times. Using Kingman's approximation Wq ≈ [(ca² + cs²)/2] × [ρ/(1 − ρ)] × ts, what is the average wait in queue?","options":["27 minutes","36 minutes","13.5 minutes","3 minutes"],"answer":0,"explanation":"Wq ≈ (1 + 0.5)/2 × 0.9/0.1 × 4 = 0.75 × 9 × 4 = 27 min. With exponential processing (cs² = 1) it would be 36 min, so cutting process variability alone saves 9 minutes of queueing.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-433","question":"Activities A (4 days) and B (6 days) can start at once and run in parallel, and C (3 days) can start only when both are done. A and B each need the site's only crane for their whole duration. What is the shortest project duration?","options":["9 days","10 days","13 days","16 days"],"answer":2,"explanation":"Without the resource limit the duration would be max(4, 6) + 3 = 9 days. With one crane, A and B must run one after the other (10 days), and C follows: 13 days. Resource constraints can lengthen a schedule beyond its critical path.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-434","question":"A firm has ₹10 crore to invest and four indivisible projects (cost; NPV, ₹ crore): P1 (5; 8), P2 (4; 6), P3 (3; 5), P4 (6; 9). Which selection maximises total NPV?","options":["P1 and P3, NPV ₹13 crore","P1 and P2, NPV ₹14 crore","P3 and P4, NPV ₹14 crore","P2 and P4, NPV ₹15 crore"],"answer":3,"explanation":"Feasible pairs within ₹10 crore: P1+P2 (14), P1+P3 (13), P2+P3 (11), P2+P4 (15), P3+P4 (14); no three fit. Ranking by NPV per rupee picks P3 then P1 (₹13 crore) and leaves ₹2 crore idle – greedy ratios fail for indivisible projects.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-435","question":"A decision-maker's utility for wealth x (₹ lakh) is u(x) = √x. She is offered a venture paying ₹100 lakh with probability 0.5 and nothing otherwise. What are her certainty equivalent and risk premium?","options":["Certainty equivalent ₹50 lakh; risk premium nil","Certainty equivalent ₹5 lakh; risk premium ₹45 lakh","Certainty equivalent ₹25 lakh; risk premium ₹25 lakh","Certainty equivalent ₹25 lakh; risk premium ₹75 lakh"],"answer":2,"explanation":"Expected utility = 0.5 × √100 = 5, so the certainty equivalent is 5² = ₹25 lakh. Risk premium = EMV − CE = 50 − 25 = ₹25 lakh. 5 is the utility, not a rupee amount.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-436","question":"In a survey of 400 customers, 120 say they would pay for express delivery. What is the 95% confidence interval for the true proportion?","options":["About 25.5% to 34.5%","About 29.1% to 30.9%","About 27.7% to 32.3%","About 21.0% to 39.0%"],"answer":0,"explanation":"p̂ = 0.30 and SE = √(0.3 × 0.7/400) ≈ 0.0229, so the margin is 1.96 × 0.0229 ≈ 0.0449. Forgetting the square root gives a very narrow interval; using z = 1 gives ±2.3 points.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-437","question":"In acceptance sampling, a good lot (at the acceptable quality level) is rejected by the sampling plan. What kind of error is this, and who bears its risk?","options":["Type II error – the consumer's risk (β)","Type I error – the producer's risk (α)","Type I error – the consumer's risk (β)","Type II error – the producer's risk (α)"],"answer":1,"explanation":"Rejecting a lot that should be accepted is a Type I error; its probability α is called the producer's risk because the producer loses a good lot. Accepting a bad lot (at the LTPD) is a Type II error, the consumer's risk β.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-438","question":"Using 30 observations, Model A has 2 predictors and R² = 0.70; Model B has 6 predictors and R² = 0.73. Which statement is correct?","options":["Model B has the higher adjusted R² (about 0.69 vs 0.658)","Model B is better because its R² is higher","Model A has the higher adjusted R² (about 0.678 vs 0.66)","Both have the same adjusted R² because they use the same data"],"answer":2,"explanation":"Adjusted R² = 1 − (1 − R²)(n − 1)/(n − k − 1): A = 1 − 0.30 × 29/27 ≈ 0.678; B = 1 − 0.27 × 29/23 ≈ 0.66. The four extra predictors add too little fit to justify the lost degrees of freedom.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-439","question":"A logistic regression of loan default on a 'missed a payment last year' dummy gives a coefficient of 0.7. Holding other variables fixed, how does a missed payment change the outcome?","options":["It raises the probability of default by 0.7 (70 percentage points)","It multiplies the odds of default by about 2.01","It raises the probability of default by 70%","It multiplies the probability of default by about 2.01"],"answer":1,"explanation":"Logistic coefficients act on the log-odds, so the odds ratio is e^0.7 ≈ 2.01 – the odds roughly double. The effect on the probability itself depends on the starting level, so neither a fixed 70-point nor a fixed doubling of probability is right.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-440","question":"A2:A6 hold customer IDs C1, C2, C1, C3, C1 and B2:B6 hold order values 500, 300, 800, 200, 650. What does =VLOOKUP(\"C1\", A2:B6, 2, FALSE) return?","options":["500","800","650","1,950"],"answer":0,"explanation":"With an exact match VLOOKUP returns the value from the first matching row from the top, which is row 2 (500). It does not sum duplicates (SUMIF would give 1,950) or return the last match (650).","difficulty":"moderate","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-441","question":"Order dates are in A2:A500 and amounts in C2:C500. Which formula correctly totals January 2026 orders?","options":["=SUMIFS(C2:C500, A2:A500, \">=1/1/2026\", A2:A500, \"<=1/31/2026 23:59\")","=SUMIF(A2:A500, \"January\", C2:C500)","=SUMIFS(C2:C500, A2:A500, \">=\"&DATE(2026,1,1))","=SUMIFS(C2:C500, A2:A500, \">=\"&DATE(2026,1,1), A2:A500, \"<\"&DATE(2026,2,1))"],"answer":3,"explanation":"Criteria must be text built by joining the operator to a real date value: \">=\"&DATE(…). Dropping the upper bound sums every order from January onwards; matching the word 'January' fails because dates are stored as numbers; text dates are locale-dependent.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-442","question":"Table logins(cust, dt, device) has rows: (A, 3 Jan, web), (A, 9 Jan, app), (B, 5 Jan, app), (B, 5 Jan, web), (C, 7 Jan, app), (A, 12 Jan, app). A query keeps rows where ROW_NUMBER() OVER (PARTITION BY cust ORDER BY dt DESC, device) = 1. How many rows remain, and how many of them have device = 'app'?","options":["3 rows, 2 of them 'app'","4 rows, 3 of them 'app'","3 rows, all 'app'","6 rows, 4 of them 'app'"],"answer":2,"explanation":"ROW_NUMBER gives exactly one row per customer with number 1: A's latest (12 Jan, app), C's only row (app), and for B the 5 Jan tie is broken by device in alphabetical order, so 'app' comes before 'web'. Hence 3 rows, all 'app'. RANK would have kept both of B's tied rows.","difficulty":"very-hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-443","question":"For the same logins table (6 rows: A has 3 logins, B has 2, C has 1; 4 are on 'app'), what does SELECT COUNT(DISTINCT cust), COUNT(*), SUM(CASE WHEN device = 'app' THEN 1 ELSE 0 END) FROM logins return?","options":["6, 6, 4","3, 6, 4","3, 3, 4","3, 6, 2"],"answer":1,"explanation":"COUNT(DISTINCT cust) counts unique customers (3); COUNT(*) counts rows (6); the CASE expression turns each 'app' row into 1, so the SUM counts app logins (4). This SUM(CASE…) pattern is how analysts pivot categories into columns.","difficulty":"moderate","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-444","question":"Which statement about risk pooling in a supply chain is correct?","options":["Centralising stock for several independent markets reduces the total safety stock needed for the same service level","Centralising stock increases safety stock because demand variability adds up","Risk pooling works best when the markets' demands are perfectly positively correlated","Risk pooling reduces cycle stock but never safety stock"],"answer":0,"explanation":"With independent demands, the standard deviation of total demand is less than the sum of the individual standard deviations, so pooled safety stock falls. The benefit shrinks as demands become positively correlated and vanishes at perfect correlation.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-445","question":"In SMED (single-minute exchange of die), what is the key first step to reduce setup time?","options":["Run larger batches so that setups are less frequent","Buy a second machine to run while the first is being set up","Schedule all setups for the night shift","Separate internal setup (done only while the machine is stopped) from external setup (done while it runs), and convert internal steps to external"],"answer":3,"explanation":"SMED first identifies which setup tasks truly need the machine stopped, moves the rest to be done while the previous job is still running, and then streamlines what remains. Larger batches hide setup cost rather than reducing it.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-446","question":"In the first step of Vogel's approximation method for a transportation table with cost rows S1: 7, 5, 11; S2: 10, 13, 12; S3: 15, 8, 17 (columns D1, D2, D3), which row or column has the largest penalty, and which cell is allocated first?","options":["Row S2 (penalty 2); cell S2–D1","Row S3 (penalty 7); cell S3–D2","Column D2 (penalty 3); cell S1–D2","Row S3 (penalty 7); cell S3–D1"],"answer":1,"explanation":"Penalty = difference between the two lowest costs in a row or column: S1 2, S2 2, S3 7 (15 − 8); D1 3, D2 3, D3 1. S3 has the largest penalty, so allocate as much as possible to its cheapest cell, S3–D2 (cost 8), not to the cell that created the penalty's other end.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-447","question":"The first unit of a new product takes 100 labour hours, and labour follows an 80% unit learning curve (Tₙ = T₁ × n^b, b = log 0.8/log 2 ≈ −0.322). About how many hours will the first four units take in total?","options":["About 256 hours","About 314 hours","400 hours","About 344 hours"],"answer":1,"explanation":"T₂ = 80, T₃ = 100 × 3^(−0.322) ≈ 70.2, T₄ = 64. Total ≈ 100 + 80 + 70.2 + 64 ≈ 314. 256 = 4 × 64 uses the 4th unit's time for every unit; 400 ignores learning.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-448","question":"A firm models receivables month by month. Of money now in the 0–30 day bucket, 60% is paid next month and 40% moves to the 31–60 day bucket. Of money in the 31–60 day bucket, 50% is paid next month, 30% is written off as bad debt and 20% stays in that bucket. Of ₹10 lakh now in the 0–30 day bucket, how much is expected to end up as bad debt?","options":["₹1.2 lakh","₹3.0 lakh","₹1.5 lakh","₹0.96 lakh"],"answer":2,"explanation":"From the 31–60 bucket, money eventually is paid with probability 0.5/(1 − 0.2) = 0.625 and written off with 0.3/0.8 = 0.375. From 0–30, bad debt = 0.4 × 0.375 = 0.15, i.e. ₹1.5 lakh. Ignoring the money that stays a further month gives 0.4 × 0.3 = ₹1.2 lakh.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-449","question":"A Monte Carlo simulation of a warehouse's daily cost gives an estimate whose standard error is ₹400 after 1,000 runs. Roughly how many runs are needed to bring the standard error down to ₹200?","options":["4,000","2,000","1,414","8,000"],"answer":0,"explanation":"The standard error of a simulation average falls with 1/√n, so halving it needs four times as many runs. Doubling the runs only cuts the error by about 29%.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-450","question":"Last month a plant made 1,000 units (valued at ₹50 each) using labour ₹20,000, materials ₹15,000 and overhead ₹5,000. This month it made 1,100 units using labour ₹21,000, materials ₹17,000 and overhead ₹5,000. By how much did multifactor productivity change?","options":["It rose by 10%","It rose by about 4.8%","It fell by about 2.3%","It rose by about 2.3%"],"answer":3,"explanation":"MFP = output value ÷ total inputs: 50,000/40,000 = 1.25 and 55,000/43,000 ≈ 1.279, a rise of about 2.3%. 10% is output growth alone; 4.8% is labour productivity growth (1,100/21,000 vs 1,000/20,000).","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-451","question":"A three-step process has defects per unit of 0.10, 0.05 and 0.15 at the three steps, and defects follow a Poisson pattern. What is its rolled throughput yield?","options":["70.0%","About 72.7%","About 90.0%","About 74.1%"],"answer":3,"explanation":"Each step's first-pass yield is e^(−DPU), so RTY = e^(−0.10 − 0.05 − 0.15) = e^(−0.30) ≈ 0.741. 70% subtracts total DPU from 1; 72.7% multiplies (1 − DPU) terms, which is a cruder approximation.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-452","question":"A help desk logged 30, 20, 25 and 25 calls on four weekdays. Testing whether calls are equally likely on each day at α = 0.05 (critical χ² with 3 df = 7.81), what is the conclusion?","options":["χ² = 2; reject equal likelihood","χ² = 50; reject equal likelihood","χ² = 2; do not reject equal likelihood","χ² = 0.4; do not reject equal likelihood"],"answer":2,"explanation":"Expected count = 100/4 = 25 per day. χ² = Σ(O − E)²/E = (25 + 25 + 0 + 0)/25 = 2, below 7.81, so the differences are consistent with chance. Summing (O − E)² without dividing by E gives 50.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-453","question":"A regression predicts monthly sales from ad spend. For next month's ad spend, an analyst can report (a) a 95% confidence interval for the mean sales at that spend, or (b) a 95% prediction interval for next month's actual sales. Which is correct?","options":["The confidence interval is wider, because it covers all future months","The prediction interval is wider, because it adds the variability of an individual month to the uncertainty about the mean","Both intervals have the same width","The prediction interval is narrower because it concerns one month only"],"answer":1,"explanation":"A confidence interval covers only the uncertainty in the estimated regression line at that x. A prediction interval adds the residual variance of an individual observation, so it is always wider, and it does not shrink to zero as the sample grows.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-454","question":"A retailer's seasonal swings in sales grow larger as overall sales grow – the December peak is about 40% above trend every year, whatever the trend level. Which decomposition model fits better?","options":["Multiplicative: Sales = Trend × Seasonal × Irregular","Additive: Sales = Trend + Seasonal + Irregular","A pure linear trend with no seasonal component","A model with a seasonal component but no trend"],"answer":0,"explanation":"When seasonal effects are a constant percentage of the level, they scale with the trend, which is the multiplicative model. An additive model suits seasonal swings of roughly constant size in units.","difficulty":"moderate","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-455","question":"A1:A6 contain Delhi, Pune, an empty cell, Delhi, Mumbai and an empty cell. What does =COUNTIF(A1:A6, \"<>Delhi\") return?","options":["2","3","6","4"],"answer":3,"explanation":"The criterion \"<>Delhi\" counts every cell not equal to Delhi, including empty cells: Pune, Mumbai and the two blanks = 4. Expecting blanks to be ignored gives 2.","difficulty":"very-hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-456","question":"A pivot table shows revenue (₹ lakh) by region (rows) and channel (columns): North – Online 30, Store 90; South – Online 60, Store 20. If the values are shown as '% of row total', what figure appears for South–Online?","options":["75%","30%","40%","60%"],"answer":0,"explanation":"South's row total is 60 + 20 = 80, so South–Online = 60/80 = 75%. As a % of the column total it would be 60/90 ≈ 67%; as a % of the grand total, 60/200 = 30%.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-457","question":"A2 = 72 (attendance %) and B2 = 58 (marks). What does =IF(AND(A2>=75, B2>=40), \"Pass\", IF(B2>=55, \"Review\", \"Fail\")) return?","options":["Pass","Fail","Review","#VALUE!"],"answer":2,"explanation":"AND(72 ≥ 75, 58 ≥ 40) is FALSE because attendance fails, so the second IF runs: 58 ≥ 55 is TRUE, giving 'Review'. Reading AND as OR would give 'Pass'.","difficulty":"moderate","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-458","question":"cust(id, name) has rows (1, Asha), (2, Ravi), (3, Meena), (4, Kiran), (5, Dev). ord(oid, cid, amt, dt) has rows (1, 1, 500, 2 Jan), (2, 1, 300, 5 Jan), (3, 3, 200, 3 Jan), (4, 3, 200, 3 Jan), (5, 5, 900, 4 Jan), (6, 1, 100, 9 Jan). Which names does SELECT c.name FROM cust c LEFT JOIN ord o ON c.id = o.cid WHERE o.oid IS NULL return?","options":["Asha, Meena and Dev","Ravi and Kiran","No rows","Ravi, Kiran and Dev"],"answer":1,"explanation":"The LEFT JOIN keeps every customer; customers with no order get NULLs in the ord columns. Filtering WHERE o.oid IS NULL keeps exactly those – Ravi (2) and Kiran (4). This 'anti-join' finds customers who never ordered.","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-459","question":"cust(id, name) has rows (1, Asha), (2, Ravi), (3, Meena), (4, Kiran), (5, Dev). ord(oid, cid, amt, dt) has rows (1, 1, 500, 2 Jan), (2, 1, 300, 5 Jan), (3, 3, 200, 3 Jan), (4, 3, 200, 3 Jan), (5, 5, 900, 4 Jan), (6, 1, 100, 9 Jan). What does SELECT cid, dt, amt, COUNT(*) FROM ord GROUP BY cid, dt, amt HAVING COUNT(*) > 1 return?","options":["No rows, because the oids differ","Two rows: one for cid 1 and one for cid 3","One row: cid 3, 3 Jan, 200, count 2","One row: cid 1, count 3"],"answer":2,"explanation":"Grouping by customer, date and amount puts orders 3 and 4 together (same cid, date and amount) – a likely duplicate. Customer 1's three orders differ in date and amount, so each forms its own group with count 1. oid is not in the GROUP BY, so it does not separate them.","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-460","question":"cust(id, name) has rows (1, Asha), (2, Ravi), (3, Meena), (4, Kiran), (5, Dev). ord(oid, cid, amt, dt) has rows (1, 1, 500, 2 Jan), (2, 1, 300, 5 Jan), (3, 3, 200, 3 Jan), (4, 3, 200, 3 Jan), (5, 5, 900, 4 Jan), (6, 1, 100, 9 Jan). For customer 1, what running totals does SUM(amt) OVER (PARTITION BY cid ORDER BY dt) give for orders 1, 2 and 6, in date order?","options":["500, 800, 900","500, 300, 100","900, 900, 900","100, 400, 900"],"answer":0,"explanation":"Partitioned by customer and ordered by date, the window sums all earlier rows plus the current one: 500; 500 + 300 = 800; 800 + 100 = 900. Without ORDER BY the window would be the whole partition (900 on every row).","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-461","question":"A table has 10 rows with x = 1 to 10. NTILE(4) OVER (ORDER BY x) splits them into quartile buckets. How many rows fall into buckets 1, 2, 3 and 4?","options":["2, 2, 3, 3","2.5 each","3, 2, 3, 2","3, 3, 2, 2"],"answer":3,"explanation":"NTILE divides 10 rows into 4 groups as evenly as possible; the 2 leftover rows go to the first groups, so the sizes are 3, 3, 2, 2 (x = 1–3, 4–6, 7–8, 9–10).","difficulty":"very-hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-462","question":"sal(name, dept, s) has rows: dept X – A 90, B 90, C 80, D 70; dept Y – E 60, F 50, G 50, H 40. How many rows have DENSE_RANK() OVER (PARTITION BY dept ORDER BY s DESC) ≤ 2, and how many have RANK() … ≤ 2?","options":["DENSE_RANK: 5; RANK: 6","DENSE_RANK: 6; RANK: 5","DENSE_RANK: 4; RANK: 4","DENSE_RANK: 6; RANK: 6"],"answer":1,"explanation":"In X, A and B tie at rank 1; DENSE_RANK gives C rank 2, but RANK gives C rank 3. In Y, E is 1 and F, G tie at 2 under both. So DENSE_RANK keeps A, B, C, E, F, G (6), while RANK keeps A, B, E, F, G (5).","difficulty":"very-hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-463","question":"An A/B test must detect a lift in conversion from 10% to 12% with α = 0.05 (two-sided) and 80% power. Using n ≈ (1.96 + 0.84)² × [p₁(1 − p₁) + p₂(1 − p₂)] / (p₂ − p₁)², roughly how many visitors are needed per variant?","options":["About 1,920","About 3,830","About 7,670","About 960"],"answer":1,"explanation":"(2.80)² = 7.84; p₁q₁ + p₂q₂ = 0.09 + 0.1056 = 0.1956; divided by 0.02² = 0.0004 gives n ≈ 3,834 per variant. Small differences between low rates need large samples – halving the detectable lift would quadruple n.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-464","question":"Jobs arrive at an M/M/1 workstation at 10 per hour. Waiting (in the system) costs ₹100 per job per hour, and service capacity costs ₹40 per hour for each unit of service rate μ (jobs/hour). Total hourly cost = 40μ + 100L, with L = λ/(μ − λ). What service rate minimises total cost?","options":["12.5 jobs per hour","20 jobs per hour","15 jobs per hour","25 jobs per hour"],"answer":2,"explanation":"d/dμ [40μ + 100 × 10/(μ − 10)] = 40 − 1,000/(μ − 10)² = 0, so (μ − 10)² = 25 and μ = 15. Total cost there is 600 + 200 = ₹800/hour; at μ = 20 it is 800 + 100 = ₹900.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-465","question":"Which statement correctly distinguishes the cycle-service level from the fill rate?","options":["They are two names for the same measure","Fill rate is the probability of a stockout in a cycle","Cycle-service level is always higher than the fill rate","Cycle-service level is the probability of no stockout in a replenishment cycle; fill rate is the fraction of demand met from stock, which is usually higher"],"answer":3,"explanation":"A cycle with a stockout may still meet most of its demand, so the fill rate (units served ÷ units demanded) is typically higher than the cycle-service level. A firm with 90% CSL can have a fill rate above 99% when order quantities are large.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-466","question":"A one-person repair shop treats jobs on a first-come basis. Its owner proposes giving priority to short jobs (shortest processing time first), keeping the same total capacity. What happens to the average number of jobs waiting?","options":["It falls, because SPT minimises average flow time and hence average work-in-process for given jobs","It is unchanged, because capacity is the same","It rises, because long jobs wait longer","It falls only if arrivals also fall"],"answer":0,"explanation":"With the same work, finishing short jobs first reduces the average completion time and, by Little's law, the average number in the system. Long jobs do wait longer, which is the fairness cost of SPT.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-467","question":"An e-commerce firm's monthly data – Jan: 10,000 orders, revenue ₹50 lakh, marketing spend ₹10 lakh, 2,000 new customers; Feb: 12,000 orders, revenue ₹57.6 lakh, marketing ₹14 lakh, 2,500 new customers; Mar: 15,000 orders, revenue ₹69 lakh, marketing ₹20 lakh, 3,200 new customers. By how much did the average order value change from January to March?","options":["It rose by 38%","It fell by 4%","It fell by 8%","It rose by 8%"],"answer":2,"explanation":"AOV = revenue ÷ orders: Jan ₹500, Feb ₹480, Mar ₹460. (460 − 500)/500 = −8%. Revenue grew 38%, but only because orders grew 50%.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-468","question":"An e-commerce firm's monthly data – Jan: 10,000 orders, revenue ₹50 lakh, marketing spend ₹10 lakh, 2,000 new customers; Feb: 12,000 orders, revenue ₹57.6 lakh, marketing ₹14 lakh, 2,500 new customers; Mar: 15,000 orders, revenue ₹69 lakh, marketing ₹20 lakh, 3,200 new customers. What happened to customer acquisition cost (marketing spend ÷ new customers) from January to March?","options":["It rose by 25%, from ₹500 to ₹625","It fell by 25%, from ₹625 to ₹500","It rose by 100%, in line with marketing spend","It rose by 60%, in line with new customers"],"answer":0,"explanation":"CAC = 10,00,000/2,000 = ₹500 in January and 20,00,000/3,200 = ₹625 in March, a 25% rise. Marketing spend doubled while new customers grew only 60%, so each new customer cost more.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-469","question":"An e-commerce firm's monthly data – Jan: 10,000 orders, revenue ₹50 lakh, marketing spend ₹10 lakh, 2,000 new customers; Feb: 12,000 orders, revenue ₹57.6 lakh, marketing ₹14 lakh, 2,500 new customers; Mar: 15,000 orders, revenue ₹69 lakh, marketing ₹20 lakh, 3,200 new customers. If the average order value had stayed at its January level, how much higher would March revenue have been than it actually was?","options":["₹19 lakh","₹6 lakh","₹25 lakh","₹4 lakh"],"answer":1,"explanation":"At January's AOV of ₹500, 15,000 orders would bring ₹75 lakh, versus actual ₹69 lakh – a ₹6 lakh shortfall from the AOV decline. ₹25 lakh is the volume effect (5,000 extra orders × ₹500); ₹19 lakh is the actual revenue increase.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-470","question":"A warehouse receives 1,200 pallets a day and pallets stay an average of 2.5 days. Its racking holds 3,600 pallets. If inbound volume stays the same, what is the longest average dwell time it can sustain without running out of space, on average?","options":["3.6 days","2.5 days","1.2 days","3 days"],"answer":3,"explanation":"Little's law: average stock = inbound × dwell = 1,200 × 2.5 = 3,000 pallets today. Capacity 3,600 ÷ 1,200 per day = 3 days. In practice, variability means it will overflow on some days well before that average is reached.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-471","question":"An item's annual demand doubles. The firm re-computes the EOQ and orders at the new EOQ. Ordering and holding cost rates are unchanged. By what percentage do its annual ordering-plus-holding costs rise?","options":["100%","About 29%","Nil, because the EOQ adjusts","About 41%"],"answer":3,"explanation":"At the EOQ, total relevant cost = √(2DSH), which grows with the square root of demand: √2 ≈ 1.414, a rise of about 41%. The EOQ itself also rises by 41% – economies of scale in ordering.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-472","question":"A p-chart has p̄ = 0.05, and sample sizes vary. Sample A (n = 100) has 11 defectives; sample B (n = 400) has 34 defectives. Using 3-sigma limits computed for each sample's own size, which sample signals out of control?","options":["Only A","Both A and B","Only B","Neither A nor B"],"answer":2,"explanation":"UCL = p̄ + 3√(p̄(1 − p̄)/n). For n = 100, UCL ≈ 0.1154, and A's 0.11 is inside. For n = 400, UCL ≈ 0.0827, and B's 0.085 is outside. A larger sample has tighter limits, so the smaller proportion is the signal.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-473","question":"A Six Sigma team is analysing a late-delivery problem. In which DMAIC phase would it normally carry out a measurement system analysis (gauge R&R) and establish the baseline sigma level?","options":["Measure","Define","Improve","Control"],"answer":0,"explanation":"Define sets the problem and scope; Measure validates the measurement system and establishes the baseline; Analyse finds root causes; Improve tests solutions; Control sustains them with control plans and charts.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-474","question":"Activity A takes 5 days. Activity B takes 4 days and has two links with A: it can start no earlier than 2 days after A starts (start-to-start lag 2), and it can finish no earlier than 1 day after A finishes (finish-to-finish lag 1). With no other activities, what is the shortest project duration?","options":["11 days","6 days","9 days","7 days"],"answer":1,"explanation":"B may start on day 2, which would end it on day 6. The finish-to-finish link needs B to end no earlier than 5 + 1 = 6. Both are met with B from day 2 to day 6, so the project takes 6 days. Treating the links as finish-to-start gives 9 or more.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-475","question":"At a project review, earned value is ₹40 lakh, planned value ₹50 lakh and actual cost ₹35 lakh. Which statement is correct?","options":["The project is behind schedule but under budget","The project is ahead of schedule and under budget","The project is behind schedule and over budget","The project is ahead of schedule but over budget"],"answer":0,"explanation":"Schedule variance = EV − PV = −10 (behind; SPI 0.8). Cost variance = EV − AC = +5 (under budget; CPI ≈ 1.14). Comparing AC with PV says nothing about efficiency – that is the usual trap.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-476","question":"A maximisation LP has 3 '≤' constraints and 4 decision variables. After adding slack variables, how many variables are basic in any basic feasible solution, and what is the maximum number of decision variables that can be positive at an optimal corner?","options":["4 basic variables; at most 4 decision variables positive","7 basic variables; all 4 decision variables positive","3 basic variables; exactly 3 decision variables positive","3 basic variables; at most 3 decision variables positive"],"answer":3,"explanation":"A basic solution has as many basic variables as there are constraints (3), chosen from the 7 decision and slack variables. So at most 3 decision variables can be non-zero at a corner – and possibly fewer if slacks are basic or the solution is degenerate.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-477","question":"A resource's shadow price in an LP is ₹12 per hour, valid for right-hand-side values between 80 and 140 hours; the current availability is 120 hours. The firm can buy 40 more hours at ₹10 per hour. What should it conclude?","options":["Buy all 40 hours, gaining ₹2 × 40 = ₹80","Buying is worthwhile for the first 20 hours; beyond 140 hours the ₹12 value is no longer guaranteed, so re-solve before buying more","Do not buy, because shadow prices apply only to reductions","Buy all 40 hours, because the shadow price never changes"],"answer":1,"explanation":"The shadow price holds only within its range of feasibility. From 120 to 140 hours each hour adds ₹12 at a cost of ₹10, a gain of ₹40. Beyond 140 the basis may change and the value per hour may fall, possibly below ₹10.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-478","question":"For a decision, the expected value of perfect information is ₹18 lakh and the expected value of the sample information from a proposed market survey is ₹9 lakh. The survey costs ₹6 lakh. Which statement is correct?","options":["The survey is not worth buying because its efficiency is only 50%","The survey adds ₹12 lakh net (18 − 6)","The survey is worth buying; its efficiency is 50% and it adds ₹3 lakh net","The survey is worth buying only if its cost is below ₹18 lakh"],"answer":2,"explanation":"Efficiency of sample information = EVSI/EVPI = 9/18 = 50%. Since EVSI (₹9 lakh) exceeds the cost (₹6 lakh), the survey adds ₹3 lakh net. EVPI is only an upper bound on what any information can be worth.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-479","question":"A supplier's lead time is uniformly distributed between 4 and 10 days. What is the probability that a given order takes more than 8 days to arrive?","options":["20%","80%","About 33%","About 67%"],"answer":2,"explanation":"For a uniform distribution on [4, 10], P(L > 8) = (10 − 8)/(10 − 4) = 2/6 ≈ 33%. Dividing by 10 (as if it started at 0) gives 20%.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-480","question":"What do =MROUND(37, 5), =CEILING(37, 5) and =FLOOR(37, 5) return in Excel?","options":["40, 40 and 35","35, 35 and 35","40, 40 and 40","35, 40 and 35"],"answer":3,"explanation":"MROUND rounds to the nearest multiple: 37 is closer to 35 than to 40. CEILING rounds up to the next multiple (40) and FLOOR rounds down (35). Treating MROUND as 'round up' gives 40.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-481","question":"1 March 2026 is a Sunday. What does =WEEKDAY(DATE(2026,3,1)) + WEEKDAY(DATE(2026,3,1), 2) return?","options":["8","2","1","14"],"answer":0,"explanation":"With the default return type, Sunday = 1. With return type 2 (Monday = 1 … Sunday = 7), Sunday = 7. The sum is 1 + 7 = 8. Assuming both systems start on Sunday gives 2.","difficulty":"very-hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-482","question":"A sales table has months in B1:M1 (Jan to Dec) and product names in A2:A50. Which formula returns the March sales of the product named in P1?","options":["=INDEX(B2:M50, MATCH(\"Mar\", B1:M1, 0), MATCH(P1, A2:A50, 0))","=INDEX(B2:M50, MATCH(P1, A2:A50, 0), MATCH(\"Mar\", B1:M1, 0))","=VLOOKUP(P1, A2:M50, 3, FALSE)","=INDEX(A2:M50, MATCH(P1, A2:A50, 0), MATCH(\"Mar\", B1:M1, 0))"],"answer":1,"explanation":"INDEX(array, row, column) needs the row from the product match and the column from the month match, both relative to B2:M50. Swapping them mixes rows and columns; using A2:M50 shifts the column by one and returns February; VLOOKUP column 3 also points at February.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-483","question":"cust has Asha (1), Ravi (2) and Meena (3); ord has orders 10 and 11 for customer 1 and order 12 for customer 3. A report uses SELECT c.name, COUNT(*), COUNT(o.oid) FROM cust c LEFT JOIN ord o ON c.id = o.cid GROUP BY c.id. What does it show for Ravi?","options":["COUNT(*) = 0 and COUNT(o.oid) = 0","COUNT(*) = 1 and COUNT(o.oid) = 0","Ravi does not appear","COUNT(*) = 1 and COUNT(o.oid) = 1"],"answer":1,"explanation":"The LEFT JOIN keeps Ravi with one row of NULLs. COUNT(*) counts that row (1), but COUNT(o.oid) skips NULLs (0). Using COUNT(*) here would wrongly show Ravi as having one order.","difficulty":"very-hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-484","question":"prod(pid, name) has Pen (1), Book (2) and Bag (3); sales(pid, qty) has rows (1, 5), (1, 3), (2, 4). How many rows do these return? P: SELECT p.name FROM prod p JOIN sales s ON p.pid = s.pid; Q: SELECT name FROM prod WHERE pid IN (SELECT pid FROM sales).","options":["P = 2, Q = 2","P = 3, Q = 3","P = 2, Q = 3","P = 3, Q = 2"],"answer":3,"explanation":"The join repeats Pen once per matching sales row (2) plus Book (1) = 3 rows. IN only tests membership, so each product appears at most once: Pen and Book = 2. Use IN or EXISTS when you want the list of products, not the sales rows.","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-485","question":"Daily demand is normal. About what percentage of days have demand within 1.5 standard deviations of the mean? (Φ(1.5) ≈ 0.9332.)","options":["About 93.3%","About 43.3%","About 86.6%","About 6.7%"],"answer":2,"explanation":"P(−1.5 < Z < 1.5) = 2Φ(1.5) − 1 = 2 × 0.9332 − 1 ≈ 0.8664. 93.3% is only P(Z < 1.5); 43.3% is the area between the mean and +1.5σ.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-486","question":"A team compares two suppliers' processes for the same part: Process P has Cp = 1.8 and Cpk = 0.9; Process Q has Cp = 1.3 and Cpk = 1.25. Which statement is correct?","options":["Q currently produces fewer defects, but P could become far better simply by re-centring its mean","P is better now because its Cp is higher","Both are equally capable because both Cp values exceed 1","Q is better now and P cannot be improved without reducing its variation"],"answer":0,"explanation":"Cpk reflects actual performance including centring: P's mean is far off target (Cpk 0.9), so it makes more defects than Q (Cpk 1.25). P's high Cp shows low spread, so centring alone would lift its Cpk towards 1.8.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-487","question":"An item is ordered 20 times a year. Holding cost is ₹8 per unit per year and each unit short costs ₹30. Expected units short per cycle for safety stocks of 0, 50, 100, 150 and 200 units are 40, 12, 3, 0.5 and 0. Which safety stock minimises total annual cost?","options":["100 units","200 units","50 units","150 units"],"answer":3,"explanation":"Annual cost = 8 × SS + 20 × (expected shortage) × 30: SS 0 → 24,000; 50 → 7,600; 100 → 2,600; 150 → 1,500; 200 → 1,600. Eliminating stockouts entirely (200) costs more in holding than it saves.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-488","question":"A single-server desk (M/M/1) has λ = 8 per hour and μ = 10 per hour. In an M/M/1 queue, time in system is exponential with mean 1/(μ − λ). What is the probability that a customer spends more than 30 minutes in the system?","options":["About 60.7%","50%","About 36.8%","About 13.5%"],"answer":2,"explanation":"Mean time in system = 1/(10 − 8) = 0.5 h, and P(W > t) = e^(−(μ − λ)t) = e^(−2 × 0.5) = e^(−1) ≈ 0.368. Many expect 50% because 30 minutes is the mean, but the exponential is skewed, so most customers spend less than the mean.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-489","question":"A clinic with 3 doctors receives 12 patients an hour. On average there are 6 patients in the clinic, of whom 4 are waiting (not with a doctor). What is the doctors' average utilisation?","options":["About 67%","About 33%","100%","50%"],"answer":0,"explanation":"Patients being served = L − Lq = 6 − 4 = 2, i.e. 2 of 3 doctors busy on average – about 67%. Cross-check: W = 6/12 h = 30 min, Wq = 20 min, so service takes 10 min and the load is 12 × 10/60 = 2 doctors.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-490","question":"For an assembly line, which statement about the feasible range of cycle time is correct?","options":["It must be at least the total work content","It must be at least the longest single task time and need be no more than the total work content","It can be shorter than the longest task if stations work faster","It must equal the takt time exactly"],"answer":1,"explanation":"No station can cycle faster than its longest indivisible task; and a single station doing all the work needs a cycle equal to the total work content. Any cycle time between the two is feasible; takt time is the target set by demand.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-491","question":"A product's Q4 sales were 600 units, and its multiplicative seasonal index for Q4 is 1.25. What are its deseasonalised Q4 sales?","options":["750 units","600 units","575 units","480 units"],"answer":3,"explanation":"Deseasonalised value = actual ÷ seasonal index = 600/1.25 = 480. Multiplying by the index (750) puts the season in twice; subtracting 0.25 × 100 is not how multiplicative indices work.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-492","question":"Forecast errors are defined as actual − forecast. Over 12 months the mean forecast error is +35 units and the tracking signal is +5.2. What does this indicate?","options":["The forecast is biased high: it is consistently over-forecasting","The forecast is biased low: it is consistently under-forecasting demand","The forecast is unbiased because positive and negative errors cancel","The forecast has high random error but no bias"],"answer":1,"explanation":"A positive mean error with actual − forecast means actuals usually exceed forecasts – under-forecasting. A tracking signal of +5.2 (outside typical ±4 limits) confirms a persistent bias rather than random noise.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-493","question":"A regression estimated with sales and advertising both in ₹ lakh is Sales = 20 + 3.5 × Ads, with R² = 0.81. If sales are re-expressed in ₹ thousand (advertising stays in ₹ lakh) and the regression is re-run, what are the new intercept, slope and R²?","options":["Intercept 20, slope 350, R² 0.81","Intercept 2,000, slope 3.5, R² 0.81","Intercept 2,000, slope 350, R² 0.81","Intercept 2,000, slope 350, R² 81"],"answer":2,"explanation":"Multiplying y by 100 (₹1 lakh = 100 × ₹1,000) multiplies both the intercept and the slope by 100. R² is unit-free, so it is unchanged.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-494","question":"A two-tailed test of whether a new checkout flow changes basket size gives p = 0.08. The team had, before seeing the data, set a one-tailed test for an increase, and the sample mean did increase. At α = 0.05, what is the correct one-tailed conclusion?","options":["p = 0.04 one-tailed, so reject H0 in favour of an increase","p = 0.16 one-tailed, so do not reject H0","p = 0.08 either way, so do not reject H0","p = 0.04 one-tailed, so do not reject H0"],"answer":0,"explanation":"For a symmetric test statistic, the one-tailed p-value in the observed direction is half the two-tailed value: 0.04 < 0.05, so H0 is rejected. Doubling it (0.16) is the reverse conversion. Choosing the tail after seeing the data would be improper.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-495","question":"A 95% confidence interval for the mean delivery time is 102 to 110 minutes. At the 5% level (two-tailed), what does this imply about H0: μ = 100?","options":["H0 is rejected, because 100 lies outside the interval","H0 is not rejected, because 100 is close to the interval","Nothing can be said without the p-value","H0 is rejected only at the 1% level"],"answer":0,"explanation":"A two-sided 95% confidence interval contains exactly the values of μ that a two-tailed 5% test would not reject. 100 is outside (102, 110), so H0: μ = 100 is rejected at 5%.","difficulty":"moderate","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-496","question":"A call centre makes 400 outbound calls a day, and each converts independently with probability 0.1. Using the normal approximation, about how often will a day have more than 52 conversions? (Ignore the continuity correction; Φ(2) ≈ 0.977.)","options":["About 16% of days","About 0.1% of days","About 2.3% of days","About 30% of days"],"answer":2,"explanation":"Mean = np = 40 and σ = √(np(1 − p)) = √36 = 6. z = (52 − 40)/6 = 2, so P ≈ 1 − 0.977 = 2.3%. Using √(np) ≈ 6.32 changes little, but taking σ = np(1 − p) = 36 would make 52 look ordinary.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-497","question":"A2:A100 hold regions. What does =COUNTIFS(A2:A100, \"North\", A2:A100, \"South\") return, and which formula counts rows that are North or South?","options":["The number of North or South rows; no change is needed","0; use =COUNTIF(A2:A100, \"North\") + COUNTIF(A2:A100, \"South\")","0; use =COUNTIFS(A2:A100, \"North\" & \"South\")","#VALUE!; COUNTIFS cannot repeat a range"],"answer":1,"explanation":"COUNTIFS joins its criteria with AND, and no cell can equal both North and South, so it returns 0. OR logic across values of one column is done by adding separate COUNTIFs (or with SUM(COUNTIF(range, {\"North\",\"South\"}))).","difficulty":"very-hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-498","question":"A2:A5 hold Ramesh, Rakesh, Suresh and Rahul; B2:B5 hold 10, 20, 30, 40. What does =VLOOKUP(\"Ra*\", A2:B5, 2, FALSE) return?","options":["#N/A","70","40","10"],"answer":3,"explanation":"With exact match, VLOOKUP accepts wildcards in a text lookup value: 'Ra*' matches any name starting with 'Ra', and VLOOKUP returns the first match from the top – Ramesh, 10. It does not sum all matches (70) or return the last one.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-499","question":"Cell A1 contains a single space character (it looks empty). What does =IF(A1=\"\", \"Blank\", A1*2) return?","options":["Blank","0","#VALUE!","FALSE"],"answer":2,"explanation":"A space is not an empty string, so A1 = \"\" is FALSE and Excel evaluates A1*2. Multiplying text by a number gives #VALUE!. Using TRIM(A1)=\"\" or LEN(TRIM(A1))=0 is the robust test.","difficulty":"very-hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-500","question":"A1 contains the text '5' (a number stored as text) and A2 contains 3. What do =SUM(A1:A2) and =SUM(\"5\", 3) return?","options":["8 and 8","3 and 3","#VALUE! and 8","3 and 8"],"answer":3,"explanation":"SUM ignores text values in referenced cells, so SUM(A1:A2) = 3. But text representations of numbers typed directly as arguments are converted, so SUM(\"5\", 3) = 8. This is why imported numbers stored as text silently drop out of totals.","difficulty":"very-hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-501","question":"Table v(cust, city, amt) has rows (A, Pune, 100), (B, NULL, 200), (C, Pune, 50), (D, Goa, NULL), (E, NULL, 80). What does SELECT COUNT(DISTINCT city), COUNT(city), COUNT(*) FROM v return?","options":["2, 3, 5","3, 5, 5","2, 5, 5","3, 3, 5"],"answer":0,"explanation":"COUNT(DISTINCT city) counts distinct non-NULL values: Pune and Goa (2). COUNT(city) counts non-NULL entries (3). COUNT(*) counts rows (5). NULL is never counted as a distinct value.","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-502","question":"Using the same table v, what does CASE WHEN amt >= 100 THEN 'High' WHEN amt >= 50 THEN 'Mid' ELSE 'Low' END return for customers C and D?","options":["C: Mid; D: NULL","C: Mid; D: Low","C: High; D: Low","C: Low; D: NULL"],"answer":1,"explanation":"CASE takes the first branch that is true. For C (50), the first test fails and the second succeeds: 'Mid'. For D (NULL), both comparisons are unknown, not true, so the ELSE branch applies: 'Low'. Without an ELSE it would return NULL.","difficulty":"very-hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-503","question":"Using table v, how many rows do these return? P: SELECT * FROM v WHERE amt > 60; Q: SELECT city, SUM(amt) FROM v GROUP BY city HAVING SUM(amt) > 60.","options":["P = 3, Q = 2","P = 3, Q = 3","P = 4, Q = 2","P = 4, Q = 3"],"answer":0,"explanation":"P filters rows: 100, 200 and 80 exceed 60 (D's NULL does not), so 3. Q groups first: Pune 150, NULL group 280, Goa NULL; HAVING keeps Pune and the NULL group, so 2. GROUP BY treats all NULL cities as one group, and SUM over only NULLs is NULL.","difficulty":"very-hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-504","question":"Table m(store, mon, rev) has S1: month 1 = 100, month 2 = 120, month 3 = 90; S2: month 1 = 200, month 2 = 180. What does rev − LAG(rev) OVER (PARTITION BY store ORDER BY mon) give for S2's month 1 and month 2?","options":["110 and minus 20","0 and minus 20","NULL and minus 20","NULL and 180"],"answer":2,"explanation":"LAG looks at the previous row within the same partition. S2's first month has no previous S2 row, so LAG is NULL and the difference is NULL – it does not borrow S1's month 3 (90). Month 2 gives 180 − 200 = −20.","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-505","question":"Using table v (where Goa's only row has amt NULL), what do SELECT SUM(amt) FROM v WHERE city = 'Goa' and SELECT COALESCE(SUM(amt), 0) FROM v WHERE city = 'Goa' return?","options":["0 and 0","NULL and NULL","0 and NULL","NULL and 0"],"answer":3,"explanation":"SUM ignores NULLs, but when every input value is NULL (or there are no rows) it returns NULL, not 0. COALESCE converts that NULL to 0, which is what a report usually wants.","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-506","question":"A subscription business started the quarter with 1,000 customers, gained 200 new customers during the quarter and ended with 1,050. Measured on the opening base, what was its churn rate for the quarter?","options":["5% growth, so no churn","15%","About 14.3%","20%"],"answer":1,"explanation":"Lost customers = 1,000 + 200 − 1,050 = 150; churn on the opening base = 150/1,000 = 15%. Net growth of 5% hides the churn; dividing by the closing base gives about 14.3%.","difficulty":"moderate","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-507","question":"While solving a transportation problem with 3 sources and 4 destinations, an initial solution has only 5 occupied cells. What should be done before applying the MODI method?","options":["Nothing, because 5 cells are enough for MODI","Treat it as degenerate and place a very small allocation ε in a suitable empty cell so there are 6 basic cells","Add a dummy destination","Discard the solution and use the north-west corner rule"],"answer":1,"explanation":"A basic solution needs m + n − 1 = 3 + 4 − 1 = 6 occupied cells. With 5 it is degenerate, so the u and v values cannot all be found. Allocating ε to an independent empty cell (one that forms no closed loop) fixes this.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-508","question":"In the Hungarian method for a 5 × 5 assignment problem, after row and column reductions all zeros can be covered by 4 lines. What does this mean?","options":["The current zeros already give an optimal assignment","The problem is infeasible","One job must be left unassigned","An optimal assignment is not yet possible; the matrix must be revised using the smallest uncovered element"],"answer":3,"explanation":"Optimality needs the minimum number of covering lines to equal n (5). With 4 lines, subtract the smallest uncovered value from uncovered cells, add it at the intersections, and repeat.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-509","question":"A plant runs at 80% utilisation and its average queue of jobs is 4 hours of work. Management plans to load it to 95% utilisation. Assuming M/M/1-like behaviour, roughly how will waiting time change?","options":["It will rise about 4.75 times, to roughly 19 hours","It will rise about 19%, in line with utilisation","It will roughly double, to 8 hours","It will stay about the same because capacity is unchanged"],"answer":0,"explanation":"In M/M/1, waiting time ∝ ρ/(1 − ρ): 0.8/0.2 = 4 versus 0.95/0.05 = 19, a 4.75-fold rise. Queues explode non-linearly as utilisation nears 100%, which is why planners keep a capacity cushion.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-510","question":"A supply chain shares point-of-sale data and builds a joint forecast with its retailer, agreeing on replenishment plans together. Which practice is this, and which problem does it mainly reduce?","options":["Cross-docking; transport cost","Postponement; product variety","Collaborative planning, forecasting and replenishment (CPFR); the bullwhip effect","Kanban; work-in-process inventory inside the plant"],"answer":2,"explanation":"CPFR replaces each tier forecasting from its customer's orders with shared demand data and joint plans, which damps the order amplification known as the bullwhip effect.","difficulty":"moderate","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-511","question":"A lean programme wants to halve a part's economic lot size without changing demand or holding cost. By how much must the setup (ordering) cost per lot be reduced?","options":["By 50%","By 75%","By about 29%","By 25%"],"answer":1,"explanation":"EOQ ∝ √S, so halving the EOQ needs S to fall to a quarter: a 75% cut. A 50% cut in setup cost reduces the lot size only by about 29% (to 1/√2).","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-512","question":"A part is made in lots of 1,200 at a production rate of 100 per day, while it is used at 40 per day throughout the year. In each production cycle, for how many days is the machine not making this part?","options":["12 days","30 days","720 days","18 days"],"answer":3,"explanation":"Run time per lot = 1,200/100 = 12 days; the lot lasts 1,200/40 = 30 days; so the machine is free for other work for 30 − 12 = 18 days per cycle. (The maximum stock is 1,200 × (1 − 40/100) = 720 units, not a number of days.)","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-513","question":"Three stations in series each take 1 minute per unit. A batch of 50 units moves from station to station only when the whole batch is done. With one-piece flow instead, units move one at a time. When does the first unit of the order finish in each case?","options":["Batch: after 52 minutes; one-piece flow: after 3 minutes","Batch: after 150 minutes; one-piece flow: after 52 minutes","Batch: after 150 minutes; one-piece flow: after 3 minutes","Both after 150 minutes, because total work is the same"],"answer":2,"explanation":"With transfer batches of 50, no unit leaves station 3 until all three stations have each spent 50 minutes: 150 minutes. One-piece flow finishes the first unit in 3 minutes and the whole order in 52 minutes – the same work, much shorter lead time.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-514","question":"An audit of 2,000 invoices finds 96 errors. Each invoice has 8 distinct fields where an error can occur. What is the DPMO?","options":["6,000","48,000","750","60,000"],"answer":0,"explanation":"DPMO = defects ÷ (units × opportunities) × 10⁶ = 96 ÷ 16,000 × 10⁶ = 6,000. 48,000 is defects per million units (96/2,000), ignoring opportunities.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-515","question":"Match each situation with the most suitable control chart.\n1. Number of scratches per car body (same body size each time)\n2. Defects per square metre of fabric, where roll sizes vary\n3. Fraction of deliveries that are late, where daily volume varies\n4. Diameter of shafts measured in subgroups of 5\na. X̄ and R charts  b. p chart  c. c chart  d. u chart","options":["1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-b, 2-d, 3-c, 4-a"],"answer":1,"explanation":"Counts of defects in a constant inspection unit use a c chart; defects per unit with a varying unit size use a u chart; proportions defective use a p chart; continuous measurements in subgroups use X̄ and R charts.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-516","question":"Two paths are both critical at 15 days: A → B and A → C (A is shared). Crash costs per day: A ₹5,000, B ₹3,000, C ₹3,500, and each can be crashed by at least 1 day. What is the cheapest way to cut the project by 1 day?","options":["Crash B by 1 day, for ₹3,000","Crash B and C by 1 day each, for ₹6,500","Crash C by 1 day, for ₹3,500","Crash A by 1 day, for ₹5,000"],"answer":3,"explanation":"Both paths must shorten. Crashing B and C costs ₹6,500, while crashing the shared activity A shortens both paths at once for ₹5,000. Crashing B alone leaves A → C at 15 days, so the project does not shorten.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-517","question":"At the end of the simplex method (Big-M or Phase I), an artificial variable is still in the basis at a positive value. What does this indicate?","options":["The problem is unbounded","There are multiple optimal solutions","The original problem has no feasible solution","The optimal solution is degenerate"],"answer":2,"explanation":"Artificial variables are scaffolding for '≥' and '=' constraints; if one cannot be driven to zero, no point satisfies all the original constraints, so the LP is infeasible.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-518","question":"In the optimal simplex tableau of a maximisation problem, a non-basic decision variable has a reduced cost (net evaluation) of exactly zero. What does this signal?","options":["Alternative optimal solutions exist: bringing it into the basis would not change the objective","The current solution is not optimal","The problem is unbounded","That variable must be zero in every optimal solution"],"answer":0,"explanation":"A zero net evaluation for a non-basic variable means it can enter the basis with no change in Z, giving another optimal corner – the algebraic sign of an objective parallel to a binding constraint.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-519","question":"A transportation problem has 3 sources and 4 destinations. Written as a linear programme, how many decision variables and how many supply/demand constraints does it have?","options":["7 variables and 12 constraints","12 variables and 7 constraints","12 variables and 6 constraints","12 variables and 12 constraints"],"answer":1,"explanation":"There is one variable per route: 3 × 4 = 12. There is one constraint per source and one per destination: 3 + 4 = 7. Because the problem is balanced, one constraint is redundant, which is why a basic solution has m + n − 1 = 6 positive cells.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-520","question":"Option A pays ₹100 lakh in the best case and ₹20 lakh in the worst; option B pays ₹60 lakh in the best case and ₹40 lakh in the worst. Under the Hurwicz criterion, for what coefficient of optimism α are the two options equally attractive?","options":["α = 1/2","α = 2/3","α = 1/3","α = 1/4"],"answer":2,"explanation":"Hurwicz value = α × best + (1 − α) × worst. A: 100α + 20(1 − α) = 20 + 80α. B: 60α + 40(1 − α) = 40 + 20α. Equal when 60α = 20, α = 1/3; above it A is preferred.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-521","question":"In a zero-sum game the row player's payoffs are R1: 3, 5, 4 and R2: 6, 2, 7 (columns C1, C2, C3). What is the value of the game?","options":["4","3","5","4.5"],"answer":0,"explanation":"Column C3 is dominated for the column player by C1 (3 ≤ 4 and 6 ≤ 7), so drop it. In the 2 × 2 game R1: 3, 5; R2: 6, 2 there is no saddle point. Row mixes with p on R1: 3p + 6(1 − p) = 5p + 2(1 − p) gives p = 2/3 and value 4.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-522","question":"Base-year quantities and prices: product A 10 units at ₹5, product B 20 units at ₹2. Current prices: A ₹6, B ₹3. What is the Laspeyres price index?","options":["About 135.0","About 122.2","About 150.0","About 133.3"],"answer":3,"explanation":"Laspeyres weights current and base prices by base quantities: Σp₁q₀/Σp₀q₀ = (60 + 60)/(50 + 40) × 100 ≈ 133.3. Averaging the two price relatives (120 and 150) gives 135, which ignores the quantity weights.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-523","question":"Two independent risks hit a project: a supplier delay with probability 0.4 and a design change with probability 0.3. What is the probability that at least one occurs?","options":["0.70","0.12","0.42","0.58"],"answer":3,"explanation":"P(A or B) = P(A) + P(B) − P(A)P(B) = 0.4 + 0.3 − 0.12 = 0.58. Adding (0.70) double-counts the overlap; 0.12 is both together; 0.42 is neither (0.6 × 0.7).","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-524","question":"Daily demand for a cake has mean 100 and standard deviation 20. Daily profit = 50 × demand − 2,000 (₹). What are the mean and standard deviation of daily profit?","options":["Mean ₹3,000; standard deviation ₹50","Mean ₹5,000; standard deviation ₹1,000","Mean ₹3,000; standard deviation ₹1,000","Mean ₹3,000; standard deviation ₹2,980"],"answer":2,"explanation":"For Y = a + bX, the mean is a + bμ = −2,000 + 5,000 = ₹3,000 and the standard deviation is |b|σ = 50 × 20 = ₹1,000. The constant shifts the mean but not the spread.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-525","question":"A distribution of order values has mean ₹1,450 and median ₹900. Which description is most likely?","options":["It is right-skewed, with a long tail of a few very large orders","It is left-skewed, with a long tail of small orders","It is symmetric","It is bimodal with equal peaks"],"answer":0,"explanation":"When the mean is pulled well above the median, a few large values stretch the right tail – typical of order values, incomes and claim sizes. For such data the median is the better 'typical' figure.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-526","question":"A fitted regression is ŷ = 12 + 0.8x. For a store with x = 50, actual sales were 49. What is the residual for that store?","options":["Plus 3","Minus 3","52","Minus 37"],"answer":1,"explanation":"Prediction = 12 + 0.8 × 50 = 52. Residual = actual − predicted = 49 − 52 = −3: the model over-predicts this store. Reversing the subtraction gives +3.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-527","question":"A regression of sales on ad spend was fitted on stores spending between ₹2 lakh and ₹10 lakh a month. A manager uses it to predict sales at ₹40 lakh. What is the main concern?","options":["Multicollinearity","Extrapolation: the linear relationship may not hold far outside the range of the data","The R² will automatically fall","The intercept becomes meaningless only inside the data range"],"answer":1,"explanation":"A regression describes the relationship only over the observed range. Far outside it, saturation or diminishing returns may set in, and prediction intervals widen sharply, so the forecast is unreliable.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-528","question":"A2:A5 hold 100, 80, 60 and 40 (sorted in descending order). What does =MATCH(70, A2:A5, -1) return?","options":["3","#N/A","2","1"],"answer":2,"explanation":"With match type −1 on descending data, MATCH finds the smallest value that is greater than or equal to 70, which is 80 at position 2. Match type 1 would need ascending data; type 0 would give #N/A.","difficulty":"very-hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-529","question":"What do =ROUND(1234.567, -2) and =ROUND(1234.567, 1) return?","options":["1234.57 and 1234.6","1300 and 1234.5","1234 and 1230","1200 and 1234.6"],"answer":3,"explanation":"A negative digits argument rounds to the left of the decimal point: −2 rounds to the nearest hundred, 1,200. Rounding to 1 decimal gives 1,234.6.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-530","question":"What does =\"Growth: \" & TEXT(0.075, \"0%\") return?","options":["Growth: 8%","Growth: 7.5%","Growth: 0.075","Growth: 7%"],"answer":0,"explanation":"The format '0%' multiplies by 100 and shows no decimals, rounding 7.5 to 8. To show 7.5% you need the format '0.0%'. Joining 0.075 without TEXT would show 0.075.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-531","question":"B2:B7 hold 40, 0, 60, 0, 20 and an empty cell. What do =AVERAGE(B2:B7) and =AVERAGEIF(B2:B7, \">0\") return?","options":["20 and 40","24 and 24","40 and 24","24 and 40"],"answer":3,"explanation":"AVERAGE skips the empty cell but includes zeros: 120/5 = 24. AVERAGEIF with '>0' uses only 40, 60 and 20: 120/3 = 40. Treating the blank as zero would give 20.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-532","question":"Table p(id, cat) has ids 1, 2, 3 in category X, ids 4, 5 in Y and id 6 in Z. How many rows does SELECT * FROM p a JOIN p b ON a.cat = b.cat AND a.id < b.id return?","options":["8","4","6","14"],"answer":1,"explanation":"Each unordered pair within a category appears once: X has 3 pairs, Y has 1, Z none – 4 in total. Using a.id <> b.id counts each pair twice (8); with no id condition, each row also pairs with itself (14).","difficulty":"very-hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-533","question":"Table e(name, s) has salaries A 90, B 90, C 80, D 70. What do these return? P: SELECT DISTINCT s FROM e ORDER BY s DESC LIMIT 1 OFFSET 1; Q: SELECT s FROM e ORDER BY s DESC LIMIT 1 OFFSET 1.","options":["P = 90, Q = 80","P = 80, Q = 80","P = 80, Q = 90","P = 70, Q = 80"],"answer":2,"explanation":"Without DISTINCT the sorted list is 90, 90, 80, 70, so skipping one row gives 90 again. With DISTINCT it is 90, 80, 70, and skipping one gives 80 – the true second-highest salary.","difficulty":"very-hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-534","question":"A column holds the names Sara, Raman, Ria, Kavya and Ana. How many of them match LIKE '%a_' (assume a case-insensitive comparison)?","options":["1","5","2","4"],"answer":0,"explanation":"'%a_' requires 'a' as the second-last character followed by exactly one more character. Only Raman (…a-n) qualifies. Sara, Ria, Kavya and Ana all end in 'a', which would match '%a', not '%a_'.","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-535","question":"A firm orders 1,000 units at a time. At this quantity its annual holding cost is ₹6,000 and its annual ordering cost is ₹3,000. Without knowing demand or unit costs, what is the EOQ?","options":["500 units","About 1,414 units","2,000 units","About 707 units"],"answer":3,"explanation":"Holding cost ∝ Q and ordering cost ∝ 1/Q, so at Q* they are equal: Q* = Q × √(ordering cost/holding cost) = 1,000 × √(3,000/6,000) ≈ 707. The current lot is too large because holding exceeds ordering cost; 1,414 moves in the wrong direction.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-536","question":"A three-server bank counter (M/M/3) has arrivals of 24 per hour and each teller serves 10 per hour. On average, how many tellers are busy?","options":["3","0.8","2.4","1.6"],"answer":2,"explanation":"The average number of busy servers in a stable M/M/c system equals the offered load λ/μ = 24/10 = 2.4 (utilisation 2.4/3 = 80%). 0.8 is the utilisation, not the number busy.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-537","question":"A ward has 20 beds, the average length of stay is 4 days and the hospital targets 85% average occupancy. How many admissions per day can the ward handle on average?","options":["5","4.25","17","3.4"],"answer":1,"explanation":"Little's law: average patients = admissions per day × length of stay. 20 × 0.85 = 17 patients = λ × 4, so λ = 4.25 a day. 5 assumes 100% occupancy; 17 is the average census, not a flow.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-538","question":"Products A and B use machines M1 and M2, each available 480 minutes a day. A needs 4 min on M1 and 2 min on M2; B needs 2 min on M1 and 5 min on M2. Which statement about daily output is correct?","options":["With a 50:50 mix M2 is the bottleneck (about 137 units); with an 80:20 mix of A and B, M1 is (about 133 units)","M1 is always the bottleneck because A takes longer on it","M2 is always the bottleneck because B takes 5 minutes on it","Both machines limit output equally at any mix"],"answer":0,"explanation":"At 50:50 the average load per unit is M1 3 min, M2 3.5 min, so M2 limits output to 480/3.5 ≈ 137. At 80:20 it is M1 3.6 min, M2 2.6 min, so M1 limits output to 480/3.6 ≈ 133. The bottleneck moves with the product mix.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-539","question":"Simple exponential smoothing is run with α = 1. What does the forecast for next period equal?","options":["This period's forecast","The average of all past demand","Zero, because no smoothing occurs","This period's actual demand (the naive forecast)"],"answer":3,"explanation":"Fₜ₊₁ = αAₜ + (1 − α)Fₜ. With α = 1 the old forecast gets no weight, so the forecast is the latest actual – the naive method. With α = 0 the forecast would never change.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-540","question":"An analyst fits a 12-variable regression to 30 months of sales and gets R² = 0.97 on that data, but forecasts for the next 6 months are poor. What is the most likely issue, and the standard safeguard?","options":["Underfitting; add more predictors","Overfitting; evaluate the model on a hold-out sample not used for fitting","Multicollinearity; report only R²","Seasonality; drop the intercept"],"answer":1,"explanation":"With many predictors and few observations a model can fit noise, so in-sample R² overstates predictive power. Testing on data held back from fitting (or cross-validation) and using fewer predictors or adjusted R² guard against it.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-541","question":"A process has specification width 12 mm and standard deviation 2 mm. An improvement cuts the standard deviation to 1.5 mm. What happens to Cp?","options":["It rises from 1.00 to about 1.33","It rises from 1.00 to 1.25","It falls from 1.33 to 1.00","It is unchanged because the specification is unchanged"],"answer":0,"explanation":"Cp = (USL − LSL)/6σ: 12/12 = 1.00 before and 12/9 ≈ 1.33 after. Capability rises in inverse proportion to σ; a 25% cut in σ lifts Cp by a third.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-542","question":"A process's specification limits are exactly ±3σ from the target, and it was centred. Its mean then shifts by 1σ (σ unchanged). Approximately what fraction of output is now within specification? (Φ(2) ≈ 0.9772, Φ(4) ≈ 0.99997.)","options":["About 99.73%","About 84.13%","About 97.72%","About 95.45%"],"answer":2,"explanation":"After the shift, the near limit is 2σ away and the far limit 4σ away: P(−4 < Z < 2) = 0.9772 − 0.00003 ≈ 97.72%. Out-of-spec output jumps from 0.27% to about 2.3%. 95.45% would be ±2σ on both sides.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-543","question":"In a cost-minimising diet LP, the protein constraint (at least 50 g) is binding with a shadow price of ₹3 per gram. What happens if the requirement is raised to 52 g, within the allowable range?","options":["Minimum cost falls by about ₹6","Minimum cost rises by ₹3","Minimum cost rises by about ₹6","Minimum cost is unchanged because the constraint is a '≥'"],"answer":2,"explanation":"For a binding requirement in a minimisation problem, the shadow price is the extra cost of one more unit of requirement. Two more grams cost about 2 × ₹3 = ₹6, as long as the change stays within the range where the price holds.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-544","question":"A feed is blended from ingredient X (30% protein) and ingredient Y (10% protein), in kg amounts x and y. The blend must be at least 20% protein. Which linear constraint expresses this?","options":["x − y ≥ 0","0.3x + 0.1y ≥ 20","0.3x + 0.1y ≥ 0.2","x ≥ 2y"],"answer":0,"explanation":"Protein ≥ 20% of total weight: 0.3x + 0.1y ≥ 0.2(x + y), so 0.1x − 0.1y ≥ 0, i.e. x ≥ y. Writing ≥ 20 or ≥ 0.2 confuses a percentage of the blend with a fixed amount of protein.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-545","question":"Payoffs (₹ lakh): act A gives 40 if demand is high (probability 0.6) and 10 if low; act B gives 20 if high and 30 if low. What is the expected opportunity loss of act B?","options":["₹8 lakh","₹12 lakh","₹4 lakh","₹24 lakh"],"answer":1,"explanation":"Regrets: high demand – A 0, B 20; low demand – A 20, B 0. EOL(B) = 0.6 × 20 = 12; EOL(A) = 0.4 × 20 = 8, which equals the EVPI because A is the best (EMV 28 vs 24). The EMV difference is only 4.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-546","question":"Daily demand for a spare part is 0, 1, 2 or 3 units with probabilities 0.1, 0.3, 0.4 and 0.2. What are the mean and standard deviation of daily demand?","options":["Mean 1.5; standard deviation 1.12","Mean 1.7; standard deviation 0.81","Mean 1.7; standard deviation 1.3","Mean 1.7; standard deviation 0.9"],"answer":3,"explanation":"Mean = 0.3 + 0.8 + 0.6 = 1.7. E[X²] = 0.3 + 1.6 + 1.8 = 3.7, so variance = 3.7 − 2.89 = 0.81 and σ = 0.9. 0.81 is the variance; 1.5 is the unweighted average of 0–3.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-547","question":"A defect affects 2% of units. A test flags 90% of defective units and 5% of good ones, and repeat tests on the same unit are independent. A unit tests positive twice. What is the probability that it is defective?","options":["About 87%","About 27%","About 81%","About 98%"],"answer":0,"explanation":"After one positive: 0.018/(0.018 + 0.049) ≈ 0.269. Using that as the new prior, after the second: (0.269 × 0.9)/(0.269 × 0.9 + 0.731 × 0.05) ≈ 0.869. 27% is the one-test answer; 81% is 0.9² mistaken for the posterior.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-548","question":"Nothing is known about the shape of a distribution of delivery times except its mean and standard deviation. What can be said for certain about the share of deliveries within 2 standard deviations of the mean?","options":["Exactly 95%","At least 75%","At least 95%","At most 75%"],"answer":1,"explanation":"Chebyshev's inequality guarantees at least 1 − 1/k² of any distribution lies within k standard deviations: 1 − 1/4 = 75% for k = 2. The 95% figure holds only for (approximately) normal data.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-549","question":"B2:D5 is a table with four rows and three columns (B, C, D). What does =SUM(INDEX(B2:D5, 0, 2)) add up?","options":["The single value in C2","All four values in column B","Row 2 of the table (B2:D2)","All four values in column C (C2:C5)"],"answer":3,"explanation":"When INDEX is given 0 as the row number, it returns the whole column of the array. Column 2 of B2:D5 is C2:C5, so SUM adds those four values. A row number of 0 with a column of 0 would return the whole table.","difficulty":"very-hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-550","question":"A1 contains 5, A2 is empty, A3 contains the formula =\"\" (which shows nothing) and A4 contains the text x. What do =COUNTBLANK(A1:A4) and =COUNTA(A1:A4) return?","options":["1 and 3","2 and 2","2 and 3","1 and 2"],"answer":2,"explanation":"COUNTBLANK counts truly empty cells and cells whose formula returns an empty string, so A2 and A3 give 2. COUNTA counts every non-empty cell, including a formula returning \"\", so A1, A3 and A4 give 3. A3 is counted by both.","difficulty":"very-hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-551","question":"B2:B4 hold unit prices 120, 80 and 50; C2:C4 hold quantities sold 10, 30 and 60. Which formula gives the quantity-weighted average price, and what is it?","options":["=AVERAGE(B2:B4), which gives 83.33","=SUMPRODUCT(B2:B4, C2:C4)/SUM(B2:B4), which gives 26.4","=SUM(B2:B4)/SUM(C2:C4), which gives 2.5","=SUMPRODUCT(B2:B4, C2:C4)/SUM(C2:C4), which gives 66"],"answer":3,"explanation":"Weighted average = Σ(price × quantity)/Σquantity = (1,200 + 2,400 + 3,000)/100 = 66. The simple average (83.33) gives the expensive, low-volume item too much weight.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-552","question":"Table a has key values 1, NULL and 2; table b has key values 1, NULL and 3. How many rows does SELECT * FROM a JOIN b ON a.k = b.k return?","options":["2","1","3","0"],"answer":1,"explanation":"Only the rows with key 1 match. NULL = NULL is unknown, not true, so the two NULL keys do not join to each other; 2 and 3 have no partners. Joining NULLs requires an explicit condition such as a.k IS NOT DISTINCT FROM b.k.","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-553","question":"Customers: Asha (1), Ravi (2), Meena (3). Orders (cid, amt): (1, 300), (1, 700), (2, 450), (3, 520), (3, 100). Which names does SELECT name FROM c WHERE EXISTS (SELECT 1 FROM o WHERE o.cid = c.id AND o.amt > 500) return?","options":["Asha only","Asha, Ravi and Meena","Asha and Meena","Meena only"],"answer":2,"explanation":"EXISTS is true for a customer with at least one order above 500: Asha (700) and Meena (520). Ravi's only order is 450. Each customer appears once even if several orders qualify.","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-554","question":"Table r(region, rev) has N 200, S 300, E 500. What does ROUND(100.0 * rev / SUM(rev) OVER (), 1) return for region S?","options":["30.0","100.0","60.0","33.3"],"answer":0,"explanation":"SUM(rev) OVER () with an empty window is the grand total over all rows (1,000), repeated on every row, so S's share is 300/1,000 = 30%. Unlike GROUP BY, the window keeps every row. 33.3 would be a simple one-in-three share.","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-555","question":"A January cohort of 1,000 sign-ups has 600 active users in month 1 and 450 in month 2. An analyst reports 'month-2 retention of 75%'. What is the issue?","options":["None; 75% is the standard month-2 retention","Month-2 retention should be 60%","75% is retention relative to month 1; retention relative to the original cohort is 45%","Month-2 retention should be 25%, the share lost"],"answer":2,"explanation":"Cohort retention is normally measured against the starting cohort: 450/1,000 = 45%. 450/600 = 75% is month-over-month retention, a different and more flattering metric; dashboards must say which is used.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-556","question":"A retailer buys a seasonal item at ₹60 and sells it at ₹100; unsold units are cleared at ₹20. Each unit of unmet demand also costs an estimated ₹10 in lost goodwill. What critical ratio should set the order quantity?","options":["About 0.556","0.500","About 0.444","0.400"],"answer":0,"explanation":"Underage cost = lost margin + goodwill = 40 + 10 = 50; overage cost = 60 − 20 = 40. Critical ratio = 50/(50 + 40) ≈ 0.556. Ignoring goodwill gives 40/80 = 0.5; swapping the costs gives 0.444.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-557","question":"A machine runs batches of 100 units at 1 minute per unit. A SMED project cuts the changeover from 60 to 20 minutes, and the batch size is kept at 100. By how much does hourly capacity rise?","options":["About 33%","About 67%","About 25%","Nil, because run time per unit is unchanged"],"answer":0,"explanation":"Capacity = 100/(setup + 100) per minute: 100/160 → 37.5 per hour; 100/120 → 50 per hour, a rise of about 33%. The 67% figure is the cut in setup time itself, not the capacity gain.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-558","question":"A single-server help desk (M/M/1) receives 8 requests an hour and serves 10 an hour. If the server's speed is doubled to 20 an hour, what happens to the average time a request spends in the system?","options":["It halves, from 30 to 15 minutes","It falls from 30 to 10 minutes","It falls from 30 minutes to 5 minutes","It falls from 24 to 3 minutes"],"answer":2,"explanation":"W = 1/(μ − λ): 1/(10 − 8) h = 30 min before; 1/(20 − 8) h = 5 min after. Because waiting depends on the gap μ − λ, doubling speed cuts time in system six-fold, far more than half.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-559","question":"A contact centre receives 120 calls an hour, and calls last 3 minutes on average. What is the offered traffic load in Erlangs, and what does it mean?","options":["40 Erlangs – 40 calls arrive per agent","6 Erlangs – on average 6 agents would be busy continuously","0.05 Erlangs – each call uses 5% of an hour","360 Erlangs – total call-minutes per hour"],"answer":1,"explanation":"Offered load = arrival rate × average handling time = 120 × 3/60 = 6 Erlangs. It is the average number of simultaneously busy servers, so more than 6 agents are needed for a stable queue.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-560","question":"Demand grows by exactly 10 units every period. Simple exponential smoothing with α = 0.2 has been used for a long time. Once things settle, by how much does each period's forecast fall short of that period's actual demand?","options":["40 units","10 units","8 units","50 units"],"answer":3,"explanation":"On a linear trend, simple smoothing settles into a steady lag: the error (actual − forecast) equals trend/α = 10/0.2 = 50. Lower α means a smoother but more lagging forecast, which is why trend-adjusted (Holt) smoothing exists.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-561","question":"A process has Cp = 2.0 (spec limits ±6σ) and its mean then drifts by 1.5σ, as assumed in Six Sigma tables. What is its Cpk?","options":["1.5","2.0","0.5","1.0"],"answer":0,"explanation":"The nearer limit is now 6σ − 1.5σ = 4.5σ from the mean, so Cpk = 4.5σ/3σ = 1.5. This is the 'six sigma with a 1.5σ shift' process that yields about 3.4 defects per million.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-562","question":"A p-chart is used for a process with p̄ = 0.05. What is the smallest sample size that gives a positive lower control limit with 3-sigma limits?","options":["171","172","100","20"],"answer":1,"explanation":"LCL > 0 needs p̄ > 3√(p̄(1 − p̄)/n), i.e. n > 9(1 − p̄)/p̄ = 9 × 0.95/0.05 = 171. So n must exceed 171; the smallest integer is 172. Without a positive LCL the chart cannot signal improvements.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-563","question":"A project's critical path is 120 days long, but the contract requires completion in 110 days. When CPM is computed backward from the 110-day deadline, what will activities on the critical path show?","options":["A total float of 0, as on any critical path","A total float of plus 10 days","A total float of minus 10 days, meaning they must be compressed by 10 days","No float, because backward passes always start from the project's own length"],"answer":2,"explanation":"If the latest finish is set to the contractual date, the backward pass gives LS < ES on the longest path: negative float of −10 days, which shows how much crashing or re-sequencing is needed.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-564","question":"Three activities have PERT estimates (optimistic, most likely, pessimistic) in days: P (2, 5, 14), Q (4, 6, 8), R (1, 8, 9). Which activity's duration is most uncertain, as measured by PERT variance?","options":["R, with variance about 1.78","Q, with variance about 0.44","R, because its most likely time is the longest","P, with variance 4"],"answer":3,"explanation":"PERT variance = ((b − a)/6)²: P = (12/6)² = 4, Q = (4/6)² ≈ 0.44, R = (8/6)² ≈ 1.78. Uncertainty depends on the spread between optimistic and pessimistic times, not on the most likely value.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-565","question":"An LP has the constraints x + y ≤ 10, x ≤ 6 and 2x + 2y ≤ 30, with x, y ≥ 0. Which constraint is redundant?","options":["x ≤ 6","2x + 2y ≤ 30","x + y ≤ 10","None; all three shape the feasible region"],"answer":1,"explanation":"2x + 2y ≤ 30 is x + y ≤ 15, which is automatically satisfied whenever x + y ≤ 10. Removing it does not change the feasible region; x ≤ 6 does cut it.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-566","question":"Three workers must be assigned to four jobs, one job each at most, to minimise cost. How should the Hungarian method be applied?","options":["Add a dummy job column with zero costs","Delete the most expensive job before solving","Assign two jobs to the cheapest worker","Add a dummy worker row with zero costs; the job assigned to it is the one left undone"],"answer":3,"explanation":"The method needs a square matrix. With more jobs than workers, a dummy worker with zero costs balances it; whichever job goes to the dummy is not performed. A dummy job would be used if workers outnumbered jobs.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-567","question":"A firm surveys customers by first dividing them into regions and then randomly sampling within each region in proportion to its size. What is this design, and what is its main advantage?","options":["Stratified sampling; it ensures every region is represented and usually reduces sampling error","Cluster sampling; it is cheapest because whole regions are surveyed","Systematic sampling; it picks every k-th customer","Convenience sampling; it is the quickest"],"answer":0,"explanation":"Stratified sampling draws random samples within homogeneous subgroups. When strata differ, it gives more precise estimates than a simple random sample of the same size. Cluster sampling instead selects whole groups at random.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-568","question":"Across 1,000 customers, the correlation between app sessions and spend is r = 0.3, with p < 0.001. Which interpretation is correct?","options":["The relationship is strong because the p-value is tiny","Sessions cause about 30% of spend","The relationship is statistically significant but weak: sessions explain only about 9% of the variation in spend","It cannot be significant because r is below 0.5"],"answer":2,"explanation":"With a large sample even a modest correlation is unlikely to be zero, so it is significant. But r² = 0.09: only 9% of the variance is shared. Significance measures confidence that an effect exists, not its size; and correlation is not causation.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-569","question":"A batch of 500 components comes from a process with a 0.4% defect rate. Using the Poisson approximation, what is the probability that the batch contains no defectives?","options":["About 0.135","About 0.996","About 0.271","About 0.002"],"answer":0,"explanation":"λ = np = 500 × 0.004 = 2, so P(0) = e⁻² ≈ 0.135. 0.996 is the chance a single part is good; 0.271 is P(exactly one) or P(exactly two).","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-570","question":"=VLOOKUP(\"Pune\", A2:B50, 2, FALSE) returns #N/A, although the sheet visibly shows 'Pune' in A17. The data were pasted from another system. What is the most likely cause and fix?","options":["VLOOKUP cannot search text; use MATCH instead","Hidden trailing spaces or non-printing characters in A17; clean the column with TRIM/CLEAN and look up again","FALSE must be TRUE for text lookups","The return column must be to the left of the lookup column"],"answer":1,"explanation":"Imported data often carry trailing spaces or non-breaking characters, so 'Pune ' ≠ 'Pune' for an exact match. Cleaning the lookup column (or the lookup value) usually fixes it. TRUE would risk wrong matches on unsorted data.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-571","question":"A2:A7 hold the regions N, S, N, E, N, S and B2:B7 hold order values 300, 450, 520, 200, 410, 380. What does =MAXIFS(B2:B7, A2:A7, \"N\") + MINIFS(B2:B7, A2:A7, \"S\") return?","options":["970","720","1,000","900"],"answer":3,"explanation":"The largest North value is 520 (from 300, 520, 410) and the smallest South value is 380 (from 450, 380). 520 + 380 = 900. Using South's maximum (450) gives 970.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-572","question":"A2:A101 hold product IDs stored as text (for example '101'), and C1 holds the number 101. What does =VLOOKUP(C1, A2:B101, 2, FALSE) return?","options":["The value next to '101', since Excel converts automatically","0","#N/A, because the number 101 does not match the text '101'","#VALUE!"],"answer":2,"explanation":"Exact-match lookups compare type as well as value: the number 101 is not equal to the text '101'. Converting one side – for example looking up TEXT(C1,\"0\") or C1&\"\", or converting the column to numbers – fixes it.","difficulty":"very-hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-573","question":"A1 contains 'Professional Services'. What does =IF(ISNUMBER(SEARCH(\"serv\", A1)), \"Service line\", \"Other\") return?","options":["Other","#VALUE!","Service line","14"],"answer":2,"explanation":"SEARCH is not case-sensitive and returns the position of 'serv' (14) in 'Professional Services'. ISNUMBER turns that into TRUE, so the IF returns 'Service line'. If the text were absent, SEARCH would return #VALUE! and ISNUMBER would give FALSE.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-574","question":"Table s(id, amt) has amounts 100, 250, 500, 1000 and 250. How many rows satisfy WHERE amt BETWEEN 250 AND 500?","options":["1","3","2","4"],"answer":1,"explanation":"BETWEEN is inclusive at both ends, so 250, 500 and the second 250 qualify: 3 rows. Treating the bounds as exclusive gives 0 or 1, and forgetting the duplicate 250 gives 2.","difficulty":"hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-575","question":"Table s(id, amt, status) has (1, 100, paid), (2, 250, due), (3, 500, paid), (4, 1000, refund), (5, 250, paid). What does SELECT 1.0 * SUM(CASE WHEN status = 'paid' THEN amt ELSE 0 END) / SUM(amt) FROM s return?","options":["0.6","About 0.85","0","About 0.405"],"answer":3,"explanation":"Paid amounts: 100 + 500 + 250 = 850; total = 2,100; share ≈ 0.405. 0.6 is the share of paid rows (3 of 5), not of value. Multiplying by 1.0 avoids integer division, which in some databases would give 0.","difficulty":"very-hard","source":"Business analyst · SQL test"},
  {"id":"mgmt-operations-analytics-576","question":"A subscription app earns ₹500 a month per user at a 60% gross margin, and 4% of users churn each month. Acquiring a user costs ₹2,500. Ignoring discounting, what is the LTV/CAC ratio?","options":["3.0","5.0","0.12","1.8"],"answer":0,"explanation":"Expected lifetime = 1/0.04 = 25 months, so LTV = 500 × 0.6 × 25 = ₹7,500. LTV/CAC = 7,500/2,500 = 3.0. Using revenue instead of gross margin gives 12,500/2,500 = 5.0, overstating unit economics.","difficulty":"very-hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-577","question":"A customer first clicked a social-media ad, later a search ad, and finally an email link before buying for ₹3,000. Under last-touch attribution, and under an equal-weight linear model, how much revenue is credited to the search ad?","options":["₹3,000 under last-touch; ₹1,000 under linear","₹1,000 under both","Nil under last-touch; ₹1,000 under linear","Nil under both"],"answer":2,"explanation":"Last-touch gives all credit to the final touch – the email. A linear model splits credit equally among the three touches: ₹1,000 each. Attribution choices can change which channel looks profitable.","difficulty":"hard","source":"Business analyst · MBA placement"},
  {"id":"mgmt-operations-analytics-578","question":"For a commodity component, buyers will consider a supplier only if its quality meets the industry standard, but they choose among such suppliers mainly on price. In operations-strategy terms, what are quality and price here?","options":["Quality is the order winner; price is the order qualifier","Quality is an order qualifier; price is the order winner","Both are order winners","Both are order qualifiers"],"answer":1,"explanation":"Order qualifiers are criteria a firm must meet to be considered at all; order winners are those on which it beats competitors. Qualifiers must be kept at par; winners deserve extra investment.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-579","question":"On the product–process matrix, which pairing is most typical?","options":["Low-volume, high-variety products with a continuous-flow process","High-volume standard products with a job-shop process","One-off projects with an assembly line","Low-volume, high-variety custom products with a job-shop process"],"answer":3,"explanation":"The matrix pairs one-off products with projects, low-volume high-variety work with job shops, batches with batch processes, high-volume standard products with assembly lines, and commodities with continuous flow. Off-diagonal positions usually carry cost or flexibility penalties.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-580","question":"Demand requires a takt time of 45 seconds, but the bottleneck station's work content is 50 seconds and cannot be split. What is the minimum fix that lets the line meet takt?","options":["Duplicate the bottleneck station so that two operators work in parallel","Speed up the non-bottleneck stations","Increase the batch size","Reduce the takt time to 40 seconds"],"answer":0,"explanation":"An indivisible 50-second task cannot meet a 45-second takt on one station. Two parallel stations give an effective cycle of 25 seconds, which meets takt. Faster non-bottlenecks or bigger batches do not change the bottleneck's rate.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-581","question":"Four jobs wait at one machine (processing days; due day): A (3; 5), B (2; 4), C (4; 12), D (5; 9). What is the maximum lateness under the earliest-due-date rule, compared with shortest processing time?","options":["EDD gives 5 days; SPT gives 2 days","Both give 2 days","EDD gives 0 days; SPT gives 5 days","EDD gives 2 days; SPT gives 5 days"],"answer":3,"explanation":"EDD order B, A, D, C finishes at 2, 5, 10, 14 – lateness −2, 0, 1, 2 – so the maximum is 2. SPT order B, A, C, D finishes D at day 14 against a due day of 9: lateness 5. EDD minimises maximum lateness on a single machine.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-582","question":"A control system has three identical sensors, each with reliability 0.9, and it works if at least two of the three work (independent failures). What is the system's reliability?","options":["0.972","0.999","0.729","0.900"],"answer":0,"explanation":"P(exactly 2 work) = 3 × 0.9² × 0.1 = 0.243 and P(all 3) = 0.729, so R = 0.972. 0.999 is the 1-out-of-3 (parallel) figure; 0.729 is all three in series.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-583","question":"A planner computes the EOQ using an annual demand forecast that turns out to be 50% too high (true demand is two-thirds of the forecast). By roughly what percentage do the actual ordering-plus-holding costs exceed the true minimum?","options":["About 50%","About 2%","About 22%","About 11%"],"answer":1,"explanation":"The lot used is √1.5 ≈ 1.22 times the true EOQ, and the cost ratio is ½(1.22 + 1/1.22) ≈ 1.021, only about 2% above the minimum. The EOQ cost curve is very flat near its optimum, which is why EOQ is robust to estimation errors.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-584","question":"At a single-server counter (M/M/1) with λ = 6 per hour and μ = 8 per hour, what is the difference between the average number in the system (L) and the average number in the queue (Lq)?","options":["1","2.25","0.75","3"],"answer":2,"explanation":"L = ρ/(1 − ρ) = 0.75/0.25 = 3 and Lq = ρ²/(1 − ρ) = 2.25, so L − Lq = 0.75 = ρ, the average number being served. It is not 1, because the server is idle 25% of the time.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-585","question":"A line's tasks total 40 minutes of work per unit and the cycle time is 6 minutes. Precedence constraints force the planner to use 8 stations. What is the line efficiency, and how does it compare with the theoretical minimum number of stations?","options":["About 83.3%; the theoretical minimum is 8 stations","About 95.2%; the theoretical minimum is 7 stations","About 66.7%; the theoretical minimum is 6 stations","About 83.3%; the theoretical minimum is 7 stations"],"answer":3,"explanation":"Efficiency = work content ÷ (stations × cycle time) = 40/(8 × 6) ≈ 83.3%. Minimum stations = ⌈40/6⌉ = ⌈6.67⌉ = 7, so precedence costs one extra station. 95.2% would be the efficiency with 7 stations.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-586","question":"What does =DATE(2028,3,1) - DATE(2028,2,1) return in Excel (with the result formatted as a number)?","options":["28","29","30","1"],"answer":1,"explanation":"Excel stores dates as serial numbers, so subtracting gives the number of days between them. 2028 is a leap year, so February has 29 days. Assuming a 28-day February gives the trap answer.","difficulty":"hard","source":"Business analyst · Excel test"},
  {"id":"mgmt-operations-analytics-587","question":"Payoffs (₹ lakh) for three acts under three equally uncertain states: A: 50, 20, 10; B: 30, 30, 30; C: 70, 0, 5. Which act is chosen under the maximax, maximin and Laplace (equal-likelihood) criteria respectively?","options":["C, B and B","C, B and A","A, B and C","C, C and B"],"answer":0,"explanation":"Maximax picks the best best-case: C (70). Maximin picks the best worst-case: B (30). Laplace averages: A 26.7, B 30, C 25, so B. A risk-neutral decision-maker with equal probabilities and a cautious one agree here.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-588","question":"A pump fails at random with a mean time between failures of 500 hours, and each failure is repaired instantly. What is the probability of exactly 2 failures in 1,000 hours?","options":["About 0.135","About 0.5","About 0.271","About 0.368"],"answer":2,"explanation":"Failures in a period follow a Poisson distribution with mean 1,000/500 = 2, so P(2) = e⁻² × 2²/2! ≈ 0.271. 0.135 is P(0); expecting exactly the mean to occur half the time is a common mistake.","difficulty":"very-hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-589","question":"A distributor ships 500 units a day from a port to its warehouse, and goods spend 12 days on the road. Each unit is worth ₹2,000 and carrying cost is 18% a year (365 days). What is the average pipeline (in-transit) inventory and its annual carrying cost?","options":["500 units; about ₹1.8 lakh a year","6,000 units; about ₹1.2 crore a year","6,000 units; about ₹21.6 lakh a year","3,000 units; about ₹10.8 lakh a year"],"answer":2,"explanation":"Little's law: pipeline stock = flow × time = 500 × 12 = 6,000 units, worth ₹1.2 crore. At 18% a year, carrying cost ≈ ₹21.6 lakh. Halving it (3,000) wrongly treats in-transit stock like cycle stock.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-590","question":"A firm's inventory turnover (COGS ÷ average inventory at cost) is 8 a year, and it targets 12 without any change in COGS of ₹96 crore. Using a 360-day year, how much inventory investment is released and what happens to days of inventory?","options":["₹4 crore is released; days fall from 30 to 45","₹4 crore is released; days of inventory fall from 45 to 30","₹12 crore is released; days fall from 45 to 30","₹8 crore is released; days fall from 45 to 15"],"answer":1,"explanation":"Average inventory = 96/8 = ₹12 crore now and 96/12 = ₹8 crore at the target, freeing ₹4 crore. Days of inventory = 360/turns: 45 → 30. Releasing the whole ₹12 crore confuses the old level with the reduction.","difficulty":"hard","source":"Ops MT · MBA placement"},
  {"id":"mgmt-operations-analytics-591","question":"A gauge study on a shaft diameter finds a total observed standard deviation of 5 µm, of which the repeatability-and-reproducibility (measurement system) component has a standard deviation of 2 µm. Using the common guideline (under 10% acceptable, 10–30% marginal, over 30% unacceptable), how should the measurement system be judged?","options":["%GRR = 40%, so the measurement system is unacceptable","%GRR = 16%, so it is marginal","%GRR = 4%, so it is acceptable","%GRR = 60%, so it is unacceptable"],"answer":0,"explanation":"%GRR on the study-variation basis compares standard deviations: 2/5 = 40%, above 30%, so the gauge cannot reliably tell good parts from bad. 16% is the variance ratio (4/25), which understates the problem.","difficulty":"very-hard","source":"Operations · quality · MBA placement"},
  {"id":"mgmt-operations-analytics-592","question":"An FMEA scores three failure modes (severity, occurrence, detection, each 1–10). F1: 9, 2, 3. F2: 4, 6, 4. F3: 6, 3, 5. Most current FMEA guidance says very high severity must be addressed regardless of the risk priority number. Which mode should be tackled first?","options":["F2, because it has the highest RPN (96)","F1, because its severity of 9 signals a safety-critical effect, even though its RPN (54) is the lowest","F3, because it is the hardest to detect","All three equally, because RPNs are close"],"answer":1,"explanation":"RPNs are F1 54, F2 96, F3 90. Ranking purely by RPN would put a potential safety failure last; because RPN multiplies ordinal scales, a severity-first rule (or action-priority tables) takes precedence.","difficulty":"hard","source":"Operations · quality · MBA placement"},
  {"id":"mgmt-operations-analytics-593","question":"A line makes three models with daily demand A 240, B 120 and C 60. To level production (heijunka), the plant repeats the smallest mixed-model cycle that keeps the daily ratio. What is that cycle and how often does it repeat each day?","options":["One each of A, B and C, repeated 140 times","Batches of 240 A, then 120 B, then 60 C, once a day","4 A, 2 B and 1 C, repeated 60 times","2 A, 1 B and 1 C, repeated 60 times"],"answer":2,"explanation":"The ratio 240:120:60 reduces to 4:2:1, so the minimum cycle is 7 units (for example A-B-A-C-A-B-A), repeated 420/7 = 60 times. Daily batches defeat levelling, and 'one of each' does not match demand.","difficulty":"hard","source":"Operations · lean · MBA placement"},
  {"id":"mgmt-operations-analytics-594","question":"A project has a budget at completion of ₹200 lakh. To date, earned value is ₹90 lakh and actual cost is ₹100 lakh. What cost performance index must the remaining work achieve to finish exactly on the original budget (TCPI based on BAC)?","options":["0.90","1.11","1.22","1.10"],"answer":3,"explanation":"TCPI = (BAC − EV)/(BAC − AC) = (200 − 90)/(200 − 100) = 1.10: every remaining rupee must deliver ₹1.10 of work. 0.90 is the current CPI and 1.11 is its reciprocal.","difficulty":"hard","source":"Operations · project management · MBA placement"},
  {"id":"mgmt-operations-analytics-595","question":"A churn model has an ROC AUC of 0.80. What is the most accurate interpretation?","options":["If one churner and one non-churner are picked at random, there is an 80% chance the model gives the churner a higher score","The model classifies 80% of customers correctly","80% of customers flagged as churners actually churn","The model catches 80% of all churners"],"answer":0,"explanation":"AUC measures ranking ability across all thresholds: the probability that a random positive outranks a random negative. Accuracy, precision and recall each depend on one chosen threshold.","difficulty":"hard","source":"Business analytics · MBA placement"},
  {"id":"mgmt-operations-analytics-596","question":"A bank mails 50,000 customers, of whom 2,000 respond. When customers are ranked by a model's score, the top 10% (5,000 customers) contain 700 of the responders. What is the lift in the top decile?","options":["35%","3.5","14","1.4"],"answer":1,"explanation":"Top-decile response rate = 700/5,000 = 14% against an overall rate of 2,000/50,000 = 4%, so lift = 14/4 = 3.5. 35% is the share of all responders captured in the top decile (the gains figure).","difficulty":"hard","source":"Business analytics · MBA placement"},
  {"id":"mgmt-operations-analytics-597","question":"Base year: product A, price ₹10, quantity 20; product B, price ₹5, quantity 40. Current year: A, price ₹12, quantity 15; B, price ₹10, quantity 60. What are the Paasche and Fisher price indices?","options":["Paasche 160.0; Fisher 166.5","Paasche 173.3; Fisher 166.7","Paasche 173.3; Fisher 166.5","Paasche 166.7; Fisher 173.3"],"answer":2,"explanation":"Laspeyres = (12×20 + 10×40)/(10×20 + 5×40) = 640/400 = 160. Paasche = (12×15 + 10×60)/(10×15 + 5×60) = 780/450 = 173.3. Fisher = √(160 × 173.3) ≈ 166.5, a geometric mean; 166.7 is the arithmetic mean, and 160 is Laspeyres.","difficulty":"very-hard","source":"Business analytics · statistics · MBA placement"},
  {"id":"mgmt-operations-analytics-598","question":"A linear regression of weekly units sold on price gives a slope of −20 units per rupee. The average price is ₹15 and average weekly sales are 200 units. What is the price elasticity of demand at the means?","options":["−20","−266.7","−0.67","−1.5"],"answer":3,"explanation":"Elasticity = slope × (P̄/Q̄) = −20 × 15/200 = −1.5, so demand is elastic at the mean. The raw slope is in units per rupee, not a percentage; −0.67 inverts the ratio.","difficulty":"hard","source":"Business analytics · MBA placement"},
  {"id":"mgmt-operations-analytics-599","question":"A maker of electronic controllers sees many failures in the first weeks of use, very few for several years, and then a rising failure rate as parts wear out. What practice targets the first phase of this bathtub curve?","options":["Burn-in testing before shipment, to weed out weak units","Scheduled preventive replacement after several years","Doubling the warranty period","Relaxing incoming inspection"],"answer":0,"explanation":"Early ('infant mortality') failures come from manufacturing defects, so running units under stress before shipment removes them. Preventive replacement targets the wear-out phase at the other end.","difficulty":"moderate","source":"Operations · reliability · MBA placement"},
  {"id":"mgmt-operations-analytics-600","question":"An LP maximises Z = c₁x + 4y subject to 2x + y ≤ 16, x + 2y ≤ 14 and x, y ≥ 0. With c₁ = 3 the optimum is at (6, 4). Over what range of c₁ does this corner stay optimal (with y's coefficient fixed at 4)?","options":["0.5 ≤ c₁ ≤ 2","2 ≤ c₁ ≤ 8","3 ≤ c₁ ≤ 8","c₁ ≥ 2 only"],"answer":1,"explanation":"The corner stays optimal while the objective's slope ratio c₁/4 lies between the binding constraints' ratios, 1/2 (from x + 2y) and 2 (from 2x + y). So 2 ≤ c₁ ≤ 8. The range 0.5–2 is the ratio itself, before multiplying by 4.","difficulty":"very-hard","source":"Operations research · MBA placement"},
  {"id":"mgmt-operations-analytics-601","question":"A paint company stocks only white base paint and a few colourants at its dealers, and tints each can to the customer's chosen shade in the store. What is this supply-chain practice and its main benefit?","options":["Cross-docking; lower transport cost","Vendor-managed inventory; fewer stock-outs at the supplier","Postponement; it delays differentiation until demand is known, cutting inventory and stock-outs across thousands of shades","Make-to-stock; faster delivery of finished colours"],"answer":2,"explanation":"Postponement holds stock in a generic form and customises late, so aggregate base demand is pooled and far less finished-goods inventory is needed. It suits high-variety products with uncertain demand for each variant.","difficulty":"hard","source":"Operations · supply chain · MBA placement"},
  {"id":"mgmt-operations-analytics-602","question":"A workshop keeps screws in two bins. It uses the first bin, and when it is empty it orders a fresh supply and starts drawing from the second bin, which holds enough to cover demand during the lead time plus a safety margin. What kind of inventory system is this?","options":["A periodic-review system","An ABC-classification system","A material requirements planning system","A simple continuous-review (fixed-order-quantity) system in which the second bin is the reorder point"],"answer":3,"explanation":"The two-bin system is a visual fixed-quantity, reorder-point system: an empty first bin signals that stock has fallen to the reorder point. It suits cheap, high-use C-class items where formal tracking costs more than it saves.","difficulty":"moderate","source":"Operations · inventory · MBA placement"},
  {"id":"mgmt-operations-analytics-603","question":"In Kraljic's purchasing portfolio matrix, a component with low profit impact but high supply risk (one specialised supplier, hard to substitute) falls in which quadrant, and what strategy suits it?","options":["Bottleneck item; secure supply through buffer stock, long-term contracts or developing alternatives","Leverage item; use competitive bidding to cut price","Strategic item; build a deep partnership with joint development","Non-critical item; simplify and automate buying"],"answer":0,"explanation":"Kraljic classifies items by profit impact and supply risk. Low impact with high risk is a bottleneck item, where the priority is assuring supply, not saving money. Leverage items are high impact, low risk.","difficulty":"hard","source":"Operations · procurement · MBA placement"},
  {"id":"mgmt-operations-analytics-604","question":"A buyer in Pune imports machinery from Germany. Under Incoterms, which statement correctly contrasts EXW (Ex Works) with DDP (Delivered Duty Paid)?","options":["Under EXW the seller pays export clearance and main freight; under DDP the buyer pays import duty","Under EXW the buyer bears nearly all costs and risks from the seller's premises; under DDP the seller bears all costs and risks up to delivery, including import duties","Both terms transfer risk when goods are loaded on the ship","Under DDP risk passes to the buyer at the seller's factory"],"answer":1,"explanation":"EXW is the minimum obligation for the seller: the goods are simply made available at its premises. DDP is the maximum: the seller delivers to the named place, cleared for import with duties paid. Most other terms fall between these two extremes.","difficulty":"hard","source":"Operations · supply chain · MBA placement"},
  {"id":"mgmt-operations-analytics-605","question":"Two managers rank five suppliers (1 = best). Manager X: S1 1, S2 2, S3 3, S4 4, S5 5. Manager Y: S1 2, S2 1, S3 4, S4 3, S5 5. What is Spearman's rank correlation between their rankings?","options":["0.2","0","0.8","0.97"],"answer":2,"explanation":"Rank differences are 1, 1, 1, 1, 0, so Σd² = 4. ρ = 1 − 6Σd²/[n(n² − 1)] = 1 − 24/120 = 0.8. 0.2 forgets to subtract from 1, 0 uses n² − 1 without multiplying by n, and 0.97 drops the 6.","difficulty":"hard","source":"Business analytics · statistics · MBA placement"},
  {"id":"mgmt-operations-analytics-606","question":"A u-chart tracks defects per unit of fabric rolls. The average is ū = 0.5 defects per unit, and each sample inspects 8 units. What are the 3-sigma control limits for a sample?","options":["UCL 2.62, LCL 0","UCL 1.25, LCL −0.25","UCL 1.03, LCL 0","UCL 1.25, LCL 0"],"answer":3,"explanation":"For a u-chart, limits are ū ± 3√(ū/n) = 0.5 ± 3 × 0.25, giving 1.25 and −0.25; a negative lower limit is set to 0. Leaving out n gives 2.62, and using the p-chart formula gives 1.03.","difficulty":"hard","source":"Operations · quality · MBA placement"},
  {"id":"mgmt-operations-analytics-607","question":"A filling line's mean drifts upward by about half a standard deviation and stays there. A standard Shewhart X̄ chart with 3-sigma limits takes many samples to signal it. Which tool is designed to catch such small, sustained shifts faster?","options":["A CUSUM or EWMA chart, which accumulate information from past samples","A wider 4-sigma X̄ chart","A Pareto chart of defect types","An R chart"],"answer":0,"explanation":"Shewhart charts use each sample alone, so small shifts rarely cross the limits. CUSUM and EWMA charts accumulate deviations over time and detect shifts of about 0.5–1.5σ much sooner. Wider limits would make detection even slower.","difficulty":"very-hard","source":"Operations · quality · MBA placement"},
  {"id":"mgmt-operations-analytics-608","question":"Table ord(cust, day) has rows (A, 1), (A, 5), (A, 12), (B, 3), (B, 4). What does this query return?\nSELECT AVG(gap) FROM (SELECT LEAD(day) OVER (PARTITION BY cust ORDER BY day) − day AS gap FROM ord) t;","options":["2.4","4","2.75","3.25"],"answer":1,"explanation":"Gaps: A → 4, 7, NULL; B → 1, NULL. AVG ignores NULLs: (4 + 7 + 1)/3 = 4. Treating NULLs as 0 gives 2.4; leaving out PARTITION BY gives 2.75; averaging each customer first gives 3.25.","difficulty":"hard","source":"Business analytics · SQL · MBA placement"},
  {"id":"mgmt-operations-analytics-609","question":"cust has rows (1, Asha), (2, Ravi), (3, Meena). ord(oid, cid, status) has (10, 1, 'paid'), (11, 1, 'due'), (12, 2, 'due'). How many rows does each query return?\nP: SELECT c.name, o.oid FROM cust c LEFT JOIN ord o ON c.id = o.cid AND o.status = 'paid';\nQ: SELECT c.name, o.oid FROM cust c LEFT JOIN ord o ON c.id = o.cid WHERE o.status = 'paid';","options":["P = 1, Q = 1","P = 4, Q = 1","P = 3, Q = 1","P = 3, Q = 3"],"answer":2,"explanation":"In P the filter is part of the join, so every customer is kept: Asha with order 10, and Ravi and Meena with NULLs (3 rows). In Q the WHERE runs after the join and removes rows whose status is NULL or 'due', leaving only Asha's order 10, which silently turns the left join into an inner join.","difficulty":"very-hard","source":"Business analytics · SQL · MBA placement"},
  {"id":"mgmt-operations-analytics-610","question":"orders(oid, cust, amount): (1, A, 100), (2, A, 200), (3, A, 600), (4, B, 300), (5, B, 500), (6, C, 900). How many rows does this return?\nSELECT oid FROM orders o WHERE amount > (SELECT AVG(amount) FROM orders WHERE cust = o.cust);","options":["3","1","4","2"],"answer":3,"explanation":"The subquery is correlated, so each order is compared with its own customer's average: A's average is 300 (order 3 qualifies), B's 400 (order 5), and C's 900 (900 is not greater than itself). Two rows. Comparing with the overall average of about 433 would give 3.","difficulty":"hard","source":"Business analytics · SQL · MBA placement"},
  {"id":"mgmt-operations-analytics-611","question":"A1 holds 95. What does =IFS(A1>=50, \"C\", A1>=70, \"B\", A1>=90, \"A\", TRUE, \"F\") return?","options":["\"C\"","\"A\"","\"F\"","#N/A"],"answer":0,"explanation":"IFS returns the value for the first condition that is TRUE, testing in order. 95 >= 50 is already TRUE, so it returns \"C\". The conditions must run from the highest threshold down for the grading to work.","difficulty":"hard","source":"Business analytics · Excel · MBA placement"},
  {"id":"mgmt-operations-analytics-612","question":"x values 2, 4, 6, 8, 10 are in A2:A6 and y values 30, 34, 35, 41, 45 in B2:B6. What does =FORECAST.LINEAR(12, B2:B6, A2:A6) return?","options":["48.75","48.1","49.0","22.2"],"answer":1,"explanation":"Least-squares slope = Σ(x − x̄)(y − ȳ)/Σ(x − x̄)² = 74/40 = 1.85, and intercept = 37 − 1.85 × 6 = 25.9, so the forecast is 25.9 + 1.85 × 12 = 48.1. 48.75 uses the end-point slope, and 22.2 multiplies the slope by 12 without the intercept.","difficulty":"hard","source":"Business analytics · Excel · MBA placement"},
  {"id":"mgmt-operations-analytics-613","question":"A spare part sells in only about one week out of five, but when it does, it sells 3–20 units. A simple exponential-smoothing forecast keeps showing a small positive number every week and is never right. Which method is designed for such demand?","options":["A 12-month moving average","Holt's trend-adjusted smoothing","Croston's method, which separately smooths the size of non-zero demands and the interval between them","Seasonal decomposition"],"answer":2,"explanation":"Intermittent demand breaks the assumptions of ordinary smoothing. Croston forecasts demand size and inter-demand interval separately and divides them, giving a more sensible demand rate for setting stock levels.","difficulty":"very-hard","source":"Operations · forecasting · MBA placement"},
  {"id":"mgmt-operations-analytics-614","question":"A distributor classifies SKUs not only by annual value (ABC) but also by how variable their demand is: steady (X), fluctuating (Y) and erratic (Z). Which combination is the best candidate for automated replenishment with low safety stock?","options":["CZ","AZ","BZ","AX"],"answer":3,"explanation":"AX items are high value with stable demand, so they can be forecast accurately and replenished automatically with little safety stock, which saves the most money. Z items have erratic demand and need more judgement or make-to-order handling.","difficulty":"moderate","source":"Operations · inventory · MBA placement"},
  {"id":"mgmt-operations-analytics-615","question":"A furniture maker keeps standard frames and fabrics in stock but sews and assembles each sofa only after the customer chooses the fabric and size. Where is its customer order decoupling point, and what kind of system is this?","options":["Between components and final assembly; assemble-to-order","At finished goods; make-to-stock","Before design; engineer-to-order","At raw materials; make-to-order from scratch"],"answer":0,"explanation":"Stock is held as components and the customer's order triggers final assembly, so the decoupling point sits just before assembly: assemble-to-order. Upstream is forecast-driven (push) and downstream is order-driven (pull).","difficulty":"hard","source":"Operations · supply chain · MBA placement"},
  {"id":"mgmt-operations-analytics-616","question":"According to Marshall Fisher, which pairing of product type and supply chain is the best match?","options":["Functional products (stable demand, low margins) with a responsive, buffer-heavy chain","Innovative products (short life, unpredictable demand, high margins) with a responsive chain, and functional products with an efficient, low-cost chain","Innovative products with a lean, lowest-cost chain to protect margins","Both product types with the same efficient chain"],"answer":1,"explanation":"Functional goods such as staples have predictable demand, so efficiency matters most. Innovative goods such as fashion electronics face costly stock-outs and markdowns, so they need speed and buffer capacity; mismatches are a common source of supply-chain failure.","difficulty":"hard","source":"Operations · supply chain · MBA placement"},
  {"id":"mgmt-operations-analytics-617","question":"An auto plant has one truck leave each morning on a fixed route, collecting small loads from six nearby suppliers in turn and delivering the combined load to the plant, instead of each supplier sending a half-empty truck. What is this called?","options":["Cross-docking","Drop shipping","A milk run","Hub-and-spoke"],"answer":2,"explanation":"A milk run consolidates frequent small pickups from several suppliers on a fixed loop, raising truck utilisation and allowing small, frequent deliveries suited to lean production.","difficulty":"moderate","source":"Operations · logistics · MBA placement"},
  {"id":"mgmt-operations-analytics-618","question":"A carrier charges less-than-truckload rates of ₹12/kg for shipments under 2,500 kg and ₹10/kg for 2,500 kg or more, and lets a shipper declare a lighter shipment as 2,500 kg to get the lower rate. A full truck costs ₹30,000. What is the cheapest way to ship 2,200 kg?","options":["LTL at actual weight: ₹26,400","Full truck: ₹30,000","LTL at actual weight with the lower rate: ₹22,000","Declare it as 2,500 kg: ₹25,000"],"answer":3,"explanation":"Actual weight costs 2,200 × ₹12 = ₹26,400; declaring 2,500 kg costs 2,500 × ₹10 = ₹25,000. Declaring pays above 2,500 × 10/12 ≈ 2,083 kg (the weight break). The ₹10 rate cannot be applied to 2,200 kg without declaring 2,500 kg.","difficulty":"very-hard","source":"Operations · logistics · MBA placement"},
  {"id":"mgmt-operations-analytics-619","question":"According to Ferdows and De Meyer's 'sand cone' model, in what order should a plant build lasting capabilities?","options":["Quality, then dependability, then speed, then cost efficiency","Cost, then speed, then dependability, then quality","Speed, then cost, then quality, then dependability","All four at once, since they trade off"],"answer":0,"explanation":"The sand cone says capabilities are cumulative: quality forms the base, dependability builds on it, then speed (flexibility), and cost efficiency comes last as a result of the others. Chasing cost first erodes the foundation.","difficulty":"very-hard","source":"Operations strategy · consulting · MBA placement"},
  {"id":"mgmt-operations-analytics-620","question":"In Schmenner's service process matrix, which service has low labour intensity and low interaction and customisation, and so is a 'service factory'?","options":["A law firm","A budget airline","A hospital's surgery department","A retail bank branch giving tailored advice"],"answer":1,"explanation":"Airlines, trucking and hotels are capital-intensive with standardised service (service factory). Law firms and hospitals are professional services (high labour, high customisation), and tailored advice also leans that way.","difficulty":"hard","source":"Operations · services · MBA placement"},
  {"id":"mgmt-operations-analytics-621","question":"An outbound team makes 400 calls a day, each converting independently with probability 0.1. Using the normal approximation with continuity correction, what is the probability of at least 50 conversions in a day? (Φ(1.58) ≈ 0.943, Φ(1.67) ≈ 0.952, Φ(1.75) ≈ 0.960)","options":["About 4.8%","About 4.0%","About 5.7%","About 94.3%"],"answer":2,"explanation":"Mean = 40, SD = √(400 × 0.1 × 0.9) = 6. 'At least 50' becomes X > 49.5: z = 9.5/6 ≈ 1.58, so P ≈ 1 − 0.943 = 5.7% (exact binomial ≈ 6.0%). 4.8% skips the correction, 4.0% corrects in the wrong direction, and 94.3% forgets the complement.","difficulty":"very-hard","source":"Business analytics · statistics · MBA placement"},
  {"id":"mgmt-operations-analytics-622","question":"A project manager must cut two weeks from a schedule. She considers starting interior work before all structural approvals are complete, instead of after. What is this technique, and what is its main drawback compared with crashing?","options":["Crashing; it always raises direct cost","Resource levelling; it lengthens the project","Critical chain; it removes buffers","Fast-tracking; it overlaps activities originally done in sequence, raising the risk of rework rather than adding cost directly"],"answer":3,"explanation":"Fast-tracking runs sequential activities in parallel, which saves time without extra resources but risks rework if earlier work changes. Crashing adds resources to critical activities at extra cost.","difficulty":"moderate","source":"Operations · project management · MBA placement"},
  {"id":"mgmt-operations-analytics-623","question":"A firm adopting Goldratt's critical chain method strips the safety margin out of each task estimate and instead places one shared buffer at the end of the project chain. What is the main reasoning?","options":["Individual task safety is often wasted through student syndrome and Parkinson's law, while a pooled buffer protects the deadline with less total time","Buffers are unnecessary once estimates are accurate","Each task needs a larger buffer of its own","Removing buffers forces teams to crash every activity"],"answer":0,"explanation":"Padding hidden inside each task tends to be used up anyway (work starts late or expands to fill time). Aggregating safety into a project buffer works like risk pooling: the total protection needed is smaller than the sum of separate pads.","difficulty":"very-hard","source":"Operations · project management · MBA placement"},
  {"id":"mgmt-operations-analytics-624","question":"A firm wants to lay fibre linking five sites at minimum total cable length. Possible links (km): A–B 4, A–C 3, B–C 2, B–D 5, C–D 7, C–E 8, D–E 6, A–E 9. What is the minimum total length that connects all sites?","options":["14 km","16 km","18 km","20 km"],"answer":1,"explanation":"Kruskal's method picks B–C 2, A–C 3, skips A–B 4 (it would close a loop), then B–D 5 and D–E 6: total 16 km. 14 km adds the four cheapest links including the loop, and 20 km is the star from C.","difficulty":"hard","source":"Operations research · MBA placement"},
  {"id":"mgmt-operations-analytics-625","question":"Pipelines (capacity in kilolitres per hour): Source→A 10, Source→B 8, A→B 2, A→Sink 6, B→Sink 9. What is the maximum flow from Source to Sink?","options":["18","16","15","14"],"answer":2,"explanation":"The cut through the two links into the sink has capacity 6 + 9 = 15, and 15 can be achieved: Source→A 8 (6 to Sink, 2 to B) and Source→B 7, giving B 9 to Sink. 18 is only the source's outgoing capacity, and 16 is another, larger cut.","difficulty":"very-hard","source":"Operations research · MBA placement"},
  {"id":"mgmt-operations-analytics-626","question":"A van leaves depot D, visits A, B, C and E once each and returns. Distances (km): D–A 30, D–B 19, D–C 18, D–E 17, A–B 15, A–C 22, A–E 23, B–C 14, B–E 25, C–E 20. What is the length of the nearest-neighbour tour, and how does it compare with the best tour?","options":["96 km, which is the optimum","87 km, which is the optimum","66 km, 21 km shorter than the best","96 km, 9 km longer than the best tour of 87 km"],"answer":3,"explanation":"Nearest neighbour goes D→E (17)→C (20)→B (14)→A (15)→D (30) = 96 km. The tour D→C→B→A→E→D = 18 + 14 + 15 + 23 + 17 = 87 km is shorter: greedy choices strand the van far from the depot. 66 km forgets the return leg.","difficulty":"very-hard","source":"Operations research · logistics · MBA placement"},
  {"id":"mgmt-operations-analytics-627","question":"A sales regression has strongly autocorrelated residuals: each month's error tends to have the same sign as the last. What value of the Durbin–Watson statistic would you expect, and what is the risk?","options":["Close to 0; standard errors are understated, so predictors look more significant than they are","Close to 2; there is no problem","Close to 4; the model has positive autocorrelation","Exactly 1; R² is overstated only"],"answer":0,"explanation":"DW ranges from 0 to 4: about 2 means no autocorrelation, near 0 positive and near 4 negative autocorrelation. Positive autocorrelation makes OLS standard errors too small, inflating t-statistics.","difficulty":"very-hard","source":"Business analytics · MBA placement"},
  {"id":"mgmt-operations-analytics-628","question":"A regression predicts store sales from advertising (₹ lakh) and footfall (thousands). The raw coefficients are 4.0 for advertising and 0.5 for footfall. A manager concludes that advertising matters eight times as much. What is wrong?","options":["Nothing, as coefficients directly measure importance","Coefficients depend on the units of each variable; importance should be compared with standardised coefficients or the effect of a typical (one-SD) change","Only the intercept shows importance","Footfall must matter more because it has a smaller coefficient"],"answer":1,"explanation":"A coefficient is the change in y per unit of x, so its size depends on how x is measured. If footfall varies by thousands while ad spend varies by a few lakh, footfall's one-SD effect may be far larger.","difficulty":"hard","source":"Business analytics · MBA placement"},
  {"id":"mgmt-operations-analytics-629","question":"In a demand model, regressing the predictor 'price' on all the other predictors gives R² = 0.90. What is the variance inflation factor (VIF) for price?","options":["1.11","0.10","10","9"],"answer":2,"explanation":"VIF = 1/(1 − R²ⱼ) = 1/0.10 = 10, so price's coefficient variance is ten times what it would be without collinearity, a common warning level. 1.11 uses 1/R², and 9 uses R²/(1 − R²).","difficulty":"hard","source":"Business analytics · MBA placement"},
  {"id":"mgmt-operations-analytics-630","question":"Two identical pumps run in active parallel, and the system works as long as at least one works. Each pump fails at a constant rate with an MTBF of 1,000 hours, and failed pumps are not repaired. What is the system's mean time to failure?","options":["2,000 hours","1,000 hours","500 hours","1,500 hours"],"answer":3,"explanation":"Time to the first failure averages 1/(2λ) = 500 hours, then the survivor lasts another 1/λ = 1,000 hours (memoryless): 1,500 hours. Adding the two MTBFs (2,000) wrongly assumes standby with no wear; 500 hours is the series result.","difficulty":"very-hard","source":"Operations · reliability · MBA placement"},
  {"id":"mgmt-operations-analytics-631","question":"A planner sets stock for a single season so that demand is fully met 95% of the time (critical ratio 0.95). Each unsold unit costs ₹10. In newsvendor terms, what shortage cost per unit is this policy implicitly assuming?","options":["₹190","₹200","₹9.50","₹10.53"],"answer":0,"explanation":"Critical ratio = Cu/(Cu + Co). Setting 0.95 = Cu/(Cu + 10) gives Cu = 10 × 0.95/0.05 = ₹190. Checking whether a lost sale really costs that much is a useful test of whether 95% is the right target.","difficulty":"very-hard","source":"Operations · inventory · MBA placement"},
  {"id":"mgmt-operations-analytics-632","question":"A fraud model gives each transaction a probability of fraud. Blocking a genuine transaction costs ₹500 in lost goodwill; letting a fraud through costs ₹5,000. Above what predicted probability should a transaction be blocked to minimise expected cost?","options":["50%","About 9.1%","10%","About 90.9%"],"answer":1,"explanation":"Block when p × 5,000 > (1 − p) × 500, i.e. p > 500/5,500 ≈ 9.1%. The default 50% cut-off ignores the unequal costs; 10% divides 500 by 5,000 without adding the two costs.","difficulty":"very-hard","source":"Business analytics · MBA placement"},
  {"id":"mgmt-operations-analytics-633","question":"An analyst runs k-means clustering on customers using annual spend (₹, ranging up to 5,00,000) and number of visits (ranging 1–50), without any transformation. What is the likely problem?","options":["k-means cannot handle two variables","Visits will dominate the clusters","Spend will dominate the distance calculation, so clusters reflect spend almost alone; the variables should be standardised first","The number of clusters will be set automatically"],"answer":2,"explanation":"k-means uses Euclidean distance, so a variable with a range of lakhs swamps one with a range of 50. Standardising (z-scores) or scaling gives each variable a fair weight.","difficulty":"hard","source":"Business analytics · MBA placement"},
  {"id":"mgmt-operations-analytics-634","question":"A2:A5 hold the weight slab limits 1, 2, 5 and 10 (kg), and B2:B5 the shipping rates 50, 80, 150 and 250. What does =XLOOKUP(2.3, A2:A5, B2:B5, \"n/a\", 1) return?","options":["80","\"n/a\"","5","150"],"answer":3,"explanation":"Match mode 1 means 'exact match, or the next larger item'. 2.3 is not in the list, so XLOOKUP takes 5 and returns 150. Match mode −1 (next smaller) would return 80; 5 is the slab itself, not the rate in column B.","difficulty":"hard","source":"Business analytics · Excel · MBA placement"},
  {"id":"mgmt-operations-analytics-635","question":"A test-and-repair station takes 4 minutes per pass. 25% of units fail the test and are sent back through the same station for a full 4-minute pass, and reworked units again fail 25% of the time. What is the station's capacity in good units per hour?","options":["15","12","11.25","20"],"answer":2,"explanation":"Expected passes per good unit = 1/(1 − 0.25) = 4/3, so each good unit takes 5.33 minutes: 60/5.33 = 11.25 per hour. 15 ignores rework, and 12 allows only a single rework (5 minutes).","difficulty":"very-hard","source":"Operations · capacity · MBA placement"},
  {"id":"mgmt-operations-analytics-636","question":"Inspecting a part costs ₹2, and a defective part that reaches the customer costs ₹100. The process's defect rate is a stable 3%. Under Deming's all-or-none rule, what should the firm do?","options":["Inspect none, since 3% is a low defect rate","Inspect a random 3%","Inspect 50%","Inspect 100%, since the defect rate exceeds the break-even rate of 2%"],"answer":3,"explanation":"Break-even p = inspection cost ÷ cost of an escaped defect = 2/100 = 2%. With p = 3% > 2%, 100% inspection costs less than letting defects escape; with a stable rate below 2%, no inspection would be cheaper. Partial sampling is never optimal under this rule.","difficulty":"very-hard","source":"Operations · quality · MBA placement"},
  {"id":"mgmt-operations-analytics-637","question":"A sales list in A2:A101 is filtered to show only North, and the analyst has also manually hidden some North rows. Which formula sums only the cells still visible?","options":["=SUBTOTAL(109, B2:B101)","=SUM(B2:B101)","=SUBTOTAL(9, B2:B101)","=AGGREGATE(9, 0, B2:B101)"],"answer":0,"explanation":"SUBTOTAL with function 9 ignores rows hidden by a filter but still counts manually hidden rows; 109 ignores both. SUM counts everything, and AGGREGATE with option 0 ignores only nested subtotals.","difficulty":"very-hard","source":"Business analytics · Excel · MBA placement"},
  {"id":"mgmt-operations-analytics-638","question":"A dashboard shows distinct active customers per month: January 3 (A, B, C), February 3 (A, B, D) and March 2 (A, E). A manager adds the monthly figures to report 8 distinct customers for the quarter. What is the correct figure?","options":["8","5","3","2.7"],"answer":1,"explanation":"Distinct counts are not additive: across the quarter the distinct customers are A, B, C, D and E = 5. Summing the months counts A three times and B twice. The quarter needs its own COUNT(DISTINCT), not a sum of months.","difficulty":"hard","source":"Business analytics · SQL · MBA placement"},
  {"id":"mgmt-operations-analytics-639","question":"A hospital needs nurses in six 4-hour periods around the clock: 4, 8, 10, 7, 12 and 4 (the last period runs into the first). Each nurse works an 8-hour shift covering two consecutive periods, starting at the beginning of any period. What is the minimum number of nurses?","options":["23","45","26","12"],"answer":2,"explanation":"Each nurse covers exactly one of periods 1, 3 and 5, so at least 4 + 10 + 12 = 26 nurses are needed, and 26 is achievable (for example 0, 8, 2, 5, 7, 4 nurses starting in periods 1–6). Half the total (23) ignores this structure, and 12 is just the peak.","difficulty":"very-hard","source":"Operations research · MBA placement"},
  {"id":"mgmt-operations-analytics-640","question":"A distributor shipped 200 orders with 800 order lines and 20,000 units. 10 orders were incomplete; they had 16 short lines totalling 600 units. What are the order, line and unit fill rates?","options":["95%, 98% and 97%","98%, 95% and 97%","97%, 98% and 95%","95%, 97% and 98%"],"answer":0,"explanation":"Order fill = 190/200 = 95%; line fill = 784/800 = 98%; unit fill = 19,400/20,000 = 97%. Order fill is the strictest, since one short line spoils the whole order.","difficulty":"hard","source":"Operations · supply chain · MBA placement"},
  {"id":"mgmt-operations-analytics-641","question":"A cement company adds a new kiln only after demand has clearly exceeded current capacity for some time, accepting some lost sales to keep utilisation high. Which capacity strategy is this?","options":["Lead strategy","Lag strategy","Match (tracking) strategy","Chase strategy"],"answer":1,"explanation":"A lag strategy adds capacity after demand has grown, maximising utilisation and cutting risk but losing some sales. A lead strategy builds ahead of demand, and match adds small increments as demand moves.","difficulty":"moderate","source":"Operations · capacity · MBA placement"},
  {"id":"mgmt-operations-analytics-642","question":"Goldratt's five focusing steps of the Theory of Constraints are listed out of order: P. Elevate the constraint  Q. Subordinate everything else to that decision  R. Identify the constraint  S. If the constraint is broken, go back to the start  T. Decide how to exploit the constraint. What is the correct order?","options":["R, P, T, Q, S","R, Q, T, P, S","R, T, Q, P, S","T, R, Q, P, S"],"answer":2,"explanation":"Identify → exploit (get the most from it without spending) → subordinate (pace everything else to it) → elevate (add capacity) → repeat, without letting inertia set in. Elevating before exploiting wastes money on capacity the plant may not need.","difficulty":"hard","source":"Operations · TOC · MBA placement"},
  {"id":"mgmt-operations-analytics-643","question":"A warehouse cycle-counts its 2,000 SKUs by ABC class: 100 A items are counted monthly, 300 B items quarterly and 1,600 C items once a year. With 250 working days a year, about how many SKU counts must be done each working day?","options":["8","16","12","20"],"answer":1,"explanation":"Counts a year = 100 × 12 + 300 × 4 + 1,600 × 1 = 1,200 + 1,200 + 1,600 = 4,000, so 4,000/250 = 16 a day. Counting every SKU once a year would need only 8 a day, but it would give A items too little attention.","difficulty":"moderate","source":"Operations · inventory · MBA placement"},
];

export default questions;
